import builtins
import json
from pathlib import Path

import numpy as np
import pytest
from evaluate_native_camera_development import binding, reuse_completed_joint_predictions

from demosaic.prediction_archive import PredictionArchive, fingerprint, iter_predictions


@pytest.fixture
def partial(tmp_path):
    dataset = {"rows": [], "observations": []}
    values = []
    for index in range(2):
        target = np.full((1, 3, 16, 16), 0.1 + index * 0.01, np.float32)
        path = tmp_path / f"target{index}.npy"
        np.save(path, target)
        data = {
            "target": target,
            "wb": np.ones((1, 3), np.float32),
            "matrix": np.eye(3, dtype=np.float32)[None],
        }
        identity = f"case{index}"
        dataset["rows"].append({"case_id": identity, "reference_camera_FP32": binding(path)})
        observation = {
            "id": identity,
            "case_id": identity,
            "arrays": binding(path),
            "input_fingerprints": {key: fingerprint(data[key]) for key in ("wb", "matrix")},
        }
        dataset["observations"].append(observation)
        values.append(data)
    path = tmp_path / "dataset.json"
    path.write_text(json.dumps(dataset))
    methods = [
        {"label": label, "kind": "joint", "checkpoint": {"sha256": str(i + 1) * 64}}
        for i, label in enumerate(("V114", "V115", "V117", "V119"))
    ]
    archive = PredictionArchive(tmp_path / "original")
    for method in methods:
        model = {
            "label": method["label"],
            "kind": "joint",
            "step": 20000,
            "self_ensemble": "none",
            "sha256": method["checkpoint"]["sha256"],
        }
        for observation, data in zip(dataset["observations"], values, strict=True):
            context = {
                **observation,
                "ids": [observation["id"]],
                "input_arrays": observation["arrays"],
            }
            archive.append(model, context, data["target"] + np.float32(0.001), data)
    previous = tmp_path / "execution.json"
    previous.write_text(json.dumps({"dataset_manifest": binding(path), "methods": methods}))
    failure = tmp_path / "failure.json"
    failure.write_text(
        json.dumps(
            {
                "execution_plan": binding(previous),
                "actual_tracking": {
                    "method": "RawNIND-preup",
                    "started_root_calls": 8,
                    "completed_valid_root_calls": 8,
                    "encoder_calls": 8,
                    "reference_network_calls": 0,
                },
            }
        )
    )
    plan = {
        "methods": methods,
        "dataset_manifest": binding(path),
        "retained_collection": {
            "execution_plan": binding(previous),
            "failure": binding(failure),
            "archive": binding(archive.manifest),
        },
    }
    return plan, dataset, archive


def test_partial_archive_reuse_preserves_bytes_and_never_imports_model_code(
    partial, tmp_path, monkeypatch
):
    plan, dataset, original = partial
    before = original.manifest.read_bytes()
    recovered = PredictionArchive(tmp_path / "recovered")
    original_import = builtins.__import__

    def forbid(name, *args, **kwargs):
        if name == "torch" or name.startswith(("demosaic.inference", "demosaic.model")):
            raise AssertionError("Prediction reuse must not load a model")
        return original_import(name, *args, **kwargs)

    monkeypatch.setattr(builtins, "__import__", forbid)
    result = reuse_completed_joint_predictions(plan, dataset, recovered)
    assert sum(r["new_root_calls"] for r in result) == 0
    assert sum(r["reused_prediction_count"] for r in result) == 8
    assert original.manifest.read_bytes() == before
    for (old, old_pixels, _), (new, new_pixels, _) in zip(
        iter_predictions(original.manifest), iter_predictions(recovered.manifest), strict=True
    ):
        assert old["prediction"]["sha256"] == new["prediction"]["sha256"]
        assert old["context"] == new["context"] and np.array_equal(old_pixels, new_pixels)


@pytest.mark.parametrize("damage", ["completed_reference", "changed_input"])
def test_recovery_refuses_unsupported_failure_or_observation(partial, tmp_path, damage):
    plan, dataset, _ = partial
    if damage == "completed_reference":
        path = plan["retained_collection"]["failure"]["path"]
        data = json.loads(Path(path).read_text())
        data["actual_tracking"]["reference_network_calls"] = 1
        with open(path, "w") as stream:
            json.dump(data, stream)
        plan["retained_collection"]["failure"] = binding(path)
    else:
        dataset["observations"][0]["input_fingerprints"] = {}
    with pytest.raises(AssertionError):
        reuse_completed_joint_predictions(plan, dataset, PredictionArchive(tmp_path / "rejected"))

"""Ordered FP32 closure and new replay/counter validation; no quality fixture."""

import copy

import numpy as np
import pytest
from audit_pooled_phase_quality import native_addition, validate_stream
from train_pooled_phase_trial import METHODS


def test_ordered_wave_addition_must_not_regroup_older_corrections():
    old = np.full((1, 3, 2, 2), np.float32(1))
    old_correction = np.full_like(old, -1)
    wave = np.full_like(old, 2**-25)
    inherited = old + old_correction
    value = inherited + wave
    assert not np.array_equal(value, old + (old_correction + wave))
    assert native_addition(value, inherited, wave) == 12
    with pytest.raises(AssertionError):
        native_addition(old + (old_correction + wave), inherited, wave)


@pytest.mark.parametrize("change", ["dtype", "shape", "nan"])
def test_invalid_native_arrays_are_rejected(change):
    inherited = np.zeros((1, 3, 2, 2), np.float32)
    wave = np.zeros_like(inherited)
    value = inherited.copy()
    if change == "dtype":
        wave = wave.astype(np.float64)
    if change == "shape":
        wave = wave[..., :1]
    if change == "nan":
        value[0, 0, 0, 0] = np.nan
    with pytest.raises(ValueError):
        native_addition(value, inherited, wave)


def schema_fixture(monkeypatch):
    # This stubs the independently tested legacy evidence validator. Every
    # input/prediction below is a labeled structural stand-in, not native quality.
    import audit_pooled_phase_quality as audit

    monkeypatch.setattr(audit, "validate_evidence", lambda *args: None)
    monkeypatch.setattr(audit, "validate_support", lambda *args: None)
    monkeypatch.setattr(audit, "validate_pooled", lambda *args: None)
    counts = {"wrapper": 1644, "frozen": 1644, "network": 1500, "sampler": 7500, "projection": 1500}
    plan = {
        "processing_order": list(range(822)),
        "expected_quality_counts": counts,
        "module_config": {},
    }
    design = []
    inputs = {}
    baseline = {}
    frozen = {}
    events = []
    journal = []
    rows = []
    for index in range(822):
        cid = f"schema-fixture-{index}"
        case = {"id": cid, "arrays": {"fixture": index}, "parent": {"fixture_parent": index}}
        design.append(case)
        noisy = index < 750
        inputs[cid] = {
            "noisy": noisy,
            "fingerprints": {
                k: {"fixture": index, "kind": k} for k in ["packed", "variance", "colors", "wb"]
            },
            "packed_shape": [1, 4, 8, 8],
            "colors": [[0, 1, 1, 2]],
        }
        baseline[cid] = {"values": {"fixture_V183": index}}
        frozen[cid] = {"values": {"fixture_V169": index} if noisy else baseline[cid]["values"]}
    running = {k: 0 for k in counts}
    head = 0
    for method in METHODS.values():
        for index, case in enumerate(design):
            cid = case["id"]
            noisy = inputs[cid]["noisy"]
            row = {
                "id": cid,
                "method": method,
                "index": index,
                "values": {"fixture_new": index} if noisy else baseline[cid]["values"],
                "inherited_values": copy.deepcopy(baseline[cid]["values"]),
                "frozen_values": copy.deepcopy(frozen[cid]["values"]),
                "inherited_V183_EMA_replay_exact": True,
                "frozen_V169_replay_exact": True,
                "ADC_exact": not noisy,
                "wave_correction_RMS_DN16": 0.1 if noisy else 0.0,
            }
            record = {
                "method": method,
                "index": index,
                "id": cid,
                "arrays": case["arrays"],
                "parent": case["parent"],
                "inputs": copy.deepcopy(inputs[cid]["fingerprints"]),
                "row": row,
                "evidence": {"fixture_evidence": index} if noisy else None,
                "support": {"fixture_support": index} if noisy else None,
                "pooled": {"selection": {"fixture_pooled": index}} if noisy else None,
                "inherited_replay_exact": True,
                "frozen_replay_exact": True,
                "baseline_plus_wave_closure_exact": True,
            }
            for key in running:
                running[key] += (
                    5 * int(noisy)
                    if key == "sampler"
                    else (1 if key in ["wrapper", "frozen"] else int(noisy))
                )
            head += int(noisy)
            events.append(
                {
                    "method": method,
                    "index": index,
                    "ordinal": index,
                    "id": cid,
                    "matching_evaluated": noisy,
                    "counts": running.copy(),
                    "readout_calls": head,
                }
            )
            rows.append(row)
            journal.append(record)
    scores = {
        "rows": rows,
        "counts": counts,
        "readout_calls": 1500,
        "ADC_outputs_exact_V169": 144,
        "exact_V183_EMA_replays": 1644,
        "exact_V169_replays": 1644,
        "weights_unchanged": True,
        "RNG_unchanged": True,
    }
    return plan, scores, design, events, journal, inputs, baseline, frozen


def test_new_stream_schema_accepts_both_replays_and_all_head_calls(monkeypatch):
    check = validate_stream(*schema_fixture(monkeypatch))
    assert check["input_fingerprints"] == 6576 and check["readout_calls"] == 1500
    assert check["exact_input_only_raw_EMA_evidence_pairs"] == 750


@pytest.mark.parametrize(
    "change",
    [
        "baseline",
        "frozen",
        "input",
        "head_calls",
        "ADC",
        "closure",
        "evidence_pair",
        "support_pair",
    ],
)
def test_altered_new_stream_contract_is_rejected(monkeypatch, change):
    data = schema_fixture(monkeypatch)
    if change == "baseline":
        data[4][0]["row"]["inherited_values"] = {"wrong": 1}
    if change == "frozen":
        data[4][0]["row"]["frozen_values"] = {"wrong": 1}
    if change == "input":
        data[4][0]["inputs"]["packed"] = {"wrong": 1}
    if change == "head_calls":
        data[3][0]["readout_calls"] = 0
    if change == "ADC":
        data[4][750]["row"]["wave_correction_RMS_DN16"] = 0.1
    if change == "closure":
        data[4][0]["baseline_plus_wave_closure_exact"] = False
    if change == "support_pair":
        data[4][822]["support"] = {"different": 1}
    if change == "evidence_pair":
        data[4][822]["evidence"] = {"different": True}
    with pytest.raises(AssertionError):
        validate_stream(*data)

"""Exercise the future five-control handoff without model inference or saved weights."""

from copy import deepcopy

import pytest
from bind_patch_memory_review import (
    CONTROL_LABELS,
    inherit_controls,
    matching_batches,
    require_completed_training,
    require_training_result,
)


def comparison_inputs():
    def control(label):
        return {"model": {"label": label}, "prediction": {"path": label, "sha256": label}}

    declared = [
        {
            "id": str(i),
            "ROI_xywh": [48, 48, 160, 160],
            "noise": {"shot": 0, "read": 0},
            "display_exposure": 1,
            "input_fingerprints": {"packed": "saved-input"},
            "controls": [control(label) for label in CONTROL_LABELS[:4]],
        }
        for i in range(2)
    ]
    inherited = deepcopy(declared)
    for observation in inherited:
        observation["controls"].append(control(CONTROL_LABELS[-1]))
    predictions = [
        {"id": str(i), "prediction": {"path": "V139", "sha256": "V139"}} for i in range(2)
    ]
    return declared, inherited, predictions, {"sha256": "V139-checkpoint"}


def identity_ref(path):
    return {"path": path, "sha256": path}


@pytest.mark.parametrize("profile", ["mesh-nominal", "mesh-profile3879"])
def test_preserves_legacy_mesh_V120_metadata_and_profile_label(profile):
    declared, inherited, predictions, checkpoint = comparison_inputs()
    label = "V120-profile3879" if profile == "mesh-profile3879" else "V120"
    legacy = {
        "label": label,
        "checkpoint": "saved-V120",
        "prediction": {"path": "V120", "sha256": "V120"},
    }
    for collection in (declared, inherited):
        collection[0].update(id=profile, kind="mesh")
        collection[0]["controls"][0] = deepcopy(legacy)
    predictions[0]["id"] = profile
    result = inherit_controls(declared, inherited, predictions, checkpoint, checked=identity_ref)
    assert result[0]["controls"][0] == legacy
    assert result[0]["controls"][4]["model"]["label"] == "V138 1k EMA"
    assert result[0]["controls"][5]["model"]["label"] == "V139 1k EMA"


def test_adopts_inherited_fifth_control_then_new_prediction_without_mutating_inputs():
    inputs = comparison_inputs()
    saved = deepcopy(inputs)
    result = inherit_controls(*inputs, checked=identity_ref)
    assert inputs == saved
    assert len(result) == 2
    for observation in result:
        assert [c["model"]["label"] for c in observation["controls"]] == CONTROL_LABELS + [
            "V139 1k EMA"
        ]
        assert observation["controls"][-1] == {
            "model": {"label": "V139 1k EMA", "sha256": "V139-checkpoint", "step": 1000},
            "prediction": {"path": "V139", "sha256": "V139"},
        }
        assert "label" not in observation["controls"][-1]
        assert observation["ROI_xywh"] == [48, 48, 160, 160]


@pytest.mark.parametrize("field", ["ROI_xywh", "noise", "display_exposure", "input_fingerprints"])
def test_rejects_changed_observation_support(field):
    declared, inherited, predictions, checkpoint = comparison_inputs()
    inherited[0][field] = "changed"
    with pytest.raises(AssertionError):
        inherit_controls(declared, inherited, predictions, checkpoint, checked=identity_ref)


@pytest.mark.parametrize(
    "change",
    [
        "prefix",
        "fifth_label",
        "stale_label",
        "missing_tail",
        "duplicate",
        "order",
        "prediction_id",
        "hash",
    ],
)
def test_rejects_missing_replaced_or_mislabeled_control(change):
    declared, inherited, predictions, checkpoint = comparison_inputs()
    if change == "prefix":
        inherited[0]["controls"][0]["prediction"]["sha256"] = "changed"
    elif change == "fifth_label":
        inherited[0]["controls"][4]["model"]["label"] = "V137 1k EMA"
    elif change == "stale_label":
        inherited[0]["controls"][4]["label"] = "V120"
    elif change == "missing_tail":
        inherited[0]["controls"].pop()
    elif change == "duplicate":
        declared[1]["id"] = declared[0]["id"]
    elif change == "order":
        inherited.reverse()
    elif change == "prediction_id":
        predictions[1]["id"] = predictions[0]["id"]
    else:
        predictions[0]["prediction"]["sha256"] = "changed"
    with pytest.raises(AssertionError):
        inherit_controls(declared, inherited, predictions, checkpoint, checked=identity_ref)


def test_requires_exact_original_training_owner_and_completed_receipt():
    queue = {"training_plan": {"sha256": "plan"}, "training_owner": {"pid": 10, "created": 2}}
    status = {
        "plan": queue["training_plan"],
        "controller": queue["training_owner"],
        "status": "completed-training-awaiting-model-comparisons",
        "child": None,
        "completed": {"train-V140": {"path": "result", "sha256": "result"}},
    }
    with pytest.raises(AssertionError, match="still live"):
        require_completed_training(status, queue, True)
    assert require_completed_training(status, queue, False) == status["completed"]["train-V140"]
    for field, value in [
        ("controller", {"pid": 11, "created": 2}),
        ("plan", {}),
        ("status", "running"),
    ]:
        changed = {**status, field: value}
        with pytest.raises(AssertionError):
            require_completed_training(changed, queue, False)


