    assert output.verify_alignment()["models"] == 3
    for old, new in zip(
        iter_predictions(archive.manifest), iter_predictions(output.manifest), strict=True
    ):
        assert old[0]["prediction"]["sha256"] == new[0]["prediction"]["sha256"]
