            changed[name].flatten()[0] = False
        else:
            changed[name].flatten()[0] += 1 / 65536
        assert batch_fingerprint(changed) != expected
    altered["packed"] = batch["packed"].bfloat16()
    assert batch_fingerprint(altered) != expected

