                            (
                                "in_phase_gain",
                                "gain_channel_std",
                                "quadrature_gain",
                                "amplitude_ratio",
                                "dc_bias_abs",
                                "noncarrier_rms",
                                "linear_srgb_rmse",
                            )
                            if kind == "carrier"
                            else (
                                "dc_bias_abs_rgb",
                                "linear_srgb_rmse",
                                "spatial_luma_rms",
                                "relative_band_rms",
                                "relative_peak_band_contrast",
                            )
                        )
                        metrics = dict.fromkeys(fields, 0.0)
                        if kind == "carrier":
                            metrics.update(
                                in_phase_gain=0.05 if model == "bank" else 0.0, amplitude_ratio=1.0
                            )
                        else:
                            metrics["spatial_luma_rms"] = 0.005 if model == "bank" else 0.004
                        rows.append(
                            {
                                "kind": kind,
                                "level": level,
                                "contrast": contrast,
                                "period": period,
                                "condition": condition,
                                "pattern": pattern,
                                "draw": draw,
                                "model": model,
                                "metrics": metrics,
                            }
                        )
    summarize(summary, rows)
    return summary, rows, control, bank


