        "expected_quality_counts": {
            "wrapper": 12,
            "frozen": 12,
            "network": 8,
            "sampler": 40,
            "projection": 4,
        },
    }
    inputs = {
        case["id"]: {
            "noisy": case["id"] != "ADC",
            "packed_shape": [1, 4, 16, 16],
            "colors": [[0, 1, 1, 2]],
            "fingerprints": {
                key: case["id"] + key for key in ["packed", "variance", "colors", "wb"]
