                    row["noise"] = case["noise"]["name"]
                rows.append(row)
                events.append(
                    {
                        "method": method,
                        "index": index,
                        "id": case["id"],
                        "ordinal": ordinal,
                        "counts": dict(counts),
                        "matching_evaluated": noisy,
                    }
                )
