PLAN = {"path": "/frozen/plan.json", "sha256": "a" * 64}
OWNER = {"pid": 111, "created": 1.0}
CHILD = {"pid": 222, "created": 2.0}


def state():
    return {
        "plan": copy.deepcopy(PLAN),
        "controller": copy.deepcopy(OWNER),
        "child": copy.deepcopy(CHILD),
        "status": TERMINAL,
        "completed": dict.fromkeys(KEYS),
    }


@pytest.mark.parametrize("live_owners", [[], [OWNER], [CHILD], [OWNER, CHILD]])
def test_complete_coverage_releases_only_after_both_exact_owners_exit(live_owners):
    assert training_ready(state(), PLAN, OWNER, is_live=lambda owner: owner in live_owners) is (
        not live_owners
    )


def test_running_training_waits_while_its_controller_is_alive():
    current = state()
    current.update(status="running-ADC-training-stage", completed={})
    assert not training_ready(current, PLAN, OWNER, is_live=lambda owner: owner == OWNER)
    with pytest.raises(AssertionError, match="exited before completion"):
        training_ready(current, PLAN, OWNER, is_live=lambda owner: owner == CHILD)


@pytest.mark.parametrize("damage", ["plan", "PID-reuse", "failed", "missing", "extra"])
def test_wrong_identity_failed_or_incomplete_training_cannot_release(damage):
    current = state()
    if damage == "plan":
        current["plan"]["sha256"] = "b" * 64
    elif damage == "PID-reuse":
        current["controller"]["created"] += 1
    elif damage == "failed":
        current["status"] = "failed-ADC-training-preserved-no-automatic-retry"
    elif damage == "missing":
        current["completed"].pop("train-V99")
    else:
        current["completed"]["train-V100"] = None
    with pytest.raises(AssertionError):
        training_ready(current, PLAN, OWNER, is_live=lambda owner: False)


@pytest.mark.parametrize("damage", [None, "bytes", "plan", "arm", "engineering", "owner"])
def test_all_six_result_receipts_are_checked_before_audits(tmp_path, monkeypatch, damage):
    current = state()
    for key in KEYS:
        phase, arm = key.split("-")
        result = {
            "phase": phase,
            "arm": arm,
            "plan": PLAN,
            "engineering_only": phase != "train",
            "owner": CHILD,
        }
        if key == "train-V99":
            if damage == "plan":
                result["plan"] = {}
            elif damage == "arm":
                result["arm"] = "V98"
            elif damage == "engineering":
                result["engineering_only"] = True
        path = tmp_path / f"{key}.json"
        save(path, result)
        current["completed"][key] = ref(path)
        if damage == "bytes" and key == "train-V99":
            path.write_text(path.read_text() + "\n")
    monkeypatch.setattr("queue_v95_adc_quality.live", lambda owner: damage == "owner")
    if damage is None:
        completed_results(current, PLAN)
    else:
        with pytest.raises(AssertionError):
            completed_results(current, PLAN)

import numpy as np
import pytest
from dense_measurement_support import METHODS, cases, measure, target_frequencies, ratios
from dense_support_reference import reference


@pytest.mark.parametrize("method", list(METHODS))
@pytest.mark.parametrize("position", ["interior", "corner"])
@pytest.mark.parametrize("noise", ["uniform", "graded"])
def test_weighted_plane_operator_and_SNR_match_independent_QR(method, position, noise):
    for case in cases():
        if (
            case["method"] == method
            and case["position"] == position
            and case["noise"] == noise
            and case["target"] in [0, 13, 47]
        ):
            a, b = measure(case), reference(case)
            for key, value in b.items():
                np.testing.assert_allclose(a[key], value, rtol=2e-11, atol=2e-11)
            assert a["maximum_affine_annihilation_error"] < 1e-12


def test_fixed_target_grid_and_closed_case_cross():
    targets = target_frequencies()
    spec = cases()
    assert len(targets) == 48 and len(spec) == 1152 and len(set(c["id"] for c in spec)) == 1152
    for target in targets:
        fy, fx = target["native_fyx"]
        assert 1 / 16 < np.hypot(fy, fx) < 1 / 3 and abs(fy) < 0.25 and abs(fx) < 0.25
    assert len(set(tuple(t["native_fyx"]) for t in targets)) == 48


def test_unfitted_effective_support_exact_counts():
    for method, expected in [
        ("rect65_grid256", 4225),
        ("hann65_grid65", 16384 / 9),
        ("hann129_grid129", 65536 / 9),
    ]:
        case = next(c for c in cases() if c["method"] == method and c["position"] == "interior")
        assert measure(case)["raw_taper_effective_sample_count_without_affine"] == pytest.approx(
            expected
        )


def test_exact_frequency_quantization_changes_only_carrier_not_target():
    specs = [
        c
        for c in cases()
        if c["target"] == 1 and c["position"] == "interior" and c["noise"] == "uniform"
    ]
    result = ratios([measure(c) for c in specs], specs)
    assert len(result) == 4
    nearest = next(
        c
        for c in specs
        if c["method"] == "hann65_grid65" and c["mode"] == "nearest_available_carrier"
    )
    exact = dict(nearest, mode="exact_frequency")
    assert (
        measure(nearest)["phase_averaged_signal_to_noise_power"]
        < measure(exact)["phase_averaged_signal_to_noise_power"]
    )

import hashlib
import io
import urllib.error

import pytest

from demosaic import paired


def descriptor(filename, payload=b"raw sensor bytes"):
    return {
        "filename": filename,
        "bytes": len(payload),
        "publisher_checksum": {"type": "MD5", "value": hashlib.md5(payload).hexdigest()},
        "sha1": hashlib.sha1(payload).hexdigest(),
        "url": paired.DATA_URL + "1",
    }


def fixture_catalog(scene="development", reserved=False):
    clean = [{"filename": f"Bayer_{scene}_GT_ISO100_sha1={'0' * 40}.arw", "sha1": "0" * 40}]
    noisy = [
        {"filename": f"Bayer_{scene}_ISO{iso}_sha1={'0' * 40}.arw", "sha1": "0" * 40}
        for iso in (400, 1600, 6400, 12800, 25600)
    ]
    dataset = {
        "Bayer": {
            scene: {
                "test_reserve": reserved,
                "unknown_sensor": reserved,
                "clean_images": clean,
                "noisy_images": noisy,
            }
        }
    }
    files = [
        {
            "restricted": False,
            "dataFile": {
                "filename": row["filename"],
                "id": i + 1,
                "filesize": 16,
                "checksum": {"type": "MD5", "value": "0" * 32},
            },
        }
        for i, row in enumerate(clean + noisy)
    ]
    return dataset, files


def test_selection_is_metadata_only_and_keeps_publisher_test_reserve_separate():
    dataset, files = fixture_catalog()
    dataset["Bayer"]["development"]["clean_images"].append(
        {
            "filename": "Bayer_development_GT_ISOUnknown_sha1=unknown.xmp",
            "sha1": "0" * 40,
        }
    )
    result = paired.select_pairs(dataset, files, "development", scenes=["development"])
    assert [r["iso_label"] for r in result[0]["noisy"]] == [1600, 12800]
    assert len(result[0]["clean"]) == 1
    with pytest.raises(ValueError, match="other split"):
        paired.select_pairs(dataset, files, "test", scenes=["development"])
    dataset, files = fixture_catalog("reserved", reserved=True)
    result = paired.select_pairs(dataset, files, "test")
    assert result[0]["unknown_sensor"] and result[0]["scene"] == "reserved"
    with pytest.raises(ValueError, match="other split"):
        paired.select_pairs(dataset, files, "development", scenes=["reserved"])
    # Corrected filename prefixes protect against obsolete publisher split flags.
    dataset, files = fixture_catalog("TEST_protected", reserved=False)
    with pytest.raises(ValueError, match="other split"):
        paired.select_pairs(dataset, files, "development", scenes=["TEST_protected"])


def test_training_selection_cannot_include_validation_test_or_unknown_sensor():
    dataset, files = fixture_catalog("sewingmachine")
    assert paired.select_pairs(dataset, files, "train", scenes=["sewingmachine"])
    dataset["Bayer"]["sewingmachine"]["unknown_sensor"] = True
    with pytest.raises(ValueError, match="fixed training selection"):
        paired.select_pairs(dataset, files, "train", scenes=["sewingmachine"])
    for name in ("2pilesofplates", "LucieB_3apples", "7D-2"):
        dataset, files = fixture_catalog(name)
        with pytest.raises(ValueError, match="fixed training selection"):
            paired.select_pairs(dataset, files, "train", scenes=[name])
    dataset, files = fixture_catalog("sewingmachine", reserved=True)
    with pytest.raises(ValueError, match="other split"):
        paired.select_pairs(dataset, files, "train", scenes=["sewingmachine"])


def test_verified_download_reuses_bytes_without_network(tmp_path, monkeypatch):
    payload = b"raw sensor bytes"
    record = descriptor("example.arw", payload)
    monkeypatch.setattr(
        paired.urllib.request, "urlopen", lambda *args, **kwargs: io.BytesIO(payload)
    )
    result = paired.download_file(tmp_path, record)
    assert result["sha256"] == hashlib.sha256(payload).hexdigest()
    assert (tmp_path / "example.arw").read_bytes() == payload

    def unavailable(*args, **kwargs):
        raise AssertionError("A verified existing file must not be downloaded again")

    monkeypatch.setattr(paired.urllib.request, "urlopen", unavailable)
    assert paired.download_file(tmp_path, record) == result


def test_invalid_existing_download_is_preserved(tmp_path):
    path = tmp_path / "example.arw"
    path.write_bytes(b"existing bytes")
    with pytest.raises(ValueError, match="checksum mismatch"):
        paired.download_file(tmp_path, descriptor(path.name))
    assert path.read_bytes() == b"existing bytes"


@pytest.mark.parametrize("network_failure", [False, True])
def test_failed_download_cleans_only_its_own_temporary_files(
    tmp_path, monkeypatch, network_failure
):
    record = descriptor("example.arw")
    marker = tmp_path / "unrelated.part"
    marker.write_bytes(b"keep")

    def failed(*args, **kwargs):
        if network_failure:
            raise urllib.error.URLError("offline")
        return io.BytesIO(b"different payload")

    monkeypatch.setattr(paired.urllib.request, "urlopen", failed)
    monkeypatch.setattr(paired.time, "sleep", lambda seconds: None)
    with pytest.raises((ValueError, urllib.error.URLError)):
        paired.download_file(tmp_path, record)
    assert sorted(p.name for p in tmp_path.iterdir()) == ["unrelated.part"]
    assert marker.read_bytes() == b"keep"


def test_publisher_filename_cannot_escape_download_directory(tmp_path):
    with pytest.raises(ValueError, match="Unsafe publisher filename"):
        paired.download_file(tmp_path, descriptor("../escape.arw"))
    assert not list(tmp_path.iterdir())

