"""Pair independently audited endpoints with identical inputs and supervision.

Only saved archive metadata and independently rebuilt scores are read. Network
execution, observation generation and model selection are outside this tool.
"""

import argparse
import hashlib
import json
from collections import defaultdict
from pathlib import Path

import numpy as np
from audit_quality_archive import binding, paired_changes, write

from demosaic.safety import writable_path

STAGES = ("photo", "known", "unseen", "texture", "color")
METHOD_FIELDS = {"model", "model_index", "checkpoint_sha256", "metrics", "self_ensemble"}


def canonical(value):
    return json.dumps(value, sort_keys=True, allow_nan=False, separators=(",", ":"))


def read_bound(item):
    if binding(item["path"]) != item:
        raise ValueError(f"Changed comparison input: {item['path']}")
    return json.loads(Path(item["path"]).read_text())


def identity(sha256, policy="none"):
    if (not isinstance(sha256, str) or len(sha256) != 64
            or any(c not in "0123456789abcdef" for c in sha256)
            or policy not in {"none", "dihedral8"}):
        raise ValueError("Declare the exact checkpoint and inference policy")
    return {"sha256": sha256, "self_ensemble": policy}


def normalize_row(row, stage):
    result = dict(row)
    if stage in {"known", "unseen"}:
        # Early arithmetic proofs omitted an explicit pair field. The prepared
        # dataset ID encodes it unambiguously; production rows already carry it.
        fields = result["tile_id"].rsplit(":", 3)
        if (len(fields) != 4 or fields[0] != result["scene"] or len(fields[1]) != 64
                or any(c not in "0123456789abcdef" for c in fields[1])
                or not all(value.isdigit() for value in fields[2:])):
            raise ValueError("Camera tile ID does not identify its scene/capture/coordinates")
        if result.get("pair", fields[1]) != fields[1]:
            raise ValueError("Camera capture differs from its tile ID")
        result["pair"] = fields[1]
    return result


def row_key(row):
    return canonical({key: value for key, value in row.items() if key not in METHOD_FIELDS})


def audited_model(path, selected, stage):
    audit_binding = binding(path)
    audit = read_bound(audit_binding)
    if audit["stage"] != stage:
        raise ValueError("Independent audit stage differs")
    report = read_bound(audit["report"])
    models = report["checkpoints" if stage == "color" else "models"]
    matches = [(i, model) for i, model in enumerate(models)
               if model.get("sha256") == selected["sha256"]
               and model.get("self_ensemble", "none") == selected["self_ensemble"]]
    if len(matches) != 1:
        raise ValueError("Checkpoint/policy is missing or ambiguous in audited report")
    index, model = matches[0]
    label = index if stage == "color" else model["label"]
    rows = [normalize_row(row, stage) for row in read_bound(audit["independent_rows"])
            if row["checkpoint_sha256"] == selected["sha256"]
            and row["model_index" if stage == "color" else "model"] == label]
    indexed = {row_key(row): row for row in rows}
    if not rows or len(indexed) != len(rows):
        raise ValueError("Missing or duplicate independent observations")
    if binding(audit["manifest"]["path"]) != audit["manifest"]:
        raise ValueError("Changed archive manifest")
    contexts, archive_label = {}, None
    for expected_index, line in enumerate(Path(audit["manifest"]["path"]).read_text().splitlines()):
        record = json.loads(line)
        if record["schema"] != "demosaic-predictions-v1" or record["index"] != expected_index:
            raise ValueError("Archive sequence differs from its audited schema")
        if any(record["model"][key] != value for key, value in selected.items()):
            continue
        if archive_label is None:
            archive_label = record["model"]["label"]
        if archive_label != record["model"]["label"]:
            raise ValueError("Selected archive model label changed")
        context = record["context"]
        if context["stage"] != stage or not context.get("input_fingerprints"):
            raise ValueError("Missing or inconsistent archived observation context")
        key = canonical({k: v for k, v in context.items() if k != "input_fingerprints"})
        if key in contexts:
            raise ValueError("Duplicate archived observation context")
        contexts[key] = {"ids": context["ids"], "inputs": context["input_fingerprints"],
                         "supervision": record["supervision_values"]}
    observations = sum(len(value["ids"]) for value in contexts.values())
    if (not contexts or observations != len(rows)
            or audit["observations"].get(archive_label) != observations):
        raise ValueError("Selected archive and independent rows have different coverage")
    return {"audit": audit_binding, "report": audit["report"], "manifest": audit["manifest"],
            "independent_rows": audit["independent_rows"], "model": selected,
            "contexts": contexts, "rows": indexed, "observations": observations,
            "native_triplets": audit["native_triplets"]}


def metric_delta(candidate, control):
    if candidate is None or control is None:
        if candidate is not None or control is not None:
            raise ValueError("Only one method has a missing score")
        return None
    a, b = np.asarray(candidate, np.float64), np.asarray(control, np.float64)
    if a.shape != b.shape or not np.isfinite(a).all() or not np.isfinite(b).all():
        raise ValueError("Nonfinite or differently shaped comparison metrics")
    value = a - b
    return float(value) if value.ndim == 0 else value.tolist()


def scalar_contrast(candidate, control, stage, metric, bootstrap_draws):
    if stage == "photo":
        candidate = [row for row in candidate if row["kind"] == "photo"]
        control = [row for row in control if row["kind"] == "photo"]
    accepted = [i for i, (a, b) in enumerate(zip(candidate, control, strict=True))
                if a["metrics"][metric] is not None and b["metrics"][metric] is not None]
    missing = len(candidate) - len(accepted)
    if not accepted:
        return {"metric": metric, "shared_invalid_observations": missing, "available": False}
    result = paired_changes([candidate[i] for i in accepted], [control[i] for i in accepted],
                            stage=stage, metric=metric, bootstrap_draws=bootstrap_draws)
    return {**result, "shared_invalid_observations": missing, "available": True}


def analytic_groups(rows, stage):
    groups = defaultdict(list)
    fields = ("kind", "level", "contrast", "period", "condition") if stage == "texture" else ("condition", "palette")
    for row in rows:
        groups[canonical({key: row[key] for key in fields})].append(row)
    result = []
    for key, group in sorted(groups.items()):
        methods = {}
        for method in ("control", "candidate"):
            if stage == "color":
                bias = [max(map(abs, row[method]["camera_RGB_mean_error"])) * 65535 for row in group]
                spatial = [row[method]["spatially_centered_camera_RGB_RMS"] * 65535 for row in group]
                worst = int(np.argmax(bias))
                methods[method] = {"mean_max_channel_bias_DN16": float(np.mean(bias)),
                                   "p95_max_channel_bias_DN16": float(np.quantile(bias, .95)),
                                   "max_channel_bias_DN16": float(max(bias)),
                                   "mean_centered_RGB_RMS_DN16": float(np.mean(spatial)),
                                   "worst_observation": group[worst]["observation"]}
            else:
                methods[method] = {metric: {"mean": float(np.mean([r[method][metric] for r in group])),
                                             "maximum": float(np.max([r[method][metric] for r in group]))}
                                   for metric in group[0][method]}
                if group[0]["kind"] == "carrier":
                    methods[method]["absolute_gain_error_from_one"] = {
                        "mean": float(np.mean([abs(r[method]["in_phase_gain"] - 1) for r in group]))}
        result.append({"group": json.loads(key), "observations": len(group), **methods})
    return result


def compare_stage(control_audit, candidate_audit, control_model, candidate_model, *, stage,
                  expected_observations=None, bootstrap_draws=10000):
    if stage not in STAGES:
        raise ValueError("Compare numerical stages only; real GFX has no pixelwise GT score")
    control = audited_model(control_audit, control_model, stage)
    candidate = audited_model(candidate_audit, candidate_model, stage)
    reports = [read_bound(value["report"]) for value in (control, candidate)]
    protocols = [report.get("protocol") if stage == "photo" else report.get("border", 32)
                 for report in reports]
    if protocols[0] != protocols[1]:
        raise ValueError("Different independent scoring protocols")
    if control["contexts"].keys() != candidate["contexts"].keys():
        raise ValueError("Archive observation coverage/order differs")
    for key, old in control["contexts"].items():
        new = candidate["contexts"][key]
        if old["inputs"] != new["inputs"]:
            raise ValueError("Different noisy input values in matched archive context")
        if old["supervision"] != new["supervision"]:
            raise ValueError("Different target, mask or display values in matched archive context")
    if control["rows"].keys() != candidate["rows"].keys():
        raise ValueError("Independent observation metadata/coverage differs")
    if expected_observations is not None and len(candidate["rows"]) != expected_observations:
        raise ValueError("Incomplete declared numerical comparison")
    old_rows, new_rows, rows = [], [], []
    for key in sorted(control["rows"]):
        a, b = candidate["rows"][key], control["rows"][key]
        if a["metrics"].keys() != b["metrics"].keys():
            raise ValueError("Methods have different independent metric definitions")
        rows.append({"observation": json.loads(key), **json.loads(key),
                     "control": b["metrics"], "candidate": a["metrics"],
                     "candidate_minus_control": {name: metric_delta(a["metrics"][name], b["metrics"][name])
                                                 for name in a["metrics"]}})
        old_rows.append(b)
        new_rows.append(a)
    summaries = {}
    if stage in {"photo", "known", "unseen"}:
        metrics = ("srgb_psnr", "linear_psnr", "chroma_mae", "gradient_mae") if stage == "photo" else (
            "sensor_psnr", "ahd_srgb_psnr", "ahd_chroma_mae", "ahd_gradient_mae")
        summaries["all"] = [scalar_contrast(new_rows, old_rows, stage, name, bootstrap_draws) for name in metrics]
        if stage == "photo":
            summaries["photo_conditions"] = {
                condition: [scalar_contrast([r for r in new_rows if r["condition"] == condition],
                                            [r for r in old_rows if r["condition"] == condition],
                                            stage, name, bootstrap_draws) for name in metrics]
                for condition in sorted({r["condition"] for r in new_rows if r["kind"] == "photo"})}
        primary = "srgb_psnr" if stage == "photo" else "sensor_psnr"
        ordered = sorted((row for row in rows if row["candidate_minus_control"][primary] is not None),
                         key=lambda row: row["candidate_minus_control"][primary])
        summaries["worst_primary_changes"] = ordered[:8]
        summaries["best_primary_changes"] = ordered[-8:][::-1]
    else:
        summaries["analytic_groups"] = analytic_groups(rows, stage)
    return {"stage": stage, "control": {k: v for k, v in control.items() if k not in {"contexts", "rows", "native_triplets"}},
            "candidate": {k: v for k, v in candidate.items() if k not in {"contexts", "rows", "native_triplets"}},
            "matched_batches": len(control["contexts"]), "matched_observations": len(rows),
            "all_noisy_inputs_targets_masks_and_transforms_equal": True,
            "shared_contexts_sha256": hashlib.sha256(canonical(control["contexts"]).encode()).hexdigest(),
            "rows": rows, "summaries": summaries,
            "control_native_triplets": control["native_triplets"],
            "candidate_native_triplets": candidate["native_triplets"],
            "scope": "Differences of independently audited metrics, after exact archive-context/input/supervision matching. Source/scene intervals do not measure training-seed uncertainty. Analytic patterns are descriptive. Pixel files were validated by their independent audits; this join checks those audit/row/manifest bytes and logical value fingerprints without rereading every prediction. No inference, noise generation or automatic model choice."}


def compare(control_audit, candidate_audit, control_sha256, candidate_sha256, output, *,
            expected_observations=None):
    output = writable_path(output)
    output.mkdir(parents=True, exist_ok=False)
    control, candidate = (read_bound(binding(path)) for path in (control_audit, candidate_audit))
    if set(control["stages"]) != set(STAGES) or set(candidate["stages"]) != set(STAGES):
        raise ValueError("A full endpoint comparison requires all five numerical stages")
    stages = {}
    for stage in STAGES:
        for top in (control, candidate):
            read_bound(top["stages"][stage])
        result = compare_stage(control["stages"][stage]["path"], candidate["stages"][stage]["path"],
                               identity(control_sha256), identity(candidate_sha256), stage=stage,
                               expected_observations=(expected_observations or {}).get(stage))
        write(output / f"{stage}.json", result)
        stages[stage] = binding(output / f"{stage}.json")
    result = {"control_audit": binding(control_audit), "candidate_audit": binding(candidate_audit),
              "control_sha256": control_sha256, "candidate_sha256": candidate_sha256, "stages": stages,
              "new_neural_forwards": 0, "new_encoder_forwards": 0, "new_noise_observations": 0,
              "RAW_decodes": 0, "scope": "Matched independently audited endpoints. Native/GFX review remains required; no automatic promotion."}
    write(output / "result.json", result)
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--control-audit", type=Path, required=True)
    parser.add_argument("--candidate-audit", type=Path, required=True)
    parser.add_argument("--control-sha256", required=True)
    parser.add_argument("--candidate-sha256", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    compare(args.control_audit, args.candidate_audit, args.control_sha256, args.candidate_sha256,
            args.output)

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_relative_phase_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 3288 and retained == 1398 and real == 30 and len(result["rows"]) == 4686
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 4686,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())

"""Render saved mature precision outputs at native scale, without model inference."""

import argparse
import copy
import json
import os
from pathlib import Path

import numpy as np
from build_native_crop_board import MODEL_FIELDS, build, read_crop
from train_directional_bank_trial import read, ref

POLICIES = ("fp32", "fp16", "fp16-hidden")
GPU_STATUS = "completed-mature-precision-GPU-arrays-awaiting-native-and-independent-scalar-review"


def checked(item):
    if ref(item["path"]) != {k: item[k] for k in ("path", "sha256")}:
        raise ValueError(f"Changed recorded input: {item['path']}")
    return Path(item["path"])


def save_new(path, value):
    with Path(path).open("x") as stream:
        json.dump(value, stream, indent=2, allow_nan=False)
        stream.write("\n")


def arrays(item):
    with np.load(checked(item), allow_pickle=False) as data:
        return {k: data[k].copy() for k in data.files}


def prediction(item, shape):
    value = np.load(checked(item), allow_pickle=False)
    if value.dtype != np.float32 or value.shape != shape or not np.isfinite(value).all():
        raise ValueError("Expected finite saved native FP32 camera RGB")
    return value


def gpu_methods(plan_path, receipt_path):
    """Only a genuine completed pilot can supply the three new policy identities."""
    plan, receipt = read(plan_path), read(receipt_path)
    if receipt["status"] != GPU_STATUS or receipt["plan"] != ref(plan_path):
        raise ValueError("Missing successful GPU receipt for this exact plan")
    if not receipt["backend_settings_restored"]:
        raise ValueError("GPU backend restoration failed")
    execution = plan.get("execution_policy")
    if execution and receipt.get("execution_policy") != execution:
        raise ValueError("GPU execution policy differs from the frozen study")
    if [m["model"] for m in receipt["models"]] != list(plan["models"]):
        raise ValueError("GPU model set/order differs from the frozen pilot")
    methods = []
    fixture_ids = [f["id"] for f in plan["fixtures"]]
    for model in receipt["models"]:
        if model["checkpoint"] != plan["models"][model["model"]]:
            raise ValueError("GPU checkpoint differs from the frozen pilot")
        captures = model["captures"]
        keys = [(c["policy"], c["fixture"]) for c in captures]
        if (
            len(keys) != len(set(keys))
            or set(keys) != {(p, f) for p in POLICIES for f in fixture_ids}
            or any(c["model"] != model["model"] for c in captures)
        ):
            raise ValueError("GPU capture rectangle is incomplete or duplicated")
        for policy in POLICIES:
            methods.append(
                {
                    "label": model["model"] + ":" + policy + (":" + execution if execution else ""),
                    "model": model["model"],
                    "policy": policy,
                    "checkpoint": model["checkpoint"],
                    **(
                        {
                            "execution_policy": execution,
                            "execution_backend_settings": receipt["execution_backend_settings"],
                        }
                        if execution
                        else {}
                    ),
                    "RGB": {c["fixture"]: c["RGB"] for c in captures if c["policy"] == policy},
                }
            )
    return methods


def historical_methods(plan, gfx_registry):
    """Genuine old FP32 outputs preflight rendering; they never impersonate FP16."""
    methods, evidence = [], []
    photo_root = checked(plan["photo_registry"]).parent.parent
    gfx = read(checked(gfx_registry))
    for model, checkpoint in plan["models"].items():
        for policy in ("original", "autotuned"):
            path = photo_root / f"{model}-{policy}" / "result.json"
            report = read(path)
            if (report["arm"], report["policy"], report["checkpoint"]) != (
                model,
                policy,
                checkpoint,
            ):
                raise ValueError("Historical photo policy/checkpoint identity differs")
            label = f"{model}:{policy}-FP32"
            gfx_crops = [c for c in gfx["native_crops"] if c["model_label"] == label]
            if len(gfx_crops) != 4 or any(
                c["checkpoint_sha256"] != checkpoint["sha256"] for c in gfx_crops
            ):
                raise ValueError("Historical GFX method is missing or changed")
            gfx_array = gfx_crops[0]["model"]["RGB"]
            if any(c["model"]["RGB"] != gfx_array for c in gfx_crops):
                raise ValueError("Historical GFX crops use different predictions")
            rgb = {plan["fixtures"][0]["id"]: gfx_array}
            if len(report["predictions"]) != 2:
                raise ValueError("Historical photo predictions are incomplete")
            for index, row in enumerate(report["predictions"]):
                fixture = plan["fixtures"][index + 1]
                if row["index"] != index or row["observation"] != fixture["arrays"]:
                    raise ValueError("Historical photo observation differs")
                rgb[fixture["id"]] = row["RGB"]
            methods.append(
                {
                    "label": label,
                    "model": model,
                    "policy": policy + "-FP32",
                    "checkpoint": checkpoint,
                    "RGB": rgb,
                }
            )
            evidence.append(ref(path))
    return methods, evidence


def render(plan, gfx_registry, methods, output, *, evidence, scope):
    import torch

    from demosaic.reporting import display_crop, save_triplet

    if torch.cuda.is_initialized():
        raise ValueError("Saved-output renderer must remain CPU-only")
    if len({m["label"] for m in methods}) != len(methods):
        raise ValueError("Method labels must be unique")
    output = Path(output)
    if output.exists():
        raise ValueError("Choose a new render directory")
    photo_path = checked(plan["photo_registry"])
    gfx_path = checked(gfx_registry)
    photo_templates = read(photo_path)["native_crops"]
    gfx_templates = [
        c for c in read(gfx_path)["native_crops"] if c["model_label"] == "V43:original-FP32"
    ]
    gfx_fixture = read(checked(plan["gfx_fixture"]))
    if len(photo_templates) != 2 or len(gfx_templates) != 4:
        raise ValueError("Expected two photos and all four standing GFX regions")
    fixtures = plan["fixtures"][:3]
    if [f["kind"] for f in fixtures] != ["gfx", "photo", "photo"]:
        raise ValueError("Unexpected frozen fixture order")
    observations = {f["id"]: arrays(f["arrays"]) for f in fixtures}
    templates = []
    for index, template in enumerate(photo_templates):
        fixture = fixtures[index + 1]
        values = observations[fixture["id"]]
        if (
            template["observation"] != fixture["arrays"]
            or template["condition"] != fixture["condition"]
        ):
            raise ValueError("Photo template observation/noise differs from pilot")
        if (
            template["evaluation_tile_xywh"] != [48, 48, 160, 160]
            or template["display_exposure"] != 1
        ):
            raise ValueError("Photo display/ROI differs from the fixed pilot")
        for key, recorded in [
            ("wb", template["white_balance"]),
            ("matrix", template["camera_to_srgb"]),
        ]:
            np.testing.assert_array_equal(values[key][0], np.asarray(recorded, np.float32))
        parts, _, _ = read_crop(photo_path, template, "synthetic")
        templates.append(
            ("synthetic", fixture, 0, template, parts, template["evaluation_tile_xywh"])
        )
    for index, template in enumerate(gfx_templates):
        fixture = fixtures[0]
        values = observations[fixture["id"]]
        expected = gfx_fixture["gfx_regions"][index]
        if (
            template["source"]["fixture"] != plan["gfx_fixture"]
            or template["source"]["observation"] != fixture["arrays"]
            or template["region"] != expected["region"]
            or template["context_xywh"] != expected["context_xywh"]
        ):
            raise ValueError("GFX source, region or context differs from pilot")
        if (
            template["conditioning"] != {k: fixture["condition"][k] for k in ("shot", "read")}
            or template["display_exposure"] != 4
        ):
            raise ValueError("GFX noise/display differs from fixed pilot")
        for key, recorded in [("wb", template["shared_wb"]), ("matrix", template["shared_matrix"])]:
            np.testing.assert_array_equal(values[key][index], np.asarray(recorded, np.float32))
        x, y = template["region"]["noisy_xy"]
        cx, cy, _, _ = template["context_xywh"]
        roi = [x - cx, y - cy, 160, 160]
        if roi != [176, 176, 160, 160]:
            raise ValueError("Standing GFX ROI differs from native512 fixture")
        parts, _, _ = read_crop(gfx_path, template, "gfx")
        templates.append(("gfx", fixture, index, template, parts, roi))
    # Validate all RGB files before writing any artifacts. Targets never enter a model.
    for method in methods:
        if method["checkpoint"] != plan["models"][method["model"]]:
            raise ValueError("Rendering checkpoint differs from the frozen pilot")
        for fixture in fixtures:
            values = observations[fixture["id"]]
            shape = (
                len(values["packed"]),
                3,
                values["packed"].shape[-2] * 2,
                values["packed"].shape[-1] * 2,
            )
            prediction(method["RGB"][fixture["id"]], shape)
    output.mkdir(parents=True, exist_ok=False)
    crops = {"synthetic": [], "gfx": []}
    for method in methods:
        for kind, fixture, index, template, parts, roi in templates:
            values = observations[fixture["id"]]
            shape = (
                len(values["packed"]),
                3,
                values["packed"].shape[-2] * 2,
                values["packed"].shape[-1] * 2,
            )
            rgb_ref = method["RGB"][fixture["id"]]
            rgb = torch.from_numpy(prediction(rgb_ref, shape)[index : index + 1].copy())
            metadata = {k: copy.deepcopy(v) for k, v in template.items() if k not in MODEL_FIELDS}
            label = method["label"]
            metadata.update(
                model_label=label,
                checkpoint_sha256=method["checkpoint"]["sha256"],
                compute_precision=method["policy"],
                device="saved-CUDA-output/CPU-display",
                model={
                    "label": label,
                    "sha256": method["checkpoint"]["sha256"],
                    "policy": method["policy"],
                    "RGB": rgb_ref,
                },
            )
            case = template.get("source_id", template.get("region", {}).get("name"))
            crop = save_triplet(
                output / kind,
                label + ":" + case,
                [
                    ("Noisy (Malvar)", parts[0].astype(np.float64) / 255),
                    (
                        "Denoised",
                        display_crop(
                            rgb,
                            torch.from_numpy(values["wb"][index : index + 1]),
                            torch.from_numpy(values["matrix"][index : index + 1]),
                            roi,
                            exposure=template["display_exposure"],
                        ),
                    ),
                    (template["panels"][2]["label"], parts[2].astype(np.float64) / 255),
                ],
                caption=case + " / " + label,
                metadata=metadata,
            )
            crops[kind].append(crop)
    boards = []
    for kind in ("synthetic", "gfx"):
        report_path = output / kind / "report.json"
        save_new(report_path, {"native_crops": crops[kind], "scope": scope})
        board_path = output / (kind + "-native.png")
        build([report_path], board_path, kind)
        boards.append(ref(board_path.with_suffix(".json")))
    result = {
        "status": "rendered-native-crops-awaiting-actual-manual-review",
        "driver": ref(__file__),
        "photo_registry": plan["photo_registry"],
        "gfx_registry": gfx_registry,
        "evidence": evidence,
        "methods": methods,
        "boards": boards,
        "triplets": sum(map(len, crops.values())),
        "native_cells_exact": sum(read(b["path"])["native_cells_exact"] for b in boards),
        "CUDA_initialized": torch.cuda.is_initialized(),
        "new_network_forwards": 0,
        "scope": scope,
    }
    save_new(output / "index.json", result)
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("plan", type=Path)
    parser.add_argument("gfx_registry", type=Path)
    parser.add_argument("output", type=Path)
    source = parser.add_mutually_exclusive_group(required=True)
    source.add_argument("--GPU-receipt", type=Path)
    source.add_argument("--historical-FP32", action="store_true")
    args = parser.parse_args()
    if os.environ.get("CUDA_VISIBLE_DEVICES") != "":
        raise ValueError("Run this CPU-only renderer with CUDA_VISIBLE_DEVICES=''")
    plan = read(args.plan)
    registry = ref(args.gfx_registry)
    if args.historical_FP32:
        methods, evidence = historical_methods(plan, registry)
        scope = "Historical original/autotuned FP32 rendering preflight only; no FP16 predictions, new inference, quality/timing result or pilot completion. Actual native viewing remains required."
    else:
        methods = gpu_methods(args.plan, args.GPU_receipt)
        evidence = [ref(args.GPU_receipt)]
        scope = "Saved mature FP32/FP16 policy outputs only; exact native pixels and common transforms. GFX ISO100 is a separate reference, not GT. No scalar interpretation, inference, training, default change or promotion. Actual native viewing remains required."
    evidence.append(ref(args.plan))
    result = render(plan, registry, methods, args.output, evidence=evidence, scope=scope)
    print(
        json.dumps(
            {
                k: result[k]
                for k in ("status", "triplets", "native_cells_exact", "new_network_forwards")
            }
        )
    )


if __name__ == "__main__":
    main()

"""Independent NumPy float64 reductions for saved precision-pilot outputs."""

import hashlib
import json
import math
from functools import lru_cache

import numpy as np

ROI = (48, 48, 160, 160)


def input_fingerprint(values):
    """Independently reproduce the producer's five-forward-argument byte trace."""
    digest = hashlib.sha256()
    for name in sorted(("packed", "variance", "colors", "wb", "matrix")):
        value = np.asarray(values[name])
        if value.dtype not in (np.dtype("float32"), np.dtype("int64")):
            raise ValueError("Unexpected physical-input dtype")
        header = {"name": name, "dtype": "torch." + value.dtype.name, "shape": list(value.shape)}
        digest.update(json.dumps(header, sort_keys=True).encode() + b"\0")
        digest.update(np.ascontiguousarray(value).tobytes())
    return digest.hexdigest()


def comparison_gates(kind, baseline, current):
    """Fixed per-observation noninferiority gates; no group can hide a failure."""
    if kind == "photo":
        return {
            "PSNR_loss_at_most_0.05dB": current["srgb_psnr"] >= baseline["srgb_psnr"] - 0.05,
            "SSIM_loss_at_most_0.0001": current["srgb_ssim"] >= baseline["srgb_ssim"] - 0.0001,
        }
    if kind in ("adc-carrier", "weak-noisy-carrier"):
        return {
            "signed_gain_loss_at_most_0.05": current["in_phase_gain"]
            >= baseline["in_phase_gain"] - 0.05
        }
    if kind == "flat":
        return {
            "flat_luma_RMS_at_most_1.25x": current["spatial_luma_rms"]
            <= 1.25 * baseline["spatial_luma_rms"]
        }
    raise ValueError("Unknown fixed precision gate kind")


def finite_rgb(value):
    value = np.asarray(value)
    if value.ndim != 4 or value.shape[1] != 3 or not np.isfinite(value).all():
        raise ValueError("Expected finite BCHW RGB")
    return value.astype(np.float64)


def linear_rgb(rgb, wb, matrix):
    rgb = finite_rgb(rgb)
    return np.einsum(
        "bij,bjhw->bihw",
        np.asarray(matrix, np.float64),
        rgb * np.asarray(wb, np.float64)[..., None, None],
    )


def display_rgb(rgb, wb, matrix):
    value = np.clip(linear_rgb(rgb, wb, matrix), 0, 1)
    return np.clip(
        np.where(
            value <= 0.0031308, value * 12.92, 1.055 * np.maximum(value, 1e-10) ** (1 / 2.4) - 0.055
        ),
        0,
        1,
    )


def display_metrics(prediction, target, wb, matrix):
    """Full-image sRGB PSNR/SSIM, Gaussian11/sigma1.5 with valid windows."""
    p, t = display_rgb(prediction, wb, matrix), display_rgb(target, wb, matrix)
    if p.shape != t.shape or min(p.shape[-2:]) < 11:
        raise ValueError("Photo prediction/target shape differs or lacks valid SSIM windows")
    axis = np.arange(-5, 6, dtype=np.float64)
    kernel = np.exp(-(axis * axis) / (2 * 1.5**2))
    kernel /= kernel.sum()

    def smooth(value):
        # Native NumPy valid windows avoid a separate dependency or padded edge pixels.
        horizontal = np.einsum(
            "...k,k->...", np.lib.stride_tricks.sliding_window_view(value, 11, axis=-1), kernel
        )
        return np.einsum(
            "...k,k->...",
            np.lib.stride_tricks.sliding_window_view(horizontal, 11, axis=-2),
            kernel,
        )

    mp, mt = smooth(p), smooth(t)
    vp, vt = np.maximum(smooth(p * p) - mp * mp, 0), np.maximum(smooth(t * t) - mt * mt, 0)
    bound = np.sqrt(vp * vt)
    covariance = np.clip(smooth(p * t) - mp * mt, -bound, bound)
    ssim = ((2 * mp * mt + 0.01**2) * (2 * covariance + 0.03**2)) / (
        (mp * mp + mt * mt + 0.01**2) * (vp + vt + 0.03**2)
    )
    mse = np.mean((p - t) ** 2, axis=(1, 2, 3))
    return {
        "srgb_psnr": -10 * np.log10(np.maximum(mse, 1e-12)),
        "srgb_ssim": ssim.mean(axis=(1, 2, 3)),
    }


def crop(rgb, roi=ROI):
    value = finite_rgb(rgb)
    x, y, w, h = roi
    if x < 0 or y < 0 or min(w, h) < 1 or x + w > value.shape[-1] or y + h > value.shape[-2]:
        raise ValueError("ROI is outside the saved native prediction")
    return value[..., y : y + h, x : x + w]


@lru_cache(maxsize=3)
def carrier_basis(period, roi=ROI):
    x, _y, w, h = roi
    angle = np.arange(x, x + w, dtype=np.float64) * (2 * math.pi / period)
    basis = np.stack(
        (
            np.ones((h, w)),
            np.broadcast_to(np.cos(angle), (h, w)),
            np.broadcast_to(np.sin(angle), (h, w)),
        ),
        axis=-1,
    ).reshape(-1, 3)
    return basis, np.linalg.pinv(basis)


def carrier_metrics(prediction, target, period, roi=ROI):
    p, t = (
        crop(prediction, roi).reshape(len(prediction), 3, -1),
        crop(target, roi).reshape(len(target), 3, -1),
    )
    if p.shape != t.shape:
        raise ValueError("Carrier prediction/target shape differs")
    basis, inverse = carrier_basis(period, roi)
    bp, bt = p @ inverse.T, t @ inverse.T
    a, b = bp[..., 1:], bt[..., 1:]
    power = np.maximum((b * b).sum(-1), 1e-24)
    gain = (a * b).sum(-1) / power
    quadrature = (b[..., 0] * a[..., 1] - b[..., 1] * a[..., 0]) / power
    residual = p - bp @ basis.T
    return {
        "in_phase_gain": gain.mean(1),
        "gain_channel_std": gain.std(1),
        "quadrature_gain": quadrature.mean(1),
        "amplitude_ratio": np.sqrt((a * a).sum(-1) / power).mean(1),
        "dc_bias_abs": np.abs(bp[..., 0] - bt[..., 0]).mean(1),
        "noncarrier_rms": np.sqrt((residual * residual).mean((1, 2))),
        "linear_srgb_rmse": np.sqrt(((p - t) ** 2).mean((1, 2))),
    }


def flat_metrics(prediction, target, roi=ROI):
    p, t = crop(prediction, roi), crop(target, roi)
    if p.shape != t.shape:
        raise ValueError("Flat prediction/target shape differs")
    weights = np.array([0.2126, 0.7152, 0.0722])[None, :, None, None]
    luma, truth = (p * weights).sum(1), (t * weights).sum(1)
    centered = luma - luma.mean((-2, -1), keepdims=True)
    h, w = luma.shape[-2:]
    radius = np.hypot(np.fft.fftfreq(h)[:, None], np.fft.fftfreq(w)[None, :])
    band = (radius >= 1 / 48) & (radius <= 0.22)
    spectrum = np.abs(np.fft.fft2(centered))
    level = np.maximum(np.abs(truth.mean((-2, -1))), 1e-12)
    return {
        "dc_bias_abs_rgb": np.abs(p.mean((-2, -1)) - t.mean((-2, -1))).mean(1),
        "linear_srgb_rmse": np.sqrt(((p - t) ** 2).mean((1, 2, 3))),
        "spatial_luma_rms": np.sqrt((centered * centered).mean((-2, -1))),
        "relative_band_rms": np.sqrt(((spectrum * spectrum) * band).sum((-2, -1)))
        / (h * w)
        / level,
        "relative_peak_band_contrast": 2 * np.max(spectrum * band, axis=(-2, -1)) / (h * w) / level,
    }


def physical_difference(prediction, baseline):
    p, b = finite_rgb(prediction), finite_rgb(baseline)
    if p.shape != b.shape:
        raise ValueError("Precision predictions have different shapes")
    delta = p - b
    return {
        "RGB_values": delta.size,
        "max_abs_DN16": float(np.abs(delta).max() * 65535),
        "RMS_DN16": float(np.sqrt(np.mean(delta * delta)) * 65535),
    }

"""Independently replay a completed saved precision screen with CPU Torch math."""

import argparse
import json
import math
import os
from pathlib import Path

from render_mature_precision import arrays, checked, prediction, save_new
from train_directional_bank_trial import guard, read, ref


def main(protocol_path, result_path, output):
    import torch
    from diagnose_texture_response import linear_srgb, response_metrics
    from evaluate_texture_candidates import flat_metrics

    from demosaic.metrics import quality_metrics

    if os.environ.get("CUDA_VISIBLE_DEVICES") != "" or torch.cuda.is_initialized():
        raise ValueError("Independent replay must remain CPU-only")
    torch.set_num_threads(2)
    protocol, result = read(protocol_path), read(result_path)
    guard(protocol)
    if result["protocol"] != ref(protocol_path) or result["new_network_forwards"] != 0:
        raise ValueError("Wrong completed saved-output review")
    gpu = read(checked(result["GPU_receipt"]))
    plan = read(checked(protocol["GPU_plan"]))
    guard(plan)
    rows = result["per_observation"]
    key = lambda r: (
        r["model"],
        r["policy"],
        r["fixture"],
        json.dumps(r.get("case"), sort_keys=True),
    )
    saved = {key(r): r for r in rows}
    if len(saved) != len(rows) or len(rows) != 588:
        raise ValueError("Duplicate/missing saved scalar observations")
    errors, analytic_fields, photo_fields, physical_values, repeats, ramp_fields = {}, 0, 0, 0, 0, 0
    physical = {
        (r["model"], r["policy"], r["fixture"]): r
        for r in result["physical_differences_unclipped_DN16"]
    }
    ramp_rows = {(r["model"], r["policy"], r["pattern"]): r for r in result["native_ramps"]}
    methods = {}

    def close(name, current, expected):
        error = abs(float(current) - float(expected))
        if not math.isfinite(error) or error > 1e-10:
            raise ValueError(f"Independent scalar mismatch: {name}, error={error}")
        errors[name] = max(errors.get(name, 0), error)

    for model in gpu["models"]:
        captures = {(r["policy"], r["fixture"]): r for r in model["captures"]}
        methods[model["model"]] = captures
        for fixture in plan["fixtures"]:
            host = arrays(fixture["arrays"])
            shape = (
                len(host["packed"]),
                3,
                host["packed"].shape[-2] * 2,
                host["packed"].shape[-1] * 2,
            )
            predictions = {}
            for policy in ("fp32", "fp16", "fp16-hidden"):
                capture = captures[policy, fixture["id"]]
                values = prediction(capture["RGB"], shape)
                predictions[policy] = values
                if fixture["kind"] == "photo":
                    metrics = quality_metrics(
                        *(
                            torch.from_numpy(v)
                            for v in (values, host["target"], host["wb"], host["matrix"])
                        )
                    )
                    previous = saved[model["model"], policy, fixture["id"], "null"]
                    for name in ("srgb_psnr", "srgb_ssim"):
                        close(
                            "canonical_" + name, metrics[name][0], previous["canonical_FP32"][name]
                        )
                        photo_fields += 1
                elif fixture["kind"] == "analytic":
                    wb, matrix = (torch.from_numpy(host[k]) for k in ("wb", "matrix"))
                    pred, target = (
                        linear_srgb(torch.from_numpy(v), wb, matrix)
                        for v in (values, host["target"])
                    )
                    metrics = (
                        response_metrics(pred, target, fixture["cases"][0]["period"])
                        if fixture["signal_kind"] == "carrier"
                        else flat_metrics(pred, target)
                    )
                    for j, case in enumerate(fixture["cases"]):
                        previous = saved[
                            model["model"], policy, fixture["id"], json.dumps(case, sort_keys=True)
                        ]
                        for name, metric in metrics.items():
                            close("analytic_" + name, metric[j], previous["metrics"][name])
                            analytic_fields += 1
            for policy in ("fp16", "fp16-hidden"):
                delta = (
                    torch.from_numpy(predictions[policy]).double()
                    - torch.from_numpy(predictions["fp32"]).double()
                )
                previous = physical[model["model"], policy, fixture["id"]]
                if delta.numel() != previous["RGB_values"]:
                    raise ValueError("Physical difference coverage changed")
                close(
                    "physical_max_DN16", delta.abs().max().item() * 65535, previous["max_abs_DN16"]
                )
                close(
                    "physical_RMS_DN16",
                    delta.square().mean().sqrt().item() * 65535,
                    previous["RMS_DN16"],
                )
                physical_values += delta.numel()
        first_id = plan["fixtures"][0]["id"]
        for sample in model["timings"]:
            if sample["kind"] != "synchronized-resident-unhooked-sample":
                continue
            checked(sample["RGB"])
            original = captures[sample["policy"], first_id]["RGB"]
            # File hashes establish byte identity, including signed-zero encodings.
            same = sample["RGB"]["sha256"] == original["sha256"]
            if same != sample["byte_equal_first_capture"] or not same:
                raise ValueError("Timed repeat is not independently byte-identical")
            repeats += 1
        base, plus = plan["fixtures"][-2:]
        for policy in ("fp32", "fp16", "fp16-hidden"):
            a = torch.from_numpy(
                prediction(captures[policy, base["id"]]["RGB"], (4, 3, 256, 256))
            ).double()
            b = torch.from_numpy(
                prediction(captures[policy, plus["id"]]["RGB"], (4, 3, 256, 256))
            ).double()
            codes = (a.clamp(0, 1) * 65535).round().long()
            for j, pattern in enumerate(base["patterns"]):
                previous = ramp_rows[model["model"], policy, pattern]
                if torch.unique(codes[j]).numel() != previous["codes"]:
                    raise ValueError("Independent native code count differs")
                close(
                    "native_one_DN_RMS",
                    (b[j] - a[j]).square().mean().sqrt(),
                    previous["one_DN_response_RMS"],
                )
                ramp_fields += 2
    if (analytic_fields, photo_fields, physical_values, repeats, ramp_fields) != (
        3840,
        24,
        95944704,
        24,
        48,
    ):
        raise ValueError("Incomplete independent review coverage")
    guard(protocol)
    guard(plan)
    if torch.cuda.is_initialized():
        raise ValueError("Independent replay initialized CUDA")
    save_new(
        output,
        {
            "status": "completed-independent-Torch-replay-of-mature-precision-screen",
            "driver": ref(__file__),
            "protocol": ref(protocol_path),
            "result": ref(result_path),
            "analytic_fields": analytic_fields,
            "canonical_photo_fields": photo_fields,
            "physical_RGB_difference_values": physical_values,
            "repeat_files_SHA256_exact": repeats,
            "native_ramp_fields": ramp_fields,
            "maximum_scalar_replay_errors": errors,
            "CUDA_initialized": False,
            "new_network_forwards": 0,
            "scope": "Independent CPU Torch analytic/difference/ramp arithmetic over genuine completed outputs; photo canonical metrics repeat exactly and all24 timed output files are SHA256-identical to their first capture. Scalar parity bound1e-10 is separate from unchanged policy noninferiority limits. No new inference, population quality, full-frame timing, default change or promotion.",
        },
    )
    print(
        {
            "status": "completed-independent-Torch-replay",
            "analytic_fields": analytic_fields,
            "physical_values": physical_values,
            "exact_repeat_files": repeats,
        }
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("protocol", "result", "output"):
        parser.add_argument(name, type=Path)
    args = parser.parse_args()
    main(args.protocol, args.result, args.output)

"""Native carrier footprints for fixed packed bins; never recovery bounds.

Sampling every second pixel identifies a frequency modulo one half cycle per
native pixel. Four native lifts share each packed bin. Two green phases alone
do not distinguish all four lifts. These masks describe geometry, not a learned
head's attainable output: spatial coefficient modulation has other frequencies.
"""

import numpy as np


def signed_bins(shape, bins):
    if len(shape) != 2 or any(type(n) is not int or n < 8 for n in shape):
        raise ValueError("Expected two packed integer axes >=8")
    bins = np.asarray(bins)
    if (
        bins.ndim != 2
        or bins.shape[1] != 2
        or not np.issubdtype(bins.dtype, np.integer)
        or not ((bins >= 0) & (bins < shape)).all()
    ):
        raise ValueError("Expected in-range integer Nx2 packed bins")
    size = np.asarray(shape)
    return np.where(bins <= (size - 1) // 2, bins, bins - size)


def carrier_footprints(shape, bins, radius):
    """Conjugate-closed native masks around principal or all four lifts.

    Lift the signed CENTER before expanding each square neighborhood on the
    native torus. Folding the neighborhood first would silently wrap it at the
    packed Nyquist boundary. Four-lift overlap is counted once in the union.
    """
    centers = signed_bins(shape, bins)
    if type(radius) is not int or radius < 0 or radius >= min(shape) // 2:
        raise ValueError("Expected nonnegative radius below half a packed axis")
    native = tuple(2 * n for n in shape)
    masks = np.zeros((4, *native), dtype=bool)
    for index, (ay, ax) in enumerate([(0, 0), (0, 1), (1, 0), (1, 1)]):
        for cy, cx in centers + np.asarray([ay * shape[0], ax * shape[1]]):
            for sign in [-1, 1]:
                for dy in range(-radius, radius + 1):
                    for dx in range(-radius, radius + 1):
                        masks[index, (sign * cy + dy) % native[0], (sign * cx + dx) % native[1]] = (
                            True
                        )
    return masks[0], masks.any(0)


def native_regions(shape):
    if len(shape) != 2 or any(type(n) is not int or n < 16 or n % 2 for n in shape):
        raise ValueError("Expected even native integer axes >=16")
    fy, fx = [np.fft.fftfreq(n) for n in shape]
    ay, ax = abs(fy[:, None]), abs(fx[None, :])
    strict = (ay < 0.25) & (ax < 0.25)
    closed = (ay <= 0.25) & (ax <= 0.25)
    boundary = closed & ~strict
    return {
        "strict_principal_square": strict,
        "quarter_cycle_boundary": boundary,
        "outside_closed_principal_square": ~closed,
        "native_radial_1over16_to_1over3": (np.hypot(ay, ax) >= 1 / 16)
        & (np.hypot(ay, ax) <= 1 / 3),
    }


def power_summary(power, packed_shape, bins, radius):
    power = np.asarray(power)
    if (
        power.shape != tuple(2 * n for n in packed_shape)
        or not np.isfinite(power).all()
        or (power < 0).any()
        or not power.sum() > 0
    ):
        raise ValueError("Expected positive finite native template power")
    principal, all_lifts = carrier_footprints(packed_shape, bins, radius)
    total = power.sum(dtype=np.float64)
    result = {
        key: float(power[mask].sum(dtype=np.float64) / total)
        for key, mask in native_regions(power.shape).items()
    }
    result.update(
        principal_carrier_proximity=float(power[principal].sum(dtype=np.float64) / total),
        four_lift_carrier_proximity=float(power[all_lifts].sum(dtype=np.float64) / total),
        added_alias_proximity=float(power[all_lifts & ~principal].sum(dtype=np.float64) / total),
        principal_footprint_cells=int(principal.sum()),
        four_lift_footprint_cells=int(all_lifts.sum()),
    )
    return result

"""Freeze coupled Commons manifests with reviewed training title-series removed.

Only metadata is processed. Original records/cache paths and every nontraining
line are preserved. Use a new destination; running experiments never change.
"""

import argparse
import hashlib
import json
import os
import shutil
import unicodedata
from collections import Counter
from datetime import UTC, datetime
from pathlib import Path

from demosaic.safety import writable_path


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def ref(path):
    return {"path": str(Path(path).resolve()), "sha256": sha(path)}


def normalize(value):
    return unicodedata.normalize("NFC", value).casefold()


def validate_policy(policy):
    rules = policy.get("rules", [])
    if policy.get("format_version") != 1 or not rules:
        raise ValueError("Expected version1 policy with explicit reviewed rules")
    if len({r["id"] for r in rules}) != len(rules):
        raise ValueError("Duplicate rule identities")
    for rule in rules:
        prefixes = rule.get("title_prefixes", [])
        if rule.get("kind") not in ("capture_series", "shared_site"):
            raise ValueError("Unknown reviewed grouping kind")
        if not prefixes or any(
            not isinstance(p, str) or not p.startswith("File:") or not p[5:].strip()
            for p in prefixes
        ):
            raise ValueError("Rules need nonempty Commons title prefixes")
        if not rule.get("query_seed_ids"):
            raise ValueError("Each rule needs a reviewed validation seed")
    return rules


def matching_rules(title, rules):
    title = normalize(title)
    return [
        r["id"] for r in rules if any(title.startswith(normalize(p)) for p in r["title_prefixes"])
    ]


def read_manifest(path, factor):
    lines = Path(path).read_bytes().splitlines(keepends=True)
    records = [json.loads(line) for line in lines]
    if len({r["id"] for r in records}) != len(records):
        raise ValueError("Duplicate source identities")
    for r in records:
        if r["split"] in ("train", "val", "test") and not Path(r["cache"]).is_absolute():
            raise ValueError(
                "Cache paths must be absolute to preserve literal records on relocation"
            )
        if r["split"] == "train" and (
            r["bin_factor"] != factor
            or r["dtype"] != "uint16"
            or r["color_space"] != "linear-sRGB"
            or len(r["cache_sha256"]) != 64
            or len(r["shape"]) != 3
            or r["shape"][2] != 3
            or min(r["shape"][:2]) < 2048 // factor
        ):
            raise ValueError("Training cache metadata does not support the declared binning/patch")
    return lines, records


def quarantine(manifest8, manifest4, policy_path, output):
    manifest8, manifest4, policy_path = [
        Path(p).resolve() for p in (manifest8, manifest4, policy_path)
    ]
    output = writable_path(output)
    if output.exists():
        raise ValueError("Destination already exists; choose a new frozen version")
    inputs = {"bin8": ref(manifest8), "bin4": ref(manifest4), "policy": ref(policy_path)}
    policy = json.loads(policy_path.read_text())
    rules = validate_policy(policy)
    data = {8: read_manifest(manifest8, 8), 4: read_manifest(manifest4, 4)}
    by = {factor: {r["id"]: r for r in records} for factor, (_, records) in data.items()}
    for split in ("train", "val", "test"):
        ids = [{r["id"] for r in records if r["split"] == split} for _, records in data.values()]
        if ids[0] != ids[1]:
            raise ValueError("Coupled manifests disagree on source split membership")
    for rule in rules:
        for identity in rule["query_seed_ids"]:
            if any(
                identity not in b
                or b[identity]["split"] != "val"
                or rule["id"] not in matching_rules(b[identity]["title"], [rule])
                for b in by.values()
            ):
                raise ValueError(
                    "Reviewed query seed is missing, not validation, or does not match its rule"
                )
    matches = {
        factor: {
            r["id"]: matching_rules(r["title"], rules)
            for r in records
            if r["split"] == "train" and matching_rules(r["title"], rules)
        }
        for factor, (_, records) in data.items()
    }
    if matches[8] != matches[4]:
        raise ValueError("Coupled metadata produces different training quarantines")
    for rule in rules:
        for identity in rule.get("reviewed_training_seed_ids", []):
            if (
                identity in by[8]
                and by[8][identity]["split"] == "train"
                and rule["id"] not in matches[8].get(identity, [])
            ):
                raise ValueError("A reviewed training seed would escape its stated rule")
    output.mkdir(parents=True)
    shutil.copyfile(policy_path, output / "policy.json")
    shutil.copyfile(__file__, output / "source.py")
    outputs = {}
    for factor, (lines, records) in data.items():
        retained = b"".join(
            line for line, r in zip(lines, records, strict=True) if r["id"] not in matches[factor]
        )
        removed = b"".join(
            line for line, r in zip(lines, records, strict=True) if r["id"] in matches[factor]
        )
        path, quarantine_path = (
            output / f"manifest{factor}.jsonl",
            output / f"quarantined{factor}.jsonl",
        )
        path.write_bytes(retained)
        quarantine_path.write_bytes(removed)
        nontrain = b"".join(
            line for line, r in zip(lines, records, strict=True) if r["split"] != "train"
        )
        kept_rows = [r for r in records if r["id"] not in matches[factor]]
        outputs[f"bin{factor}"] = {
            "manifest": ref(path),
            "quarantine": ref(quarantine_path),
            "before_counts": dict(Counter(r["split"] for r in records)),
            "after_counts": dict(Counter(r["split"] for r in kept_rows)),
            "unchanged_nontraining_literal_lines_sha256": hashlib.sha256(nontrain).hexdigest(),
        }
    removed_records = [
        {"source": by[8][identity], "matched_rule_ids": hit}
        for identity, hit in sorted(matches[8].items())
    ]
    reasons_path = output / "quarantine-reasons.jsonl"
    reasons_path.write_text(
        "".join(json.dumps(r, ensure_ascii=False) + "\n" for r in removed_records)
    )
    report = {
        "status": "completed-reviewed-series-metadata-quarantine-for-future-training",
        "created_UTC": datetime.now(UTC).isoformat(),
        "operator": ref(__file__),
        "inputs": inputs,
        "outputs": outputs,
        "reasons": ref(reasons_path),
        "quarantined_training_sources": len(matches[8]),
        "per_rule_training_counts": dict(Counter(k for hits in matches[8].values() for k in hits)),
        "retained_cache_records_and_all_nontraining_lines_unchanged": True,
        "actual_cache_decodes_or_neural_forwards": 0,
        "limits": "Known manually reviewed title-series/site exclusions only, not full scene independence. Metadata-only subset: no new cache-byte verification, resampling, split reassignment, deletion, source modification, model scoring or active recipe change. Existing cache audits remain parent evidence; other aliases/scenes can remain unmatched.",
    }
    for value in inputs.values():
        if ref(value["path"]) != value:
            raise ValueError(
                "Input changed while freezing; preserve this failed output and choose a new version"
            )
    (output / "report.json").write_text(json.dumps(report, indent=2) + "\n")
    return report


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--manifest8", required=True, type=Path)
    parser.add_argument("--manifest4", required=True, type=Path)
    parser.add_argument("--policy", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    os.nice(10)
    print(
        json.dumps(quarantine(args.manifest8, args.manifest4, args.policy, args.output), indent=2)
    )


if __name__ == "__main__":
    main()

"""CPU NumPy audit of the fixed photo/GFX spectral intervention pilot."""

import argparse
import hashlib
import json
import math
from pathlib import Path

import numpy as np
from PIL import Image


def read(path):
    return json.loads(Path(path).read_text())


def ref(path):
    path = Path(path)
    return {"path": str(path), "sha256": hashlib.sha256(path.read_bytes()).hexdigest()}


def checked(item):
    assert ref(item["path"]) == item
    return Path(item["path"])


def fingerprint(values):
    h = hashlib.sha256()
    for name, value in sorted(values.items()):
        dtype = {"float32": "torch.float32", "int64": "torch.int64"}[value.dtype.name]
        h.update(name.encode() + dtype.encode() + str(tuple(value.shape)).encode())
        h.update(value.tobytes(order="C"))
    return h.hexdigest()


def render(rgb, wb, matrix):
    linear = np.einsum(
        "bij,bjhw->bihw", matrix.astype(np.float64), rgb.astype(np.float64) * wb[..., None, None]
    ).clip(0, 1)
    return np.where(linear <= 0.0031308, linear * 12.92, 1.055 * linear ** (1 / 2.4) - 0.055)


def psnr(prediction, target):
    mse = np.mean((prediction - target) ** 2, axis=(1, 2, 3))
    return -10 * np.log10(np.maximum(mse, 1e-12))


def main(root, output):
    review = read(root / "native/manual-review-before-statistics.json")
    assert review["statistics_interpreted"] is False
    assert all(b["actual_viewed"] for b in review["boards"])
    summary = read(checked(review["pilot"]))
    assert (
        summary["status"]
        == "completed-fixed-spectral-photo-GFX-component-pilot-awaiting-native-review"
    )
    max_mask = 0.0
    errors = {"linear_psnr": 0.0, "srgb_psnr": 0.0}
    scalars = identities = inputs = recovery_matches = 0
    comparisons = []
    for result in summary["results"]:
        with np.load(checked(result["arrays"]), allow_pickle=False) as a:
            names = ["colors", "matrix", "packed", "variance", "wb"]
            if result["kind"] == "photo":
                names.append("target")
            assert fingerprint({k: a[k] for k in names}) == result["inputs_sha256"]
            inputs += 1
            for mode, expected in [
                ("full", a["base"] + a["gate"][..., None, None] * a["innovation"]),
                ("unit", a["base"] + a["innovation"]),
            ]:
                assert expected.tobytes(order="C") == a[mode].tobytes(order="C")
                identities += len(expected)
            f = np.fft.rfft2(a["packed"].astype(np.float64), norm="ortho")
            scale = np.maximum(a["variance"], 0).astype(np.float64).mean((-2, -1), keepdims=True)
            power = (np.abs(f) ** 2 / np.maximum(scale, 1e-12)).sum(1, keepdims=True)
            t = math.log(a["packed"].shape[-2] * a["packed"].shape[-1] / 0.01)
            mask = np.maximum(1 - (4 + 4 * math.sqrt(t) + 2 * t) / np.maximum(power, 1e-12), 0)
            mask[..., 0, 0] = 0
            max_mask = max(max_mask, float(np.max(np.abs(mask - a["mask"]))))
            if result["kind"] != "photo":
                continue
            condition = result["condition"]["name"]
            rows = result["cases"]
            sources = list(dict.fromkeys(row["source_id"] for row in rows))
            scores = {(row["source_id"], row["mode"]): row["metrics"] for row in rows}
            for mode in ["full", "base", "unit"]:
                p, q = [v[..., 8:-8, 8:-8].astype(np.float64) for v in [a[mode], a["target"]]]
                values = {
                    "linear_psnr": psnr(p.clip(0, 1), q.clip(0, 1)),
                    "srgb_psnr": psnr(
                        render(p, a["wb"], a["matrix"]), render(q, a["wb"], a["matrix"])
                    ),
                }
                for metric, values_by_source in values.items():
                    for i, source in enumerate(sources):
                        errors[metric] = max(
                            errors[metric],
                            abs(float(values_by_source[i]) - scores[source, mode][metric]),
                        )
                        scalars += 1
            deltas = {}
            for mode, reference in [("unit", "full"), ("full", "base")]:
                deltas[mode + "_minus_" + reference] = {
                    metric: [
                        scores[s, mode][metric] - scores[s, reference][metric] for s in sources
                    ]
                    for metric in ["linear_psnr", "srgb_psnr", "srgb_ssim"]
                }
            comparisons.append({"condition": condition, "source_ids": sources, **deltas})
            failed = (
                root.parent
                / "spectral-photo-components-v1/cuda-pilot"
                / ("photo-" + condition)
                / "arrays.npz"
            )
            if condition in ["adc-only", "iso100-prior", "iso1600-prior", "iso12800-prior"]:
                with np.load(failed, allow_pickle=False) as old:
                    assert set(old.files) == set(a.files)
                    assert all(
                        old[k].tobytes(order="C") == a[k].tobytes(order="C") for k in a.files
                    )
                recovery_matches += 1
    assert inputs == 8 and identities == 36 and scalars == 84 and recovery_matches == 4
    assert max_mask < 1e-4 and max(errors.values()) < 1e-4
    cells = triplets = 0
    for board_ref in review["boards"]:
        board = read(checked(board_ref["receipt"]))
        pixels = np.asarray(Image.open(checked(board["board"])))
        for cell in board["cells"]:
            original = np.asarray(Image.open(checked(cell["image"])))
            x, y, w, h = cell["source_xywh"]
            xx, yy, ww, hh = cell["board_xywh"]
            source = original[y : y + h, x : x + w]
            assert (w, h, ww, hh) == (160,) * 4
            assert np.array_equal(source, pixels[yy : yy + hh, xx : xx + ww])
            assert hashlib.sha256(source.tobytes()).hexdigest() == cell["pixel_sha256"]
            cells += 1
        for report_ref in board["reports"]:
            report = read(checked(report_ref))
            shared = {}
            for crop in report["native_crops"]:
                original = np.asarray(
                    Image.open(
                        checked(
                            {
                                "path": str(Path(report_ref["path"]).parent / crop["image"]),
                                "sha256": crop["png_sha256"],
                            }
                        )
                    )
                )
                key = crop.get("source_id", crop.get("region", {}).get("name"))
                for i in [0, 2]:
                    x, y, w, h = crop["panels"][i]["png_xywh"]
                    part = original[y : y + h, x : x + w].tobytes()
                    assert shared.setdefault((key, i), part) == part
                triplets += 1
    assert cells == 90 and triplets == 54
    result = {
        "status": "completed-independent-NumPy-photo-GFX-component-audit",
        "driver": ref(__file__),
        "pilot": review["pilot"],
        "manual_review_before_statistics": ref(
            root / "native/manual-review-before-statistics.json"
        ),
        "input_batches_exact": inputs,
        "FP32_output_identities_exact": identities,
        "FP64_mask_max_abs_error": max_mask,
        "PSNR_scalars_independently_recomputed": scalars,
        "PSNR_max_abs_error_by_metric": errors,
        "SSIM_independently_recomputed": False,
        "first_four_failed_attempt_arrays_bitwise_replayed": recovery_matches,
        "native_cells_exact": cells,
        "source_triplets_exact": triplets,
        "comparisons": comparisons,
        "scope": "Two photo sources, seven conditions, one RGGB layout/draw; no population inference. GFX is qualitative only; no real-reference metrics. No neural inference, training, serving or policy change.",
    }
    assert output.is_relative_to(root) or output.is_relative_to(Path.cwd())
    output.write_text(json.dumps(result, indent=2) + "\n")
    print({k: v for k, v in result.items() if k not in ["comparisons", "scope"]})


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    main(args.root.resolve(), args.output.resolve())

"""Preserve V172 Adam/EMA history while introducing a new evidence parameter.

The old network's optimizer clock continues;the adapter starts at zero. Target
pixels and quality decisions do not enter these state-management functions.
"""

import copy

import torch
from train_local_noise_matching_trial import tree_equal


def matching_parameters(module):
    parameters = {name: p for name, p in module.named_parameters() if p.requires_grad}
    allowed = {"network." + name for name, _ in module.network.named_parameters()}
    if hasattr(module, "phase_evidence_in"):
        allowed.update(
            "phase_evidence_in." + name for name, _ in module.phase_evidence_in.named_parameters()
        )
    if set(parameters) != allowed or any(p.requires_grad for p in module.frozen.parameters()):
        raise ValueError(
            "Expected trainable matching network/optional evidence and frozen component"
        )
    return parameters


def optimizer_for(module, *, lr, weight_decay):
    matching_parameters(module)
    optimizer = torch.optim.AdamW(module.network.parameters(), lr=lr, weight_decay=weight_decay)
    if hasattr(module, "phase_evidence_in"):
        optimizer.add_param_group({"params": list(module.phase_evidence_in.parameters())})
    return optimizer


def _validate_ema(parameters, ema):
    if set(ema) != set(parameters):
        raise ValueError("EMA must include every trainable network/evidence tensor")
    for name, parameter in parameters.items():
        if ema[name].shape != parameter.shape or ema[name].dtype != parameter.dtype:
            raise ValueError("EMA shape/dtype differs from the parameter")


def adam_clocks(module, optimizer):
    output = {
        "network": {"tensors": 0, "states": 0, "steps": []},
        "adapter": {"tensors": 0, "states": 0, "steps": []},
    }
    for name, parameter in matching_parameters(module).items():
        group = output["network" if name.startswith("network.") else "adapter"]
        group["tensors"] += 1
        state = optimizer.state.get(parameter)
        if state:
            if "step" not in state or not all(
                torch.isfinite(v).all() for v in state.values() if isinstance(v, torch.Tensor)
            ):
                raise ValueError("Invalid or nonfinite Adam state")
            group["states"] += 1
            group["steps"].append(float(state["step"]))
    for group in output.values():
        group["steps"] = sorted(set(group["steps"]))
    return output


def warm_start_matching(module, checkpoint, *, lr, weight_decay):
    """Load old raw/Adam/EMA exactly,then add a zero adapter with no Adam state.

    Deep-copy optimizer payloads even on CPU,where load_state_dict can otherwise
    share moment storage between a checkpoint and independently initialized arms.
    Learning rate intentionally changes for the new schedule;moments/steps do not.
    """
    initial_updates = checkpoint["updates"]
    if type(initial_updates) is not int or initial_updates < 1:
        raise ValueError("Expected a completed positive-step matching checkpoint")
    if len(checkpoint["optimizer"]["param_groups"]) != 1:
        raise ValueError("Expected the original single-network optimizer group")
    if hasattr(module, "phase_evidence_in"):
        module.initialize_from_local_matching(checkpoint["models"])
    else:
        module.load_state_dict(checkpoint["models"], strict=True)
    network_names = dict(module.network.named_parameters())
    if set(checkpoint["ema"]) != set(network_names):
        raise ValueError("Old EMA does not cover exactly the matching network")
    optimizer = torch.optim.AdamW(module.network.parameters(), lr=lr, weight_decay=weight_decay)
    optimizer.load_state_dict(copy.deepcopy(checkpoint["optimizer"]))
    # Check the original optimizer before adding the new parameter group/LR.
    if not tree_equal(optimizer.state_dict(), checkpoint["optimizer"]):
        raise ValueError("Original Adam state did not load exactly")
    before = adam_clocks(module, optimizer)
    if (
        len(optimizer.state) != len(network_names)
        or before["network"]["states"] != len(network_names)
        or before["network"]["steps"] != [float(initial_updates)]
    ):
        raise ValueError("Existing Adam clocks do not match checkpoint updates")
    if hasattr(module, "phase_evidence_in"):
        optimizer.add_param_group({"params": list(module.phase_evidence_in.parameters())})
    for group in optimizer.param_groups:
        group["lr"] = lr
        if group["weight_decay"] != weight_decay:
            raise ValueError("Warm-start weight decay differs from the intended recipe")
    parameters = matching_parameters(module)
    ema = {
        "network." + name: value.detach().to(device=parameters["network." + name].device).clone()
        for name, value in checkpoint["ema"].items()
    }
    for name, parameter in parameters.items():
        if name.startswith("phase_evidence_in."):
            if parameter.count_nonzero():
                raise ValueError("Expected a zero evidence initializer")
            ema[name] = parameter.detach().clone()
    _validate_ema(parameters, ema)
    clocks = adam_clocks(module, optimizer)
    if clocks["adapter"]["states"] != 0:
        raise ValueError("New adapter unexpectedly has an Adam history")
    return (
        optimizer,
        ema,
        {
            "initial_updates": initial_updates,
            "Adam_clocks": clocks,
            "original_moments_exact": True,
            "new_adapter_has_no_Adam_state": True,
            "network_EMA_exact": True,
            "adapter_EMA_starts_zero": True,
        },
    )


def update_matching_ema(module, ema, *, total_updates, maximum_decay):
    if type(total_updates) is not int or total_updates < 1 or not 0 <= maximum_decay < 1:
        raise ValueError("Expected positive update count and EMA decay in[0,1)")
    parameters = matching_parameters(module)
    _validate_ema(parameters, ema)
    decay = min(maximum_decay, (1 + total_updates) / (10 + total_updates))
    with torch.no_grad():
        for name, parameter in parameters.items():
            ema[name].lerp_(parameter, 1 - decay)
    return decay


def load_matching_ema(module, ema):
    parameters = matching_parameters(module)
    _validate_ema(parameters, ema)
    with torch.no_grad():
        for name, parameter in parameters.items():
            parameter.copy_(ema[name])


def restore_matching_state(module, checkpoint, *, lr, weight_decay):
    """Restore a continuation checkpoint without reinitializing its adapter."""
    module.load_state_dict(checkpoint["models"], strict=True)
    parameters = matching_parameters(module)
    _validate_ema(parameters, checkpoint["ema"])
    optimizer = optimizer_for(module, lr=lr, weight_decay=weight_decay)
    optimizer.load_state_dict(copy.deepcopy(checkpoint["optimizer"]))
    if not tree_equal(optimizer.state_dict(), checkpoint["optimizer"]):
        raise ValueError("Adam restoration differs")
    ema = {
        name: value.detach().to(device=parameters[name].device).clone()
        for name, value in checkpoint["ema"].items()
    }
    clocks = adam_clocks(module, optimizer)
    expected = checkpoint["initial_updates"] + checkpoint["updates"]
    if (
        len(optimizer.state) != len(parameters)
        or clocks["network"]["states"] != clocks["network"]["tensors"]
        or clocks["network"]["steps"] != [float(expected)]
    ):
        raise ValueError("Restored network clock is wrong")
    if clocks["adapter"]["tensors"] and (
        clocks["adapter"]["states"] != clocks["adapter"]["tensors"]
        or clocks["adapter"]["steps"] != [float(checkpoint["updates"])]
    ):
        raise ValueError("Restored new-parameter clock is wrong")
    torch.set_rng_state(checkpoint["CPU_RNG"])
    cuda = checkpoint.get("CUDA_RNG")
    if cuda is not None:
        torch.cuda.set_rng_state(cuda)
    return (
        optimizer,
        ema,
        {
            "Adam_clocks": clocks,
            "model_loaded_strictly": True,
            "Adam_exact": True,
            "EMA_exact": True,
            "CPU_RNG_exact": torch.equal(torch.get_rng_state(), checkpoint["CPU_RNG"]),
            "CUDA_RNG_exact": torch.equal(torch.cuda.get_rng_state().cpu(), cuda)
            if cuda is not None
            else None,
        },
    )

"""Compare local fine-band response in matched saved photographic archives."""

import hashlib
import json
import os
import time
from collections import defaultdict
from pathlib import Path

import numpy as np
import psutil
from diagnose_local_material_detail import basis, binding, blocks, fft_dct, luminance, reduce_sums

CONDITIONS = {"adc-only", "iso100-prior", "iso12800-prior"}
PATTERNS = {"RGGB", "BGGR", "GRBG", "GBRG"}
EDGES = np.array([0, 0.02, 0.05, 0.10, 0.20])


def fingerprint(value):
    return {
        "dtype": value.dtype.str,
        "shape": list(value.shape),
        "sha256": hashlib.sha256(value.tobytes()).hexdigest(),
    }


def read_records(path, sha256):
    rows = {}
    for index, line in enumerate(Path(path).read_text().splitlines()):
        row = json.loads(line)
        if row["schema"] != "demosaic-predictions-v1" or row["index"] != index:
            raise ValueError("Archive schema or sequential index differs")
        if row["model"]["sha256"] != sha256:
            continue
        if row["model"].get("self_ensemble", "none") != "none" or row["model"]["step"] != 20000:
            raise ValueError("Expected final20k single-view predictions")
        context = row["context"]
        if context["condition"]["name"] not in CONDITIONS:
            continue
        if context["pattern"] not in PATTERNS or context["condition"]["exposure"] != 1:
            raise ValueError("Unexpected phase or exposure")
        key = (tuple(context["ids"]), context["condition"]["name"], context["pattern"])
        if key in rows:
            raise ValueError("Duplicate photographic batch")
        rows[key] = row
    if not rows:
        raise ValueError("No declared endpoint observations")
    return rows


def matched(a, b):
    if a["context"] != b["context"]:
        raise ValueError("Noisy input or observation context differs")
    if a["supervision_values"] != b["supervision_values"]:
        raise ValueError("Target, WB or matrix values differ")
    if not {"packed", "variance", "colors", "wb", "matrix"} <= set(
        a["context"]["input_fingerprints"]
    ):
        raise ValueError("Missing physical-input fingerprints")


def analyze(
    first_manifest,
    first_sha,
    second_manifest,
    second_sha,
    output,
    *,
    expected_images=427,
    source_ids=None,
    maximum_seconds=600,
):
    """Pool four CFAs per source/condition, then report equal-source summaries."""
    if os.environ.get("CUDA_VISIBLE_DEVICES") != "":
        raise RuntimeError("Explicit CPU-only environment required")
    sources = None if source_ids is None else set(source_ids)
    first, second = (
        read_records(first_manifest, first_sha),
        read_records(second_manifest, second_sha),
    )
    if first.keys() != second.keys():
        raise ValueError("Matched photographic coverage differs")
    for key in first:
        matched(first[key], second[key])
    output = Path(output)
    output.mkdir(exist_ok=False)
    began = time.monotonic()
    c = basis(16)
    frequencies = np.arange(16) / 32
    radius = np.hypot(frequencies[:, None], frequencies[None, :])
    band = (radius >= 1 / 8) & (radius < 1 / 3)
    maximum_error, transforms = 0.0, 0
    checked, supervision_cache = set(), {}

    def guard():
        if time.monotonic() - began > maximum_seconds:
            raise TimeoutError("Declared CPU analysis deadline")
        if psutil.virtual_memory().available < 8 * 2**30:
            raise RuntimeError("Less than8GiB available RAM")

    def load(item, *, supervision=False):
        key = (item["path"], item["sha256"])
        if key not in checked:
            if binding(item["path"]) != item:
                raise ValueError("Changed retained array")
            checked.add(key)
        if supervision:
            if key not in supervision_cache:
                with np.load(item["path"], allow_pickle=False) as archive:
                    values = {k: archive[k] for k in archive.files}
                if len(supervision_cache) >= 4:
                    supervision_cache.pop(next(iter(supervision_cache)))
                supervision_cache[key] = values
            return supervision_cache[key]
        return np.load(item["path"], allow_pickle=False)

    def transform(value):
        nonlocal maximum_error, transforms
        coefficients = c @ value @ c.T
        independent = fft_dct(fft_dct(value, -1), -2)
        np.testing.assert_allclose(coefficients, independent, rtol=1e-11, atol=1e-13)
        maximum_error = max(maximum_error, float(np.max(np.abs(coefficients - independent))))
        transforms += len(value)
        return coefficients[..., band]

    sums = defaultdict(
        lambda: {"GT_energy": 0.0, "cross": 0.0, "prediction_energy": 0.0, "blocks": 0}
    )
    coverage, gt, input_rows = set(), {}, []
    for key, a in first.items():
        guard()
        b = second[key]
        ids, condition, pattern = key
        indices = [
            i
            for i, source in enumerate(ids)
            if len(source) == 40
            and all(ch in "0123456789abcdef" for ch in source)
            and (sources is None or source in sources)
        ]
        if not indices:
            continue
        left, right = (load(r["supervision"], supervision=True) for r in (a, b))
        for row, values in ((a, left), (b, right)):
            if any(
                fingerprint(values[k]) != value for k, value in row["supervision_values"].items()
            ):
                raise ValueError("Supervision fingerprint differs")
        if any(not np.array_equal(left[k], right[k]) for k in ("target", "wb", "matrix")):
            raise ValueError("Retained supervision differs")
        predictions = [load(row["prediction"]) for row in (a, b)]
        for value, row in zip(predictions, (a, b), strict=True):
            if (
                value.shape != left["target"].shape
                or value.dtype != np.float32
                or not np.isfinite(value).all()
                or fingerprint(value) != row["prediction_values"]
            ):
                raise ValueError("Prediction values differ from native FP32 record")
        input_rows.append(
            {
                "context": a["context"],
                "first": {k: a[k] for k in ("prediction", "supervision")},
                "second": {k: b[k] for k in ("prediction", "supervision")},
            }
        )
        for i in indices:
            source = ids[i]
            observation = (source, condition, pattern)
            if observation in coverage:
                raise ValueError("Duplicated source/noise/CFA observation")
            coverage.add(observation)
            data = {k: left[k][i : i + 1] for k in ("target", "wb", "matrix")}
            identity = {k: fingerprint(v) for k, v in data.items()}
            if source not in gt:
                rgb, y = luminance(data["target"], data)
                tb = blocks(y)
                t = transform(tb)
                energy = np.sum(t * t, axis=1)
                mean = tb.mean(axis=(1, 2))
                rms = np.sqrt(energy / 256)
                valid = (mean >= 0.02) & (mean <= 0.9) & (rms >= 1e-5)
                for channel in rgb[0]:
                    tile = blocks(channel)
                    valid &= np.all((tile >= 0) & (tile <= 1), axis=(1, 2))
                bins = np.searchsorted(EDGES, rms / np.maximum(mean, 1e-30), side="right") - 1
                gt[source] = {
                    "identity": identity,
                    "coefficients": t,
                    "energy": energy,
                    "mean": mean,
                    "rms": rms,
                    "valid": valid,
                    "bins": bins,
                }
            reference = gt[source]
            if identity != reference["identity"]:
                raise ValueError("GT/WB/matrix changes across noise conditions or CFAs")
            for label, value in zip(("first", "second"), predictions, strict=True):
                p = transform(blocks(luminance(value[i : i + 1], data)[1]))
                cross = np.sum(p * reference["coefficients"], axis=1)
                power = np.sum(p * p, axis=1)
                for index in range(5):
                    selected = reference["valid"] & (reference["bins"] == index)
                    if not selected.any():
                        continue
                    item = sums[(source, condition, index, label)]
                    item["GT_energy"] += float(reference["energy"][selected].sum())
                    item["cross"] += float(cross[selected].sum())
                    item["prediction_energy"] += float(power[selected].sum())
                    item["blocks"] += int(selected.sum())
    if len(gt) != expected_images or len(coverage) != expected_images * 12:
        raise ValueError("Incomplete declared photographic cohort")
    if sources is not None and set(gt) != sources:
        raise ValueError("Declared source selection differs")
    per_source = [
        {
            "source_id": source,
            "condition": condition,
            "bin": index,
            "method": label,
            "sums": values,
            **reduce_sums(values),
        }
        for (source, condition, index, label), values in sorted(sums.items())
    ]
    summaries = []
    for condition in sorted(CONDITIONS):
        for index in range(5):
            row = {
                "condition": condition,
                "bin": index,
                "relative_GT_band_RMS_lower": float(EDGES[index]),
                "relative_GT_band_RMS_upper": float(EDGES[index + 1]) if index < 4 else None,
            }
            grouped = {
                label: [
                    r
                    for r in per_source
                    if r["condition"] == condition and r["bin"] == index and r["method"] == label
                ]
                for label in ("first", "second")
            }
            if not grouped["first"]:
                continue
            for label, values in grouped.items():
                pooled = {k: sum(r["sums"][k] for r in values) for k in values[0]["sums"]}
                row[label] = {
                    "contributing_sources": len(values),
                    "pooled": reduce_sums(pooled),
                    "source_balanced": {
                        k: float(np.mean([r[k] for r in values]))
                        for k in (
                            "GT_projected_gain",
                            "GT_band_RMS",
                            "band_error_RMS",
                            "orthogonal_band_RMS",
                        )
                    },
                }
            if [r["source_id"] for r in grouped["first"]] != [
                r["source_id"] for r in grouped["second"]
            ]:
                raise ValueError("Contrast-stratum source coverage differs")
            row["second_minus_first"] = {
                metric: row["second"]["source_balanced"][metric]
                - row["first"]["source_balanced"][metric]
                for metric in row["first"]["source_balanced"]
            }
            summaries.append(row)

    def save(name, value):
        with (output / name).open("x") as stream:
            json.dump(value, stream, indent=2, allow_nan=False)
            stream.write("\n")
        return binding(output / name)

    source_rows = save("per-source-v1.json", per_source)
    inputs = save("selected-inputs-v1.json", input_rows)
    ids = sorted(gt)
    np.savez(
        output / "GT-strata-v1.npz",
        source_ids=np.array(ids),
        eligible=np.stack([gt[s]["valid"] for s in ids]),
        bins=np.stack([gt[s]["bins"] for s in ids]),
        GT_band_RMS=np.stack([gt[s]["rms"] for s in ids]),
        GT_mean_luminance=np.stack([gt[s]["mean"] for s in ids]),
    )
    result = {
        "first_manifest": binding(first_manifest),
        "second_manifest": binding(second_manifest),
        "first_checkpoint_sha256": first_sha,
        "second_checkpoint_sha256": second_sha,
        "photographic_sources": len(gt),
        "paired_source_noise_CFA_observations": len(coverage),
        "unique_source_blocks": len(gt) * 225,
        "block_observations_per_method": len(coverage) * 225,
        "summaries": summaries,
        "per_source": source_rows,
        "retained_inputs": inputs,
        "GT_strata": binding(output / "GT-strata-v1.npz"),
        "native16_blocks_transformed": transforms,
        "maximum_explicit_cosine_vs_even_FFT_absolute_error": maximum_error,
        "array_files_checked": len(checked),
        "seconds": time.monotonic() - began,
        "new_neural_forwards": 0,
        "new_noise_observations": 0,
        "RAW_decodes": 0,
        "scope": "Descriptive local linear-luminance detail audit of matched final20k single-view saved outputs. Three fixed noise priors/four CFAs; GT-only native16 DCT radial[1/8,1/3), RMS/mean bins0/.02/.05/.10/.20, mean .02-.9, band RMS>=1e-5, GT RGB inside[0,1]. Equal source weight after pooling four CFAs within source/condition. Unique block counts do not multiply independent material coverage by noise/CFA count. Coarse-boundary leakage and chance noise/GT correlation remain; no debiasing, SOTA, uncertainty or carrier-recovery claim.",
    }
    save("result-v1.json", result)
    return result

"""Analyze retained independent-noise endpoints and render native comparisons."""

import argparse
import json
import sys
from collections import defaultdict
from pathlib import Path

import numpy as np
from PIL import Image, ImageDraw
from train_directional_bank_trial import guard, read, ref, save

from demosaic.archive_metrics import display, linear_rgb, noisy_malvar
from demosaic.conditional_bias import error_moments
from demosaic.prediction_archive import iter_predictions

PATTERNS = ("RGGB", "BGGR", "GRBG", "GBRG")
EDGES = (0, 0.02, 0.05, 0.1, 0.2, None)


def bias_fraction(moments):
    mse = moments["empirical_per_draw_MSE"]
    return moments["unbiased_squared_conditional_bias"] / mse if mse else None


def checked(binding):
    if ref(binding["path"]) != binding:
        raise ValueError("Retained conditional-response artifact changed")
    return Path(binding["path"])


def validate_observations(cases, observations):
    ids = [case["id"] for case in cases]
    if not ids or len(set(ids)) != len(ids):
        raise ValueError("Declare distinct conditional-response targets")
    expected = {(case, pattern, draw) for case in ids for pattern in PATTERNS for draw in range(8)}
    actual = [(row["case_id"], row["pattern"], row["draw"]) for row in observations]
    if len(actual) != len(set(actual)) or set(actual) != expected:
        raise ValueError("Observations must cover eight distinct draws of every target/CFA")
    names = [row["id"] for row in observations]
    if len(names) != len(set(names)):
        raise ValueError("Observation IDs must be unique")
    return len(expected)


def dct_band(values):
    values = np.asarray(values, dtype=np.float64)
    if values.shape[-2:] == (256, 256):
        values = values[..., 48:208, 48:208]
    if values.ndim != 4 or values.shape[1:] != (3, 160, 160):
        raise ValueError("Expected native Bx3x160x160 or 256px contexts")
    c = np.cos(np.pi * (np.arange(16)[None, :] + 0.5) * np.arange(16)[:, None] / 16)
    c *= np.sqrt(2 / 16)
    c[0] /= np.sqrt(2)
    f = np.arange(16) / 32
    radius = np.hypot(f[:, None], f[None, :])
    band = (radius >= 1 / 8) & (radius < 1 / 3)
    luma = np.einsum("c,bchw->bhw", np.array([0.2126, 0.7152, 0.0722]), values)
    blocks = luma.reshape(len(values), 10, 16, 10, 16).transpose(0, 1, 3, 2, 4)
    blocks = blocks.reshape(len(values), 100, 16, 16)
    return (c @ blocks @ c.T)[..., band], blocks.mean(axis=(-2, -1))


def group_statistics(values, data):
    target = data["target"][0]
    pixel = error_moments(values[..., 48:208, 48:208], target[..., 48:208, 48:208])
    rendered = linear_rgb(
        values,
        {
            "wb": np.repeat(data["wb"], 8, axis=0),
            "matrix": np.repeat(data["matrix"], 8, axis=0),
        },
    )
    reference = linear_rgb(data["target"], data)
    coefficients, _ = dct_band(rendered)
    truth, means = dct_band(reference)
    truth, means = truth[0], means[0]
    rgb = reference[0, :, 48:208, 48:208]
    valid = ((rgb >= 0) & (rgb <= 1)).all(0).reshape(10, 16, 10, 16)
    valid = valid.transpose(0, 2, 1, 3).reshape(100, 256).all(1)
    rms = np.sqrt(np.sum(truth**2, axis=-1) / 256)
    valid &= (means >= 0.02) & (means <= 0.9) & (rms >= 1e-5)
    contrast = rms / np.maximum(means, 1e-12)
    local = []
    for index, high in enumerate(EDGES[1:]):
        selected = valid & (contrast >= EDGES[index])
        if high is not None:
            selected &= contrast < high
        if not selected.any():
            continue
        p, t = coefficients[:, selected], truth[selected]
        moments = error_moments(p, t)
        gains = np.sum(p * t, axis=(1, 2)) / np.sum(t**2)
        local.append(
            {
                "bin": index,
                "blocks": int(selected.sum()),
                "moments": moments,
                "reference_projected_gain_mean": float(gains.mean()),
                "reference_projected_gain_draw_std": float(gains.std(ddof=1)),
                "bias_fraction_estimate": bias_fraction(moments),
            }
        )
    return {
        "camera_RGB_moments": pixel,
        "camera_RGB_bias_fraction_estimate": bias_fraction(pixel),
        "local_band": local,
    }


def aggregate(rows, cases, labels):
    summaries = []
    for case in cases:
        for label in labels:
            groups = [r for r in rows if r["case_id"] == case["id"] and r["method"] == label]
            if len(groups) != 4 or {r["pattern"] for r in groups} != set(PATTERNS):
                raise ValueError("Conditional summaries require four separate CFA groups")
            pixel = {
                key: float(np.mean([r["camera_RGB_moments"][key] for r in groups]))
                for key in groups[0]["camera_RGB_moments"]
                if key != "draws"
            }
            bands = []
            for index in range(5):
                selected = [b for r in groups for b in r["local_band"] if b["bin"] == index]
                if not selected:
                    continue
                if len(selected) != 4 or len({s["blocks"] for s in selected}) != 1:
                    raise ValueError("Reference-selected local strata differ across CFAs")
                moments = {
                    key: float(np.mean([b["moments"][key] for b in selected]))
                    for key in selected[0]["moments"]
                    if key != "draws"
                }
                bands.append(
                    {
                        "bin": index,
                        "unique_reference_blocks": selected[0]["blocks"],
                        "mean_gain": float(
                            np.mean([b["reference_projected_gain_mean"] for b in selected])
                        ),
                        "moments": moments,
                        "bias_fraction_estimate": bias_fraction(moments),
                    }
                )
            summaries.append(
                {
                    "case_id": case["id"],
                    "method": label,
                    "reference_role": case["reference_role"],
                    "camera_RGB_moments": pixel,
                    "camera_RGB_bias_fraction_estimate": bias_fraction(pixel),
                    "local_band": bands,
                }
            )
    return summaries


def analyze(plan_path, collection_path):
    plan = read(plan_path)
    guard(plan)
    root = Path(plan["root"])
    (root / "analysis.claim").open("x").close()
    collection = read(collection_path)
    if collection["plan"] != ref(plan_path):
        raise ValueError("Conditional collection refers to a different execution plan")
    labels = [m["label"] for m in plan["retained_methods"] + plan["methods"]]
    declared = {
        m["label"]: m["checkpoint"]["sha256"] for m in plan["retained_methods"] + plan["methods"]
    }
    if len(labels) != len(set(labels)):
        raise ValueError("Retained controls and new endpoints must have distinct labels")
    expected_count = validate_observations(plan["cases"], plan["observations"])
    observations = {(o["case_id"], o["pattern"], o["draw"]): o for o in plan["observations"]}
    cases = {case["id"]: case for case in plan["cases"]}
    groups, targets, records = defaultdict(dict), {}, {}
    archives = [plan["retained_archive"]]
    if collection.get("archive"):
        archives.append(collection["archive"])
    for archive in archives:
        for record, prediction, data in iter_predictions(checked(archive)):
            context = record["context"]
            method = record["model"]["label"]
            if method not in labels:
                raise ValueError("Unexpected method in retained conditional archive")
            if record["model"]["sha256"] != declared[method] or record["model"]["step"] != 20000:
                raise ValueError("Conditional prediction checkpoint or completed step differs")
            key = method, context["case_id"], context["pattern"]
            observed = observations[(*key[1:], context["draw"])]
            for field in ("id", "seed", "input_fingerprints"):
                if context[field] != observed[field]:
                    raise ValueError("Conditional observation identity/fingerprint differs")
            if context["noise"] != plan["noise"]:
                raise ValueError("Conditional noise profile differs")
            draw = context["draw"]
            if draw in groups[key] or record["model"]["self_ensemble"] != "none":
                raise ValueError("Duplicate or non-single-view conditional prediction")
            groups[key][draw] = prediction[0]
            if key in targets and any(
                not np.array_equal(v, targets[key][k]) for k, v in data.items()
            ):
                raise ValueError("Target or display metadata differs between noise draws")
            targets[key] = data
            records[(*key, draw)] = record
    if len(groups) != len(labels) * len(cases) * 4:
        raise ValueError("Conditional archive model/target/CFA coverage differs")
    rows = []
    for (method, case, pattern), group in groups.items():
        if set(group) != set(range(8)):
            raise ValueError("Every CFA needs exactly eight independent draws")
        values = np.stack([group[k] for k in range(8)]).astype(np.float64)
        with np.load(checked(cases[case]["target"]), allow_pickle=False) as original:
            if any(
                not np.array_equal(v, original[k])
                for k, v in targets[(method, case, pattern)].items()
            ):
                raise ValueError("Conditional reference differs from the original fixed target")
        rows.append(
            {
                "method": method,
                "case_id": case,
                "pattern": pattern,
                "reference_role": cases[case]["reference_role"],
                **group_statistics(values, targets[(method, case, pattern)]),
            }
        )
    summaries = aggregate(rows, plan["cases"], labels)
    output = Path(plan["work"]) / "artifacts/analysis"
    output.mkdir(parents=True, exist_ok=False)
    images = []
    for case in plan["cases"]:
        identity = case["id"]
        with np.load(checked(case["target"]), allow_pickle=False) as archive:
            data = {k: archive[k] for k in archive.files}
        observed = observations[(identity, "RGGB", 0)]
        with np.load(checked(observed["arrays"]), allow_pickle=False) as archive:
            noisy = {k: archive[k] for k in archive.files}

        def pixels(value, metadata=data):
            return np.rint(
                display(value, metadata)[0, :, 48:208, 48:208].transpose(1, 2, 0) * 255
            ).astype(np.uint8)

        noisy_pixels, truth_pixels = pixels(noisy_malvar(noisy)), pixels(data["target"])
        for kind in ("single", "mean8-diagnostic"):
            panels, names = [noisy_pixels], ["Noisy draw0"]
            for label in labels:
                group = groups[(label, identity, "RGGB")]
                value = (
                    group[0][None]
                    if kind == "single"
                    else np.mean(np.stack([group[k].astype(np.float64) for k in range(8)]), axis=0)[
                        None
                    ]
                )
                panel = pixels(value)
                panels.append(panel)
                names.append(label + (" draw0" if kind == "single" else " mean8*"))
                if (
                    kind == "single"
                    and identity in plan["exact_synthetic_cases"]
                    and label in plan.get("triplet_arms", plan["new_arms"])
                ):
                    triplet = Image.new("RGB", (512, 192), "#eeeeee")
                    drawing = ImageDraw.Draw(triplet)
                    for i, (name, cell) in enumerate(
                        zip(
                            ["Noisy draw0", label + " draw0", "Exact synthetic GT"],
                            [noisy_pixels, panel, truth_pixels],
                            strict=True,
                        )
                    ):
                        drawing.text((8 + 168 * i, 5), name, fill="black")
                        triplet.paste(Image.fromarray(cell), (8 + 168 * i, 24))
                    target = output / f"{label}-{identity}-single-triplet.png"
                    triplet.save(target)
                    images.append(
                        {
                            "image": ref(target),
                            "kind": "single-triplet",
                            "case_id": identity,
                            "method": label,
                            "checkpoint": next(
                                m["checkpoint"]
                                for m in plan["retained_methods"] + plan["methods"]
                                if m["label"] == label
                            ),
                            "ROI_xywh": [48, 48, 160, 160],
                            "display_exposure": 1,
                            "noise": plan["noise"],
                            "reference_role": case["reference_role"],
                            "source": case,
                            "observation": observed,
                            "display_metadata": {k: data[k].tolist() for k in ("wb", "matrix")},
                            "pixel_scale": "native160; no resizing",
                        }
                    )
            panels.append(truth_pixels)
            names.append(
                "Exact synthetic GT"
                if identity in plan["exact_synthetic_cases"]
                else "Low-noise ref (not GT)"
            )
            board = Image.new("RGB", (8 + 168 * len(panels), 208), "#eeeeee")
            drawing = ImageDraw.Draw(board)
            for i, (name, cell) in enumerate(zip(names, panels, strict=True)):
                drawing.text((8 + 168 * i, 5), name, fill="black")
                board.paste(Image.fromarray(cell), (8 + 168 * i, 24))
            drawing.text(
                (8, 190),
                "Single draw0"
                if kind == "single"
                else "mean8*: eight independent observations; unavailable from one capture",
                fill="black",
            )
            target = output / f"{identity}-{kind}.png"
            board.save(target)
            images.append(
                {
                    "image": ref(target),
                    "kind": kind,
                    "case_id": identity,
                    "labels": names,
                    "ROI_xywh": [48, 48, 160, 160],
                    "display_exposure": 1,
                    "reference_role": case["reference_role"],
                    "noise": plan["noise"],
                    "source": case,
                    "scope": "Native160 cells; no resizing. mean8 is a multiple-observation diagnostic, not an inference improvement.",
                }
            )
    if "torch" in sys.modules:
        raise RuntimeError("Conditional analysis must remain NumPy-only")
    result = {
        "plan": ref(plan_path),
        "collection": ref(collection_path),
        "per_group": rows,
        "summaries": summaries,
        "images": images,
        "methods": plan["retained_methods"] + plan["methods"],
        "observations_per_model": expected_count,
        "retained_control_predictions_reused": expected_count * len(plan["retained_methods"]),
        "new_neural_forwards": 0,
        "new_encoder_forwards": 0,
        "new_noise_observations": 0,
        "RAW_decodes": 0,
        "optimizer_updates": 0,
        "Torch_imported": False,
        "native_review_status": "Native boards/triplets prepared; actual viewing remains pending",
        "scope": "Fixed four-target/eight-noise-draw diagnostic. CFAs analyzed separately. Signed finite-sample bias estimates retained; no population/seed interval, exact native GT or automatic recommendation change.",
    }
    save(root / "analysis-v1.json", result)
    print(json.dumps({"groups": len(rows), "summaries": len(summaries), "images": len(images)}))
    return root / "analysis-v1.json"


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("plan", type=Path)
    parser.add_argument("collection", type=Path)
    args = parser.parse_args()
    analyze(args.plan, args.collection)

"""Native comparisons from audited PNGs and retained full-frame GFX floats."""

import hashlib
import json
import shutil
from pathlib import Path

import numpy as np
from audit_quality_archive import _triplet, binding, write
from compare_quality_archives import canonical, read_bound
from PIL import Image, ImageDraw

from demosaic.archive_metrics import display, noisy_malvar
from demosaic.prediction_archive import fingerprint


def pixel_hash(pixels):
    return hashlib.sha256(np.ascontiguousarray(pixels).tobytes()).hexdigest()


def board(path, columns, labels, captions, provenance):
    """Copy native 160px cells; reopen every encoded cell before receipting."""
    path = Path(path)
    canvas = Image.new("RGB", (8 + 168 * len(columns), 8 + 188 * len(labels)), "#eeeeee")
    draw, cells = ImageDraw.Draw(canvas), []
    for col, (values, caption) in enumerate(zip(columns, captions, strict=True)):
        for row, (pixels, label) in enumerate(zip(values, labels, strict=True)):
            if pixels.dtype != np.uint8 or pixels.shape != (160, 160, 3):
                raise ValueError("Comparison cells must be native160 RGB8 pixels")
            x, y = 8 + 168 * col, 24 + 188 * row
            draw.text((x, y - 20), f"{caption}: {label}", fill="black")
            canvas.paste(Image.fromarray(pixels), (x, y))
            cells.append(
                {
                    "column": col,
                    "label": label,
                    "png_xywh": [x, y, 160, 160],
                    "pixel_sha256": pixel_hash(pixels),
                }
            )
    with path.open("xb") as stream:
        canvas.save(stream, format="PNG")
    with Image.open(path) as image:
        decoded = np.array(image)
    for cell in cells:
        x, y, w, h = cell["png_xywh"]
        if pixel_hash(decoded[y : y + h, x : x + w]) != cell["pixel_sha256"]:
            raise ValueError("Native comparison PNG changed a crop pixel")
    receipt = {
        "image": binding(path),
        "panels": cells,
        "sources": provenance,
        "pixel_scale": "One native image pixel per PNG pixel; no resizing",
        "review_status": "Prepared; human viewing pending",
    }
    write(path.with_suffix(".json"), receipt)
    return receipt


def triplet_pixels(receipt):
    read_bound_image = receipt["image"]
    if binding(read_bound_image["path"]) != read_bound_image:
        raise ValueError("Changed audited triplet image")
    with Image.open(read_bound_image["path"]) as image:
        pixels = np.array(image.convert("RGB"))
    result = []
    for panel in receipt["panels"]:
        x, y, w, h = panel["png_xywh"]
        crop = pixels[y : y + h, x : x + w]
        if crop.shape != (160, 160, 3) or pixel_hash(crop) != panel["pixel_sha256"]:
            raise ValueError("Changed native triplet panel")
        result.append(crop)
    if len(result) != 3:
        raise ValueError("Require noisy/restored/exact-GT triplets")
    return result


def matched_material_stage(stage, output):
    """Match the candidate's declared pair, rendering only missing saved controls.

    Different audits can legitimately declare different material examples. The
    full numerical join must already have established identical observations.
    Existing PNGs and receipts stay untouched; no model or noise is constructed.
    """
    if (
        stage["stage"] != "photo"
        or not stage["all_noisy_inputs_targets_masks_and_transforms_equal"]
    ):
        raise ValueError("Material matching requires the complete aligned photographic join")
    groups = {}
    for role in ("control", "candidate"):
        selected = [
            r
            for r in stage[f"{role}_native_triplets"]
            if {k: r["model"][k] for k in ("sha256", "self_ensemble")} == stage[role]["model"]
        ]
        groups[role] = {r["source_id"]: r for r in selected}
        if len(selected) != 2 or len(groups[role]) != 2:
            raise ValueError("Require two declared material triplets per endpoint")
    if groups["control"].keys() == groups["candidate"].keys():
        return stage
    manifest = stage["control"]["manifest"]
    if binding(manifest["path"]) != manifest:
        raise ValueError("Changed material prediction archive")
    root = Path(manifest["path"]).resolve().parent
    records = []
    for index, line in enumerate(Path(manifest["path"]).read_text().splitlines()):
        row = json.loads(line)
        if row["schema"] != "demosaic-predictions-v1" or row["index"] != index:
            raise ValueError("Material archive schema or sequence differs")
        if {k: row["model"][k] for k in ("sha256", "self_ensemble")} == stage["control"]["model"]:
            records.append(row)
    candidate_manifest = stage["candidate"]["manifest"]
    if binding(candidate_manifest["path"]) != candidate_manifest:
        raise ValueError("Changed candidate material archive")
    candidates = []
    for index, line in enumerate(Path(candidate_manifest["path"]).read_text().splitlines()):
        row = json.loads(line)
        if row["schema"] != "demosaic-predictions-v1" or row["index"] != index:
            raise ValueError("Candidate material archive schema or sequence differs")
        if {k: row["model"][k] for k in ("sha256", "self_ensemble")} == stage["candidate"]["model"]:
            candidates.append(row)
    output = Path(output)
    for source_id in sorted(groups["candidate"].keys() - groups["control"].keys()):
        anchor = groups["candidate"][source_id]
        matches = [
            row for row in records if canonical(row["context"]) == canonical(anchor["context"])
        ]
        if len(matches) != 1 or source_id not in matches[0]["context"]["ids"]:
            raise ValueError("Missing or duplicate exact material observation in control archive")
        row = matches[0]
        for key in ("prediction", "supervision"):
            path = Path(row[key]["path"])
            if not path.resolve().is_relative_to(root) or binding(path) != row[key]:
                raise ValueError("Changed or escaped material archive arrays")
        prediction = np.load(row["prediction"]["path"], allow_pickle=False)
        with np.load(row["supervision"]["path"], allow_pickle=False) as archive:
            targets = {k: archive[k].copy() for k in archive.files}
        if (
            fingerprint(prediction) != row["prediction_values"]
            or {k: fingerprint(v) for k, v in targets.items()} != row["supervision_values"]
        ):
            raise ValueError("Material prediction or exact-target values differ from the archive")
        candidate_matches = [
            candidate
            for candidate in candidates
            if candidate["prediction"] == anchor["prediction"]
            and canonical(candidate["context"]) == canonical(anchor["context"])
        ]
        if (
            len(candidate_matches) != 1
            or row["supervision_values"] != candidate_matches[0]["supervision_values"]
        ):
            raise ValueError("Material control and candidate exact supervision differ")
        output.mkdir(parents=True, exist_ok=True)
        groups["control"][source_id] = _triplet(
            output,
            row,
            prediction,
            targets,
            row["context"]["ids"].index(source_id),
            anchor["source"],
        )
    return {
        **stage,
        "control_native_triplets": [groups["control"][key] for key in sorted(groups["candidate"])],
        "candidate_native_triplets": [
            groups["candidate"][key] for key in sorted(groups["candidate"])
        ],
        "material_matching": "Candidate audit's declared pair; missing control PNG rendered from exact bound FP32 prediction/supervision, zero neural/noise/RAW calls",
    }


def photo_comparison(stage, output, *, labels=("V114 control", "V116 candidate")):
    """Preserve both complete candidate triplets plus a matched four-method board."""
    output = Path(output)
    indexed = []
    for role in ("control", "candidate"):
        selected = [
            r
            for r in stage[f"{role}_native_triplets"]
            if {k: r["model"][k] for k in ("sha256", "self_ensemble")} == stage[role]["model"]
        ]
        group = {r["source_id"]: r for r in selected}
        if len(group) != 2 or len(group) != len(selected):
            raise ValueError("Require the two declared material triplets per endpoint")
        indexed.append(group)
    if indexed[0].keys() != indexed[1].keys():
        raise ValueError("Material sources differ")
    columns, provenance, copies = [], [], []
    shared = (
        "source",
        "context",
        "ROI_xywh_in_retained_context",
        "native_context_shape",
        "white_balance",
        "camera_to_srgb",
        "display_exposure",
        "display_transform",
        "reference",
    )
    for i, source in enumerate(sorted(indexed[0])):
        old, new = (group[source] for group in indexed)
        if any(old[key] != new[key] for key in shared):
            raise ValueError("Triplet ROI, source, observation or display differs")
        a, b = triplet_pixels(old), triplet_pixels(new)
        if not np.array_equal(a[0], b[0]) or not np.array_equal(a[2], b[2]):
            raise ValueError("Material noisy/GT crop pixels differ")
        columns.append([a[0], a[1], b[1], a[2]])
        provenance.append({"control": old, "candidate": new})
        path = output / f"candidate-material-{i + 1}.png"
        with path.open("xb") as stream, Path(new["image"]["path"]).open("rb") as original:
            shutil.copyfileobj(original, stream)
        copied = {**new, "image": binding(path), "original_image": new["image"]}
        write(path.with_suffix(".json"), copied)
        copies.append(copied)
    result = board(
        output / "matched-materials.png",
        columns,
        ["Noisy", *labels, "Exact GT"],
        ["A", "B"],
        provenance,
    )
    return {"comparison": result, "candidate_triplets": copies}


def bound_array(item):
    if binding(item["path"]) != item:
        raise ValueError("Changed retained float array")
    value = np.load(item["path"], allow_pickle=False)
    if value.dtype != np.float32 or not np.isfinite(value).all():
        raise ValueError("GFX requires finite original FP32 values")
    return value


def gfx_comparison(
    control_result,
    candidate_result,
    control_sha,
    candidate_sha,
    output,
    *,
    labels=("V114 control", "V116 candidate"),
    allow_conditioning_difference=False,
):
    """Render all methods with one NumPy64 transform; ISO100 remains approximate."""
    stages = [read_bound(binding(path)) for path in (control_result, candidate_result)]
    reports = [read_bound(stage["report"]) for stage in stages]
    for field in ("selection", "sources", "reference_calibration"):
        if reports[0][field] != reports[1][field]:
            raise ValueError(f"GFX shared {field} differs")
    conditioning_matched = reports[0]["conditioning"] == reports[1]["conditioning"]
    if not conditioning_matched and not allow_conditioning_difference:
        raise ValueError("GFX shared conditioning differs")
    methods, tile_grids = [], []
    for stage, report, sha in zip(stages, reports, (control_sha, candidate_sha), strict=True):
        native = [r for r in stage["full_native_floats"] if r["checkpoint"]["sha256"] == sha]
        grids = []
        for item in native:
            timing = item.get("timing", {})
            grids.append(
                {
                    "alignment": timing.get(
                        "common_input_grid_alignment", timing.get("tile_grid_alignment")
                    ),
                    "tile": timing.get("tile"),
                    "overlap": timing.get("overlap"),
                    "stride": timing.get("tile_stride"),
                    "padded_shape": timing.get("common_grid_padded_shape"),
                }
            )
        if not grids or any(grid != grids[0] for grid in grids):
            raise ValueError("Inconsistent full-frame tile geometry within one method")
        tile_grids.append(grids[0])
        crops = [
            r for r in report["native_crops"] if r["checkpoint_sha256"] == sha and r["full_frame"]
        ]
        floats = {(r["region"]["name"], r["role"]): r for r in report["float_contexts"]}
        group, pixels = {}, {}
        for item in native:
            name = item["region"]["name"]
            crop = [r for r in crops if r["region"] == item["region"]]
            if name in group or len(crop) != 1:
                raise ValueError("Missing or duplicate full-frame native region")
            crop = crop[0]
            shared = {
                k: crop[k]
                for k in (
                    "region",
                    "conditioning",
                    "display_exposure",
                    "shared_wb",
                    "shared_matrix",
                    "reference",
                )
            }
            arrays, bindings, metadata = {}, {}, {}
            for role in ("noisy-packed", "reference-rgb"):
                receipt = floats[(name, role)]
                path = Path(stage["report"]["path"]).parent / receipt["image"]
                bindings[role] = {"path": str(path), "sha256": receipt["sha256"]}
                metadata[role] = {k: v for k, v in receipt.items() if k not in {"image", "sha256"}}
                arrays[role] = bound_array(bindings[role])
                if (
                    list(arrays[role].shape) != receipt["shape"]
                    or receipt["region"] != shared["region"]
                ):
                    raise ValueError("GFX float shape/ROI differs from receipt")
            prediction = bound_array(item["array"])
            if (
                prediction.shape != (1, 3, 160, 160)
                or arrays["reference-rgb"].shape != prediction.shape
            ):
                raise ValueError("Require native160 full-frame/reference floats")
            data = {
                "wb": np.array([shared["shared_wb"]], np.float64),
                "matrix": np.array([shared["shared_matrix"]], np.float64),
                "packed": arrays["noisy-packed"],
                "colors": np.array([["RGB".index(c) for c in metadata["noisy-packed"]["pattern"]]]),
            }
            nx, ny = shared["region"]["noisy_xy"]
            tx, ty, w, h = metadata["noisy-packed"]["context_xywh"]
            x, y = nx - tx, ny - ty
            if (w, h) != (512, 512) or min(x, y) < 0 or max(x + 160, y + 160) > 512:
                raise ValueError("GFX noisy ROI outside its retained context")
            noisy = noisy_malvar(data)[..., y : y + 160, x : x + 160]
            values = [noisy, prediction, arrays["reference-rgb"]]
            pixels[name] = [
                np.rint(
                    display(value.astype(np.float64), data, shared["display_exposure"])[
                        0
                    ].transpose(1, 2, 0)
                    * 255
                ).astype(np.uint8)
                for value in values
            ]
            group[name] = {
                "shared": shared,
                "float_metadata": metadata,
                "shared_float_bindings": bindings,
                "shared_value_sha256": {key: pixel_hash(value) for key, value in arrays.items()},
                "prediction": item,
                "report": stage["report"],
            }
        if len(group) != 6:
            raise ValueError("Require all six standing GFX regions")
        methods.append((group, pixels))
    (a, ap), (b, bp) = methods
    if a.keys() != b.keys():
        raise ValueError("GFX region coverage differs")
    names, columns, provenance = sorted(a), [], []
    for name in names:
        for key in ("shared", "float_metadata", "shared_value_sha256"):
            left, right = a[name][key], b[name][key]
            if key == "shared" and not conditioning_matched and allow_conditioning_difference:
                left = {k: v for k, v in left.items() if k != "conditioning"}
                right = {k: v for k, v in right.items() if k != "conditioning"}
            if canonical(left) != canonical(right):
                raise ValueError("GFX input/reference/transform values differ")
        if any(not np.array_equal(ap[name][i], bp[name][i]) for i in (0, 2)):
            raise ValueError("GFX common-render noisy/reference pixels differ")
        columns.append([ap[name][0], ap[name][1], bp[name][1], ap[name][2]])
        provenance.append({"control": a[name], "candidate": b[name]})
    if not conditioning_matched:
        profile_labels = []
        for index, report in enumerate(reports):
            source = report["conditioning"].get("source", "")
            profile_labels.append(
                "Haar"
                if source == "input Haar fit"
                else "nominal"
                if source == "nominal ISO prior (not calibrated)"
                else f"profile {index + 1}"
            )
        labels = tuple(
            label + " [" + profile + "]"
            for label, profile in zip(labels, profile_labels, strict=True)
        )
    prefix = "matched-gfx" if conditioning_matched else "conditioning-different-gfx"
    grid_matched = tile_grids[0] == tile_grids[1]
    if not grid_matched:
        labels = tuple(
            f"{label} [tile grid {grid['alignment']}px]"
            for label, grid in zip(labels, tile_grids, strict=True)
        )
        prefix = "grid-different-" + prefix
    boards = [
        board(
            Path(output) / f"{prefix}-{i // 3 + 1}.png",
            columns[i : i + 3],
            ["Noisy", *labels, "ISO100 ref (not GT)"],
            [str(j + 1) for j in range(i, i + 3)],
            provenance[i : i + 3],
        )
        for i in (0, 3)
    ]
    return {
        "boards": boards,
        "regions_in_column_order": names,
        "display": "Shared NumPy64 WB/matrix and exposure, clipped sRGB, round-to-nearest RGB8",
        "reference": "Independently demosaiced ISO100 f/5.6; aperture/moving-subject differences; not pixelwise GT",
        "conditioning_matched": conditioning_matched,
        "conditioning_by_method": [r["conditioning"] for r in reports],
        "tile_grid_matched": grid_matched,
        "tile_grid_by_method": tile_grids,
        "interpretation": (
            "Same noise conditioning across methods"
            if conditioning_matched
            else "Different noise conditioning is explicit in the image labels and metadata. These boards compare the recorded pipelines, and cannot isolate an architectural/model effect. Matching-profile full-frame comparison remains required."
        )
        + (
            " Tile grids differ as labeled. These saved pipeline outputs cannot isolate an architectural/model effect."
            if not grid_matched
            else ""
        ),
        "new_neural_forwards": 0,
        "RAW_decodes": 0,
        "quality_scores": None,
    }

