def build(manifest, output, report):
    data = json.loads(manifest.read_text())
    cases = []
    checkpoints = {}
    for item in data["images"]:
        if item["triplet"]:
            continue
        assert item["no_resize"]
        image = Path(item["image"]["path"])
        assert image.parent == output.parent and image.is_file()
        with Image.open(image) as pixels:
            width, height = pixels.size
        for panel in item["panels"]:
            x, y, w, h = panel["xywh"]
            assert w == h == 160 and 0 <= x <= width - w and 0 <= y <= height - h
        for label in item["predictions"]:
            if label.endswith(("-raw", "-EMA")):
                endpoint = label.rsplit("-", 1)[1]
                checkpoints[label] = data["checkpoints"][endpoint]["export"]["sha256"]
        cases.append(
            {
                "id": item["case"]["id"],
                "image": quote(image.name),
                "roi": item["ROI_xywh"],
                "anchor": item["anchor"],
                "exposure": item["exposure"],
                "contrast": item["contrast"],
                "panels": item["panels"],
                "predictions": list(item["predictions"]),
            }
        )
    assert cases
    payload = json.dumps({"cases": cases, "checkpoints": checkpoints}, ensure_ascii=True).replace(
        "<", "\\u003c"
    )
    rendered = TEMPLATE.replace("__DATA__", payload).replace("__REPORT__", html.escape(report))
    with output.open("x") as stream:
        stream.write(rendered)
    print(f"Built {len(cases)} native cases, without resampling pixels: {output}")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("manifest", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--report", required=True)
    args = parser.parse_args()
    build(
        args.manifest.resolve(),
        (args.output or args.manifest.with_name("native-viewer.html")).resolve(),
        args.report,
    )

"""Training-only response supervision on physically coupled counterfactual pairs."""

import math

import torch


@torch.no_grad()
def paired_sensor_increment_units(clean_a, clean_b, shot, *, floor_DN16=16):
    """Nominal std of the coupled sensor difference, with a fixed DN16 floor.

    Common Poisson counts and Gaussian read noise cancel before ADC; the
    remaining variance is effective_shot*abs(clean_a-clean_b). These are
    sensor-increment training units, not restored RGB covariance/confidence.
    The inherited positive-shot floor is 1e-12. Targets/units never enter forward.
    """
    if clean_a.ndim != 4 or clean_a.shape != clean_b.shape or min(clean_a.shape) < 1:
        raise ValueError("Expected matching nonempty N x C x H x W sensor tensors")
    if not all(v.is_floating_point() and torch.isfinite(v).all() for v in (clean_a, clean_b)):
        raise ValueError("Sensor values must be finite floating-point tensors")
    if clean_a.device != clean_b.device or (clean_a < 0).any() or (clean_b < 0).any():
        raise ValueError("Sensor values must be nonnegative on the same device")
    if not math.isfinite(floor_DN16) or floor_DN16 <= 0:
        raise ValueError("Noise-unit floor must be positive and finite")
    dtype = torch.float64 if clean_a.dtype == torch.float64 else torch.float32
    a, b = clean_a.to(dtype), clean_b.to(dtype)
    coefficient = torch.as_tensor(shot, device=a.device, dtype=dtype)
    if not torch.isfinite(coefficient).all() or (coefficient < 0).any():
        raise ValueError("Shot coefficient must be finite and nonnegative")
    try:
        coefficient = torch.broadcast_to(coefficient, a.shape)
    except RuntimeError as error:
        raise ValueError("Shot coefficient must broadcast within the sensor shape") from error
    coefficient = torch.where(coefficient > 0, coefficient.clamp_min(1e-12), coefficient)
    variance = coefficient * (a - b).abs()
    if variance.shape != a.shape:
        raise ValueError("Shot coefficient must broadcast within the sensor shape")
    return variance.mean((1, 2, 3), keepdim=True).sqrt().clamp_min(floor_DN16 / 65535)


def paired_response_loss(output, target, units, pairs, *, epsilon=0.003):
    """Stable Charbonnier of restored-minus-target pair differences.

    Each model forward sees one noisy image and its supplied parent. This loss
    operates afterwards on disjoint aligned pairs, including exactly unchanged
    target regions. It is blind to RGB errors shared by both members, so ordinary
    RGB/local/DC losses remain necessary. No inference gate or flat guarantee.
    """
    if output.ndim != 4 or output.shape[1] != 3 or min(output.shape) < 1:
        raise ValueError("Expected nonempty N x 3 x H x W output")
    if target.shape != output.shape or not all(v.is_floating_point() for v in (output, target)):
        raise ValueError("Output and target must be matching floating-point RGB")
    if not math.isfinite(epsilon) or epsilon <= 0:
        raise ValueError("Charbonnier epsilon must be positive and finite")
    indices = torch.as_tensor(pairs, device=output.device)
    if (
        indices.dtype != torch.int64
        or indices.ndim != 2
        or indices.shape[1] != 2
        or len(indices) < 1
    ):
        raise ValueError("Expected nonempty P x 2 int64 pair indices")
    if (
        indices.min() < 0
        or indices.max() >= len(output)
        or indices.unique().numel() != indices.numel()
    ):
        raise ValueError("Pair members must be distinct and in range")
    if units.shape != (len(indices), 1, 1, 1) or not units.is_floating_point():
        raise ValueError("Expected one floating-point unit per pair")
    if not torch.isfinite(units).all() or (units <= 0).any():
        raise ValueError("Pair units must be positive and finite")
    dtype = torch.float64 if output.dtype == torch.float64 else torch.float32
    with torch.autocast(output.device.type, enabled=False):
        value, clean = output.to(dtype), target.detach().to(device=output.device, dtype=dtype)
        scale = units.detach().to(device=output.device, dtype=dtype)
        first, second = indices.unbind(1)
        residual = ((value[first] - value[second]) - (clean[first] - clean[second])) / scale
        power = residual.square()
        return (power / ((power + epsilon**2).sqrt() + epsilon)).mean()

"""Share verified checkpoint copies in completed evaluations; preserve all paths/bytes.

Only report-owned content-addressed snapshots are eligible. Original model
archives and all active input directories/inodes remain physically separate.
"""

import argparse
import fcntl
import hashlib
import json
import os
import re
import stat
import time
from collections import defaultdict
from pathlib import Path

import psutil

from demosaic.safety import writable_path


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def ref(path):
    return {"path": str(Path(path).resolve()), "sha256": sha(path)}


def read(path):
    return json.loads(Path(path).read_text())


def save(path, value):
    path = Path(path)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(json.dumps(value, indent=2, allow_nan=False) + "\n")
    temporary.replace(path)


def props(path):
    s = Path(path).stat()
    return {
        "device": s.st_dev,
        "inode": s.st_ino,
        "size": s.st_size,
        "allocated": s.st_blocks * 512,
        "mode": s.st_mode,
        "mtime_ns": s.st_mtime_ns,
        "uid": s.st_uid,
        "gid": s.st_gid,
        "links": s.st_nlink,
    }


def inode(properties):
    return properties["device"], properties["inode"]


def check_refs(items):
    for item in items:
        require(ref(item["path"]) == item, f"Protected file changed: {item['path']}")


def collect_active(plans):
    """Bind existing immutable inputs/sources and reserve whole input directories."""
    references, directories, inodes = {}, set(), set()
    for filename in plans:
        value = read(filename)
        references[str(Path(filename).resolve())] = ref(filename)
        for item in value.get("inputs", []):
            references[item["path"]] = item
        for path, digest in value.get("frozen_files", {}).items():
            references[path] = {"path": path, "sha256": digest}
    check_refs(references.values())
    for path in references:
        p = Path(path)
        if p.is_file():
            directories.add(p.parent)
            inodes.add(inode(props(p)))
    return list(references.values()), directories, inodes


def prepare(root, evaluation, inventory, active_plans):
    root, evaluation = writable_path(root), writable_path(evaluation)
    require(not root.exists(), "Use a fresh consolidation root")
    protected, directories, protected_inodes = collect_active(active_plans)
    # Stat-only enumeration: never read or modify these original archives.
    archives = {}
    for name in ("models", "runs", "benchmarks", "references"):
        for path in (evaluation.parent / name).rglob("*.pt"):
            if path.is_file() and not path.is_symlink():
                archives[str(path)] = props(path)
    archive_inodes = {inode(value) for value in archives.values()}
    files, artifact_dirs, skipped = {}, set(), []
    for group in read(inventory)["candidate_groups"]:
        for candidate in group["files"]:
            path = Path(candidate["path"])
            if path.suffix != ".pt" or path.parent.name != "weights":
                continue
            if not path.is_relative_to(evaluation) or path.resolve() != path:
                continue
            match = re.fullmatch(r"weights-([0-9a-f]{64})\.pt", path.name)
            if match is None or any(path.is_relative_to(folder) for folder in directories):
                continue
            value = props(path)
            if inode(value) in archive_inodes | protected_inodes:
                continue
            if value["uid"] != os.getuid() or not stat.S_ISREG(value["mode"]):
                continue
            reports = [path.parent.parent / name for name in ("summary.json", "report.json")]
            report = next((p for p in reports if p.exists()), None)
            if report is None:
                continue
            data = read(report)
            if "native_crops" not in data or not any(
                model.get("sha256") == match[1] and model.get("snapshot") == str(path)
                for model in data.get("models", [])
            ):
                skipped.append(str(path))
                continue
            files[str(path)] = {"sha256": match[1], "properties": value}
            artifact_dirs.add(path.parent.parent)
    by_digest = defaultdict(list)
    for path, value in files.items():
        by_digest[value["sha256"]].append(path)
    groups = []
    for digest, paths in by_digest.items():
        unique = defaultdict(list)
        for path in paths:
            unique[inode(files[path]["properties"])].append(path)
        if len(unique) < 2:
            continue
        # Prefer a previously immutable/shared evaluation copy. Never an archive.
        ordered = sorted(
            unique.values(),
            key=lambda p: (bool(files[p[0]]["properties"]["mode"] & 0o222), -len(p), p[0]),
        )
        canonical = ordered[0][0]
        targets = [
            p[0] for p in ordered[1:] if len(p) == 1 and files[p[0]]["properties"]["links"] == 1
        ]
        if targets:
            groups.append({"sha256": digest, "canonical": canonical, "targets": targets})
    require(bool(groups), "No eligible completed snapshot copies")
    unchanged = []
    for folder in sorted(artifact_dirs):
        for path in sorted(folder.rglob("*")):
            if path.is_file() and path.suffix.lower() in {".json", ".jsonl", ".png", ".md"}:
                unchanged.append(ref(path))
    root.mkdir(parents=True)
    plan = {
        "driver": ref(__file__),
        "evaluation": str(evaluation),
        "inventory": ref(inventory),
        "active_plans": [str(Path(p).resolve()) for p in active_plans],
        "protected": protected,
        "original_archive_properties": archives,
        "files": files,
        "groups": groups,
        "unchanged_report_metric_native_artifacts": unchanged,
        "expected_reclaimed_allocated_bytes": sum(
            files[p]["properties"]["allocated"] for g in groups for p in g["targets"]
        ),
        "skipped_unbound_report_snapshots": skipped,
        "scope": "Owned completed report checkpoint copies only. Full SHA verification required before replacement. All target paths/bytes/hashes retained; shared copies become read-only. Original archives, active-input directories/inodes, images, crops, metrics, training, evaluation and downloading remain untouched.",
    }
    save(root / "plan.json", plan)
    return plan


def replace_verified_copy(path, source, digest, expected):
    """Retain the old inode until the verified atomic replacement succeeds."""
    path, source = Path(path), Path(source)
    require(
        props(path) == expected and expected["links"] == 1, "Target snapshot properties changed"
    )
    require(source.stat().st_mode & 0o222 == 0, "Canonical snapshot must be immutable")
    require(path.stat().st_dev == source.stat().st_dev, "Snapshots use different filesystems")
    require(sha(path) == digest and sha(source) == digest, "Snapshot checksum differs")
    temporary = path.with_name(path.name + f".new-link-{os.getpid()}")
    backup = path.with_name(path.name + f".old-link-{os.getpid()}")
    require(not temporary.exists() and not backup.exists(), "Replacement temporary path exists")
    os.link(path, backup)
    try:
        os.link(source, temporary)
        require(temporary.samefile(source), "Temporary link has wrong inode")
        os.replace(temporary, path)
        require(path.samefile(source) and sha(path) == digest, "Replacement verification failed")
    except BaseException:
        os.replace(backup, path)
        raise
    finally:
        temporary.unlink(missing_ok=True)
    backup.unlink()


def apply(root):
    root = writable_path(root)
    plan = read(root / "plan.json")
    require(ref(__file__) == plan["driver"], "Consolidation driver changed")
    require(not (root / "result.json").exists(), "Consolidation already completed")
    evaluation = writable_path(plan["evaluation"])
    check_refs(plan["protected"])
    check_refs(plan["unchanged_report_metric_native_artifacts"])
    for path, properties in plan["original_archive_properties"].items():
        require(props(path) == properties, "Original archive metadata changed")
    protected_directories = {Path(item["path"]).parent for item in plan["protected"]}
    excluded_inodes = {inode(value) for value in plan["original_archive_properties"].values()}
    excluded_inodes.update(inode(props(item["path"])) for item in plan["protected"])
    for group in plan["groups"]:
        for filename in [group["canonical"], *group["targets"]]:
            path = Path(filename)
            require(
                path == path.resolve()
                and path.is_relative_to(evaluation)
                and path.parent.name == "weights"
                and path.name == f"weights-{group['sha256']}.pt"
                and not any(path.is_relative_to(folder) for folder in protected_directories)
                and inode(props(path)) not in excluded_inodes,
                "Snapshot path escapes eligible inactive evaluation storage",
            )
    # No current project's writer may target a completed evaluation directory.
    for process in psutil.process_iter(["pid", "cmdline"]):
        try:
            if process.pid != os.getpid():
                require(
                    not any(
                        plan["evaluation"] + "/" in argument
                        for argument in process.info["cmdline"] or []
                    ),
                    "A process still references the evaluation tree",
                )
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue
    with (root / "claim").open("x") as claim:
        claim.write(str(os.getpid()))
    cache = Path(plan["evaluation"]) / ".checkpoint-cache"
    cache.mkdir(exist_ok=True)
    changes = []
    for group_index, group in enumerate(plan["groups"], 1):
        require(psutil.virtual_memory().available >= 24 * 2**30, "Less than24GiB available RAM")
        digest, source = group["sha256"], Path(group["canonical"])
        with (cache / f"{digest}.lock").open("a") as lock:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
            require(
                props(source) == plan["files"][str(source)]["properties"],
                "Canonical snapshot changed",
            )
            # Validate the entire group before its first mutation.
            for path in [str(source), *group["targets"]]:
                require(
                    props(path) == plan["files"][path]["properties"] and sha(path) == digest,
                    "Snapshot changed or has corrupt bytes",
                )
            source.chmod(0o444)
            for filename in group["targets"]:
                replace_verified_copy(
                    filename, source, digest, plan["files"][filename]["properties"]
                )
                change = {
                    "path": filename,
                    "canonical": str(source),
                    "sha256": digest,
                    "old_properties": plan["files"][filename]["properties"],
                    "new_properties": props(filename),
                }
                changes.append(change)
                with (root / "changes.jsonl").open("a") as stream:
                    stream.write(json.dumps(change) + "\n")
        save(
            root / "status.json",
            {
                "status": "consolidating-completed-evaluation-snapshots",
                "owner": {"pid": os.getpid(), "created": psutil.Process().create_time()},
                "groups_done": group_index,
                "replacements": len(changes),
                "updated_unix": time.time(),
            },
        )
        print(
            json.dumps(
                {
                    "replacements": len(changes),
                    "expected_total": sum(len(g["targets"]) for g in plan["groups"]),
                }
            ),
            flush=True,
        )
    check_refs(plan["protected"])
    check_refs(plan["unchanged_report_metric_native_artifacts"])
    for path, properties in plan["original_archive_properties"].items():
        require(props(path) == properties, "Original archive metadata changed")
    result = {
        "status": "completed-byte-preserving-owned-evaluation-snapshot-consolidation",
        "plan": ref(root / "plan.json"),
        "driver": ref(__file__),
        "replacements": len(changes),
        "checkpoint_digests": len(plan["groups"]),
        "reclaimed_allocated_bytes": sum(x["old_properties"]["allocated"] for x in changes),
        "protected_files_checked": len(plan["protected"]),
        "report_metric_native_files_unchanged": len(
            plan["unchanged_report_metric_native_artifacts"]
        ),
        "original_archives_unchanged": len(plan["original_archive_properties"]),
        "scope": plan["scope"],
    }
    save(root / "result.json", result)
    save(
        root / "status.json",
        {
            "status": result["status"],
            "owner": {"pid": os.getpid(), "created": psutil.Process().create_time()},
            "result": ref(root / "result.json"),
            "updated_unix": time.time(),
        },
    )
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("action", choices=["prepare", "apply"])
    parser.add_argument("--root", required=True, type=Path)
    parser.add_argument("--evaluation", type=Path)
    parser.add_argument("--inventory", type=Path)
    parser.add_argument("--active-plan", action="append", type=Path, default=[])
    args = parser.parse_args()
    os.nice(15)
    with writable_path(args.root.parent / "evaluation-snapshot-consolidation.lock").open(
        "a"
    ) as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        if args.action == "prepare":
            result = prepare(args.root, args.evaluation, args.inventory, args.active_plan)
            print(
                json.dumps(
                    {
                        "groups": len(result["groups"]),
                        "replacements": sum(len(g["targets"]) for g in result["groups"]),
                        "expected_reclaimed_GiB": result["expected_reclaimed_allocated_bytes"]
                        / 2**30,
                        "protected": len(result["protected"]),
                        "unchanged_artifacts": len(
                            result["unchanged_report_metric_native_artifacts"]
                        ),
                    }
                )
            )
        else:
            print(json.dumps(apply(args.root)))


if __name__ == "__main__":
    main()

"""Apply unchanged predeclared V88/V89 criteria, retaining every ADC contrast."""

import argparse
from pathlib import Path

import score_context_eligibility as previous
import score_directional_bank_eligibility as shared
from review_spectral_trial import BOUNDARY
from train_directional_bank_trial import guard, read, ref, save


def spectral_keys(value):
    """Rename only positional role keys; numeric values/model labels stay intact."""
    if isinstance(value, dict):
        return {k.replace("context", "spectral"): spectral_keys(v) for k, v in value.items()}
    if isinstance(value, list):
        return [spectral_keys(v) for v in value]
    return value


def evaluate_primary(statistics, control, spectral, parent):
    return spectral_keys(previous.evaluate_primary(statistics, control, spectral, parent))


def evaluate_analytic(summary, rows, control, spectral):
    return spectral_keys(previous.evaluate_analytic(summary, rows, control, spectral))


def adc_detail(rows, models):
    return spectral_keys(
        previous.adc_detail(rows, {"control": models["control"], "context": models["spectral"]})
    )


def main(plan_path, output):
    from compare_long_commons_scores import rows

    from demosaic.safety import writable_path

    plan = read(plan_path)
    guard(plan)
    root = Path(plan["root"])
    boundary = read(root / "training-boundary.json")
    shared.require(
        boundary["status"] == BOUNDARY and boundary["engineering_preflight"] is False,
        "Production spectral training boundary has not been verified",
    )
    control, spectral = boundary["checkpoints"]
    shared.require(
        [c["label"] for c in [control, spectral]] == ["V88-original4000", "V89-original4000"]
        and all(c["step"] == 4000 for c in [control, spectral]),
        "Wrong study/boundary",
    )
    for c in [control, spectral]:
        shared.require(ref(c["path"])["sha256"] == c["sha256"], "Checkpoint changed")
    statistics = read(root / "primary-statistics.json")
    shared.require(
        not statistics.get("preflight_only"), "Historical replay is not production evidence"
    )
    checked = set()
    for source in statistics["sources"]:
        for side in ["first", "second"]:
            for key in ["report", "cases"]:
                path = source[side][key]
                if path not in checked:
                    shared.require(
                        ref(path)["sha256"] == source[side][key + "_sha256"], "Source changed"
                    )
                    checked.add(path)
    analytic = Path(plan["outputs"]["analytic"])
    result = {
        "status": "applied-predeclared-spectral-numerical-criteria-manual-review-pending",
        "plan": ref(plan_path),
        "training_boundary": ref(root / "training-boundary.json"),
        "primary_statistics": ref(root / "primary-statistics.json"),
        "analytic_summary": ref(analytic / "summary.json"),
        "analytic_cases": ref(analytic / "per-case.jsonl"),
        "primary": evaluate_primary(
            statistics, control, spectral, dict(plan["parent"], label="V63-parent")
        ),
        "analytic": evaluate_analytic(
            read(analytic / "summary.json"), rows(analytic / "per-case.jsonl"), control, spectral
        ),
        "manual_native_color_detail_highlight_review": "required; not evaluated by this tool",
        "eligible_for_automatic_extension_or_promotion": False,
    }
    output = writable_path(output)
    shared.require(not output.exists(), "Output exists; preserve prior criteria")
    save(output, result)


if __name__ == "__main__":
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("plan", type=Path)
    p.add_argument("output", type=Path)
    a = p.parse_args()
    main(a.plan, a.output)

"""Read-only Kineto operator attribution; no torch import or model execution."""

import argparse
import hashlib
import json
import math
from collections import Counter, defaultdict
from pathlib import Path

from demosaic.safety import writable_path


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def interval(event):
    start, duration = event.get("ts"), event.get("dur")
    if not all(isinstance(v, (int, float)) and math.isfinite(v) for v in (start, duration)):
        raise ValueError("Nonfinite or missing event timestamp/duration")
    if duration < 0:
        raise ValueError("Negative event duration")
    return start, start + duration


def contains(outer, inner):
    return (
        (outer.get("pid"), outer.get("tid")) == (inner.get("pid"), inner.get("tid"))
        and interval(outer)[0] <= interval(inner)[0]
        and interval(inner)[1] <= interval(outer)[1]
    )


def summarize_events(events, *, range_prefix=None):
    cpu = [
        e for e in events if e.get("ph") == "X" and e.get("cat") in ["cpu_op", "user_annotation"]
    ]
    ids = {}
    for event in cpu:
        external = event.get("args", {}).get("External id")
        if external is not None:
            if external in ids:
                raise ValueError("Ambiguous CPU external id")
            ids[external] = event
    ranges = [
        e
        for e in cpu
        if e["cat"] == "user_annotation"
        and (range_prefix is None or e["name"].startswith(range_prefix))
    ]
    for event in cpu:
        interval(event)

    def enclosing(event):
        if event is None:
            return []
        # Contain the whole CPU launch operator, on its own process/thread.
        return sorted(
            [r for r in ranges if contains(r, event)],
            key=lambda r: r["dur"],
        )

    gpu = [
        e
        for e in events
        if e.get("ph") == "X" and e.get("cat") in ["kernel", "gpu_memcpy", "gpu_memset"]
    ]
    runtime = defaultdict(list)
    for event in events:
        if (
            event.get("ph") == "X"
            and event.get("cat") in ["cuda_runtime", "cuda_driver"]
            and "correlation" in event.get("args", {})
        ):
            interval(event)
            runtime[event["args"]["correlation"]].append(event)
    exclusive = defaultdict(list)
    inclusive = defaultdict(list)
    operators = defaultdict(list)
    cross = Counter()
    unknown = []
    for event in gpu:
        interval(event)
        args = event.get("args", {})
        op = ids.get(args.get("External id"))
        containing = enclosing(op)
        branch = containing[0]["name"] if containing else "<outside named ranges>"
        exclusive[branch].append(event["dur"])
        for name in {r["name"] for r in containing}:
            inclusive[name].append(event["dur"])
        operators[(branch, op["name"] if op is not None else "<unmapped CPU operator>")].append(
            event["dur"]
        )
        launches = runtime.get(args.get("correlation"), [])
        if len(launches) == 1:
            external = launches[0]["args"].get("External id")
            if external is not None and op is not None and external == args.get("External id"):
                cross["GPU_external_id_independently_matches_unique_runtime_correlation"] += 1
                if contains(op, launches[0]):
                    cross["runtime_launch_inside_matched_CPU_operator_on_same_thread"] += 1
                else:
                    cross["runtime_launch_outside_matched_CPU_operator_or_thread"] += 1
            else:
                cross["runtime_external_id_mismatch_or_unmapped"] += 1
        else:
            cross["runtime_correlation_missing_or_ambiguous"] += 1
        if op is None:
            unknown.append(
                {
                    "name": event["name"],
                    "external_id": args.get("External id"),
                    "correlation": args.get("correlation"),
                    "duration_us": event["dur"],
                }
            )

    def totals(groups):
        return sorted(
            [
                {
                    "name": name,
                    "events": len(values),
                    "summed_GPU_activity_ms": math.fsum(values) / 1000,
                }
                for name, values in groups.items()
            ],
            key=lambda x: -x["summed_GPU_activity_ms"],
        )

    all_gpu = math.fsum(e["dur"] for e in gpu)
    assert math.isclose(
        math.fsum(math.fsum(v) for v in exclusive.values()), all_gpu, rel_tol=0, abs_tol=1e-8
    )
    operators = [
        {
            "exclusive_branch": branch,
            "CPU_operator": op,
            "events": len(v),
            "summed_GPU_activity_ms": math.fsum(v) / 1000,
        }
        for (branch, op), v in operators.items()
    ]
    operators.sort(key=lambda x: -x["summed_GPU_activity_ms"])
    cpu_counts = defaultdict(Counter)
    for op in cpu:
        if op["cat"] != "cpu_op":
            continue
        containing = enclosing(op)
        branch = containing[0]["name"] if containing else "<outside named ranges>"
        cpu_counts[branch][op["name"]] += 1
    return {
        "CPU_operator_events": sum(e["cat"] == "cpu_op" for e in cpu),
        "GPU_activity_events": len(gpu),
        "GPU_categories": dict(Counter(e["cat"] for e in gpu)),
        "CPU_named_range_calls": dict(Counter(e["name"] for e in ranges)),
        "all_GPU_activity_ms_sum": all_gpu / 1000,
        "GPU_mapping_cross_checks": dict(cross),
        "contains_positive_duration_GPU_activity": any(e["dur"] > 0 for e in gpu),
        "all_GPU_mappings_verified": bool(gpu)
        and not unknown
        and cross["GPU_external_id_independently_matches_unique_runtime_correlation"]
        == cross["runtime_launch_inside_matched_CPU_operator_on_same_thread"]
        == len(gpu),
        "range_prefix": range_prefix,
        "unmapped_GPU_events": unknown,
        "exclusive_GPU_ranges": totals(exclusive),
        "inclusive_GPU_ranges_do_not_sum_nested_ranges": totals(inclusive),
        "GPU_operator_attribution": operators,
        "CPU_operator_counts_by_exclusive_range": {
            name: dict(counts) for name, counts in cpu_counts.items()
        },
        "scope": "Saved instrumented trace only; CPU operator joined by External id, runtime cross-check joined separately by correlation and checked inside that CPU operator on its own thread. Innermost enclosing CPU annotation assigns each GPU activity exactly once to exclusive totals; inclusive nested ranges overlap. Kernel/memcpy/memset durations are summed, not critical-path wall time or full-frame speed. CPU operator counts are not GPU timing. No model execution or state/output/precision change.",
    }


def summarize(path, *, range_prefix=None):
    path = Path(path)
    before = sha(path)
    trace = json.loads(path.read_text())
    result = summarize_events(trace["traceEvents"], range_prefix=range_prefix)
    assert sha(path) == before, "Input trace changed while being read"
    return {"trace": str(path), "trace_sha256": before, **result}


def require_cuda_mapping(result):
    if not result["contains_positive_duration_GPU_activity"]:
        raise ValueError(
            "Trace has no positive-duration GPU activities; CPU trace is not GPU evidence"
        )
    if not result["all_GPU_mappings_verified"]:
        raise ValueError(
            "GPU activities have unmapped/mismatched/ambiguous CPU or runtime associations"
        )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("trace", type=Path)
    parser.add_argument("output", type=Path)
    parser.add_argument("--range-prefix")
    parser.add_argument("--require-cuda", action="store_true")
    args = parser.parse_args()
    trace, output = args.trace, writable_path(args.output)
    if output.exists():
        raise ValueError("Choose a new output")
    result = summarize(trace, range_prefix=args.range_prefix)
    if args.require_cuda:
        require_cuda_mapping(result)
    result["driver_sha256"] = sha(__file__)
    result["require_CUDA_mapping"] = args.require_cuda
    output.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    print(
        json.dumps(
            {
                k: result[k]
                for k in [
                    "trace",
                    "GPU_activity_events",
                    "GPU_mapping_cross_checks",
                    "exclusive_GPU_ranges",
                ]
            }
        )
    )

"""Build native160px review boards from saved crop PNGs; no inference or resizing."""

import argparse
import hashlib
import io
import json
from pathlib import Path

import numpy as np
from PIL import Image, ImageDraw

KINDS = {
    "synthetic": ("GT (synthetic)", ("source_id", "evaluation_tile_xywh", "condition", "source")),
    "analytic": ("GT (analytic)", ("source_id", "evaluation_tile_xywh", "condition", "source")),
    "camera": ("AHD reference", ("scene", "prepared_crop", "conditioning", "evaluation_tile_xywh")),
    "gfx": ("ISO100 ref (not GT)", ("region", "context_xywh", "full_frame", "conditioning")),
    "gfx-window": ("ISO100 ref (not GT)", ("region", "conditioning", "source")),
    "three-camera": (
        "RawNIND (not GT)",
        ("source_sha256", "region", "sensor_roi_xywh", "context_roi_xywh", "conditioning"),
    ),
    "hue": ("GT (analytic)", ("case", "ROI_xywh", "conditioning")),
    "highlights": ("ISO100 AHD / not GT", ("region", "ROI_xywh", "source", "conditioning")),
}
MODEL_FIELDS = {
    "image",
    "caption",
    "png_sha256",
    "panels",
    "model",
    "model_label",
    "checkpoint_sha256",
    "compute_precision",
    "device",
    "runtime",
    "model_index",
    "case_index",
}


def digest(data):
    return hashlib.sha256(data).hexdigest()


def reference(path, data=None):
    path = Path(path).resolve()
    return {"path": str(path), "sha256": digest(path.read_bytes() if data is None else data)}


def identity(crop):
    model = crop.get("model", {})
    label = crop.get("model_label", model.get("label"))
    hashes = [
        value
        for value in (
            crop.get("checkpoint_sha256"),
            model.get("sha256"),
            model.get("weight_sha256"),
        )
        if value is not None
    ]
    sha = hashes[0] if hashes else None
    if not isinstance(label, str) or not label:
        raise ValueError("Missing model label")
    if model.get("label", label) != label or any(value != sha for value in hashes):
        raise ValueError("Conflicting model label or checkpoint hash")
    if not isinstance(sha, str) or len(sha) != 64 or any(c not in "0123456789abcdef" for c in sha):
        raise ValueError("Missing recorded checkpoint SHA256")
    return label, sha


def case_key(crop, kind):
    if kind in ("synthetic", "analytic"):
        value = crop["source_id"]
    elif kind == "camera":
        value = [crop["scene"], crop["prepared_crop"]["id"]]
    elif kind == "three-camera":
        value = [crop["source_sha256"], crop["region"]]
    elif kind == "hue":
        value = crop["case"]["id"]
    else:
        value = crop["region"]["name"]
    return json.dumps(value, sort_keys=True)


def read_crop(report, crop, kind):
    expected_label, required = KINDS[kind]
    for key in (*required, "display_exposure", "reference", "pixel_scale", "display_encoding"):
        if key not in crop:
            raise ValueError(f"Missing shared crop metadata: {key}")
    if (
        len(crop["panels"]) != 3
        or crop["panels"][0]["label"] != "Noisy (Malvar)"
        or crop["panels"][2]["label"] != expected_label
    ):
        raise ValueError("Reference label does not match the explicitly selected report kind")
    path = (report.parent / crop["image"]).resolve()
    if not path.is_relative_to(report.parent.resolve()):
        raise ValueError("Crop PNG is outside its report directory")
    data = path.read_bytes()
    if digest(data) != crop["png_sha256"]:
        raise ValueError("Crop PNG hash mismatch")
    with Image.open(io.BytesIO(data)) as image:
        if image.mode != "RGB":
            raise ValueError("Expected RGB8 display PNG")
        pixels = np.asarray(image).copy()
    parts, rects = [], []
    for panel in crop["panels"]:
        rect = panel["png_xywh"]
        if len(rect) != 4 or any(type(v) is not int for v in rect):
            raise ValueError("Panel coordinates must be integer xywh")
        x, y, w, h = rect
        if (
            (w, h) != (160, 160)
            or x < 0
            or y < 0
            or x + w > pixels.shape[1]
            or y + h > pixels.shape[0]
        ):
            raise ValueError("Panel must be an in-bounds native160px square")
        if any(x < a + c and a < x + w and y < b + d and b < y + h for a, b, c, d in rects):
            raise ValueError("Panel rectangles overlap")
        rects.append(rect)
        parts.append(pixels[y : y + h, x : x + w])
    settings = {k: v for k, v in crop.items() if k not in MODEL_FIELDS}
    return parts, settings, reference(path, data)


def build(reports, output, kind, labels=None):
    """Require a complete method-by-case rectangle and retain every input crop receipt."""
    output = Path(output)
    receipt_path = output.with_suffix(".json")
    if output.suffix != ".png" or output.exists() or receipt_path.exists():
        raise ValueError("Choose a new PNG and receipt path")
    cases, models, hashes, inputs, sources = {}, [], {}, [], []
    for index, report in enumerate(map(Path, reports)):
        report_data = report.read_bytes()
        inputs.append(reference(report, report_data))
        crops = json.loads(report_data)["native_crops"]
        if not crops:
            raise ValueError("Report has no saved native crops")
        for crop in crops:
            model, sha = identity(crop)
            if model not in models:
                models.append(model)
            if hashes.setdefault(model, sha) != sha:
                raise ValueError("One model label names different checkpoints")
            key = (index, case_key(crop, kind))
            case = cases.setdefault(key, {})
            if model in case:
                raise ValueError("Duplicate model/case crop")
            parts, settings, png = read_crop(report, crop, kind)
            case[model] = (parts, settings, png, crop)
            sources.append({"report_index": index, "image": png, "crop": crop})
    if labels is not None and (
        set(labels) != set(models) or len(set(labels.values())) != len(models)
    ):
        raise ValueError("Display labels must uniquely map every recorded method")
    names = [labels[m] if labels is not None else m for m in models]
    last = "AHD reference (not exact GT)" if kind == "camera" else KINDS[kind][0]
    row_names = ["Noisy (Malvar)", *names, last]
    ruler = ImageDraw.Draw(Image.new("RGB", (1, 1)))
    left = max(180, max(ruler.textbbox((0, 0), n)[2] for n in row_names) + 16)
    image = Image.new("RGB", (left + 168 * len(cases), 48 + 184 * len(row_names)), "white")
    draw = ImageDraw.Draw(image)
    cells = []
    for col, (key, case) in enumerate(cases.items()):
        if set(case) != set(models):
            raise ValueError("Incomplete method-by-case rectangle")
        first_parts, first_settings, _, _ = case[models[0]]
        for parts, settings, _, _ in case.values():
            if settings != first_settings:
                raise ValueError(
                    "Source/ROI/noise/display/reference metadata differs across methods"
                )
            if not np.array_equal(parts[0], first_parts[0]) or not np.array_equal(
                parts[2], first_parts[2]
            ):
                raise ValueError("Noisy/reference pixels differ across methods")
        draw.text((left + 168 * col, 4), f"Report {key[0] + 1}", fill="black")
        draw.text((left + 168 * col, 20), key[1].strip('"')[:24], fill="black")
        rows = [(models[0], 0), *((m, 1) for m in models), (models[0], 2)]
        for row, (model, part) in enumerate(rows):
            parts, _, png, crop = case[model]
            x, y = left + 168 * col, 72 + 184 * row
            draw.text((4, 56 + 184 * row), row_names[row], fill="black")
            image.paste(Image.fromarray(parts[part]), (x, y))
            cells.append(
                {
                    "case": list(key),
                    "row_label": row_names[row],
                    "model_label": model,
                    "part": part,
                    "image": png,
                    "source_xywh": crop["panels"][part]["png_xywh"],
                    "board_xywh": [x, y, 160, 160],
                    "pixel_sha256": digest(parts[part].tobytes()),
                }
            )
    # Validate every input before creating either output; never overwrite existing artifacts.
    for item in inputs:
        if reference(item["path"]) != item:
            raise ValueError("Report changed during board construction")
    output.parent.mkdir(parents=True, exist_ok=True)
    with output.open("xb") as stream:
        image.save(stream, format="PNG")
    with Image.open(output) as saved:
        readback = np.asarray(saved)
    for cell in cells:
        x, y, w, h = cell["board_xywh"]
        if digest(readback[y : y + h, x : x + w].tobytes()) != cell["pixel_sha256"]:
            raise ValueError("Saved board pixel mismatch")
    result = {
        "status": "saved-native-board-awaiting-manual-review",
        "kind": kind,
        "driver": reference(__file__),
        "reports": inputs,
        "board": reference(output),
        "models": [
            {"label": m, "display_label": n, "sha256": hashes[m]}
            for m, n in zip(models, names, strict=True)
        ],
        "native_cells_exact": len(cells),
        "source_triplets": sources,
        "cells": cells,
        "scope": "Saved RGB8 preview PNG rearrangement only. Every cell is an unchanged native160px square; shared metadata and noisy/reference pixels match across methods. Recorded checkpoint hashes are retained, not rehashed here. No inference, new score, quality finding, training or promotion. Manual review remains required.",
    }
    with receipt_path.open("x") as stream:
        json.dump(result, stream, indent=2, allow_nan=False)
        stream.write("\n")
    return result


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("reports", type=Path, nargs="+")
    parser.add_argument("--kind", choices=KINDS, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument(
        "--labels", type=Path, help="Optional complete original-label to display-label JSON map"
    )
    args = parser.parse_args()
    labels = json.loads(args.labels.read_text()) if args.labels else None
    result = build(args.reports, args.output, args.kind, labels)
    print(
        json.dumps({"board": result["board"], "native_cells_exact": result["native_cells_exact"]})
    )


if __name__ == "__main__":
    main()

"""Paired-policy quality data flow; one model and one observation per comparison."""

import copy
import json
import random
from pathlib import Path

import numpy as np
import torch
from mature_precision_tools import precision_policy
from profile_raw_kernel_inference import model_hash
from train_directional_bank_trial import read, ref

from demosaic.cfa import color_indices, malvar, pack
from demosaic.data import CleanDataset, synthetic
from demosaic.metrics import quality_metrics
from demosaic.real_suite import measured_sensor_psnr
from demosaic.reporting import display_crop, save_triplet
from demosaic.suite import observation
from demosaic.train import batch_fingerprint

KEYS = ("packed", "variance", "colors", "wb", "matrix")
POLICIES = ("fp32", "fp16-hidden")


def numbers(values, index):
    return {k: float(v[index]) if torch.isfinite(v[index]) else None for k, v in values.items()}


def save_new(path, value):
    with Path(path).open("x") as stream:
        json.dump(value, stream, indent=2, allow_nan=False)
        stream.write("\n")


def photo_dataset(options):
    selected = set(options["source_ids"])
    records = [
        json.loads(line) for line in Path(options["manifest"]["path"]).read_text().splitlines()
    ]
    records = [r for r in records if r["id"] in selected]
    return CleanDataset(
        options["manifest"]["path"],
        split="val",
        patch_size=options["size"],
        native_crop=True,
        records=records,
    )


def load_arrays(item):
    if ref(item["path"]) != item:
        raise ValueError("Observation input checksum differs")
    with np.load(item["path"], allow_pickle=False) as data:
        return {k: torch.from_numpy(data[k].copy()) for k in data.files}


def physical_rows(first, second):
    delta = second.double() - first.double()
    return [
        {
            "RGB_values": x.numel(),
            "max_abs_DN16": float(x.abs().max()) * 65535,
            "RMS_DN16": float(x.square().mean().sqrt()) * 65535,
        }
        for x in delta
    ]


def case_gates(kind, baseline, candidate):
    """Prospective per-case limits; retain every failure without early stopping."""
    if kind in ("photo", "synthetic", "camera"):
        limits = {"srgb_psnr": 0.05, "srgb_ssim": 0.0001}
        if kind in ("photo", "synthetic"):
            limits["linear_psnr"] = 0.05
        else:
            limits = {"sensor_psnr": 0.05, "ahd_srgb_psnr": 0.05, "ahd_srgb_ssim": 0.0001}
        if any(baseline[k] is None or candidate[k] is None for k in limits):
            raise ValueError("Missing noninferiority metric")
        return {k: candidate[k] >= baseline[k] - limit for k, limit in limits.items()}
    if kind == "carrier":
        return {"signed_gain": candidate["in_phase_gain"] >= baseline["in_phase_gain"] - 0.05}
    if kind == "flat":
        return {
            "spatial_luma_RMS": candidate["spatial_luma_rms"] <= 1.25 * baseline["spatial_luma_rms"]
        }
    if kind == "hue":
        return {
            "channel_mean_error_increase_at_most_one_DN16": max(
                map(abs, candidate["camera_RGB_mean_error"])
            )
            <= max(map(abs, baseline["camera_RGB_mean_error"])) + 1 / 65535,
            "centered_camera_RMS_at_most_1.25x": candidate["spatially_centered_camera_RGB_RMS"]
            <= 1.25 * baseline["spatially_centered_camera_RGB_RMS"],
        }
    raise ValueError("Unknown paired quality gate kind")


class PairRunner:
    def __init__(self, model, label, checkpoint, device, *, engineering=False):
        self.model, self.label, self.checkpoint = model, label, checkpoint
        self.device, self.engineering = torch.device(device), engineering
        self.before = model_hash(model)
        self.dino = model_hash(model.context.backbone)
        self.config = copy.deepcopy(model.config.to_dict())
        self.identities = [id(p) for p in model.parameters()]
        self.rng = (
            torch.get_rng_state().clone(),
            random.getstate(),
            [r.clone() for r in torch.cuda.get_rng_state_all()]
            if self.device.type == "cuda"
            else [],
        )
        self.forwards, self.observations, self.encoder_calls = 0, 0, 0
        self.boundary_calls, self.expected_args = 0, None
        self.hook = model.context.backbone.register_forward_hook(self.encoder_called)
        self.boundary_hook = model.register_forward_pre_hook(self.forward_boundary)

    def forward_boundary(self, _module, args):
        if len(args) != 5 or any(a is not b for a, b in zip(args, self.expected_args, strict=True)):
            raise ValueError("Predictor boundary differs from the five physical arguments")
        self.boundary_calls += 1

    def encoder_called(self, *_):
        self.encoder_calls += 1

    @torch.inference_mode()
    def __call__(self, host, condition):
        # Only these five physical fields reach the predictor. Targets/masks stay outside.
        source_digest = batch_fingerprint(host)
        actual = {k: host[k].to(self.device) for k in KEYS}
        for k in ("packed", "variance"):
            if self.device.type == "cuda":
                actual[k] = actual[k].contiguous(memory_format=torch.channels_last)
        digest = batch_fingerprint(actual)
        self.expected_args = tuple(actual[k] for k in KEYS)
        self.model.set_noise(condition["shot"], condition["read"])
        result = {}
        order = POLICIES if self.forwards % 4 == 0 else tuple(reversed(POLICIES))
        for policy in order:
            with precision_policy(self.model, policy, self.device, cpu_probe=self.engineering):
                value = self.model(*(actual[k] for k in KEYS))
            if value.dtype != torch.float32 or not torch.isfinite(value).all():
                raise ValueError("Expected finite physical FP32 output")
            expected = (
                len(actual["packed"]),
                3,
                actual["packed"].shape[-2] * 2,
                actual["packed"].shape[-1] * 2,
            )
            if tuple(value.shape) != expected:
                raise ValueError("Native output shape differs")
            result[policy] = value.cpu()
            self.forwards += 1
            self.observations += len(value)
        if (
            batch_fingerprint(actual) != digest
            or batch_fingerprint(host) != source_digest
            or self.model.config.to_dict() != self.config
        ):
            raise ValueError("Policy forward changed observation or original config")
        if self.model.pretrained_rgb.network.hidden_autocast:
            raise ValueError("Hidden flag was not restored")
        return result, digest

    def metadata(self, policy):
        return {
            "label": self.label + ":" + policy,
            "sha256": self.checkpoint["sha256"],
            "checkpoint": self.checkpoint,
            "policy": policy,
            "compute_precision": "IEEE FP32"
            if policy == "fp32"
            else "FP16 neural, hidden branch FP16; physical FP32",
            "original_model_config": self.config,
        }

    def finish(self):
        self.hook.remove()
        self.boundary_hook.remove()
        self.expected_args = None
        if (
            model_hash(self.model) != self.before
            or model_hash(self.model.context.backbone) != self.dino
        ):
            raise ValueError("Learned tensor state changed")
        if (
            self.model.config.to_dict() != self.config
            or [id(p) for p in self.model.parameters()] != self.identities
        ):
            raise ValueError("Model config/parameter identities changed")
        if not torch.equal(torch.get_rng_state(), self.rng[0]) or random.getstate() != self.rng[1]:
            raise ValueError("CPU/Python RNG changed")
        if self.device.type == "cuda" and any(
            not torch.equal(a, b)
            for a, b in zip(self.rng[2], torch.cuda.get_rng_state_all(), strict=True)
        ):
            raise ValueError("CUDA RNG changed")
        if self.encoder_calls != self.forwards or self.boundary_calls != self.forwards:
            raise ValueError("Expected one actual frozen encoder call per forward")
        return {
            "model": self.label,
            "checkpoint": self.checkpoint,
            "model_sha256": self.before,
            "DINO_sha256": self.dino,
            "actual_forwards": self.forwards,
            "policy_observations": self.observations,
            "encoder_calls": self.encoder_calls,
            "five_physical_argument_boundaries": self.boundary_calls,
            "original_state_config_parameters_RNG_exact": True,
        }


def native_pair(
    runner,
    output,
    key,
    predictions,
    host,
    metadata,
    *,
    roi,
    reference="GT (synthetic)",
    reference_rgb=None,
    exposure=1,
    model_metadata=None,
):
    cpu = {k: v.cpu() for k, v in host.items()}
    noisy = malvar(cpu["packed"], cpu["colors"], cpu["wb"])
    target = cpu["target"] if reference_rgb is None else reference_rgb.cpu()
    noisy_view = display_crop(noisy, cpu["wb"], cpu["matrix"], roi, exposure=exposure)
    target_roi = [0, 0, 160, 160] if target.shape[-2:] == (160, 160) else roi
    target_view = display_crop(target, cpu["wb"], cpu["matrix"], target_roi, exposure=exposure)
    crops = []
    for policy in POLICIES:
        model = {**runner.metadata(policy), **(model_metadata or {})}
        crops.append(
            save_triplet(
                output,
                key + ":" + model["label"],
                [
                    ("Noisy (Malvar)", noisy_view),
                    (
                        "Denoised",
                        display_crop(
                            predictions[policy], cpu["wb"], cpu["matrix"], roi, exposure=exposure
                        ),
                    ),
                    (reference, target_view),
                ],
                caption=key + " / " + model["label"],
                metadata={
                    **metadata,
                    "model": model,
                    "model_label": model["label"],
                    "checkpoint_sha256": runner.checkpoint["sha256"],
                    "display_exposure": exposure,
                },
            )
        )
    return crops


def photo_panel(runner, plan, output):
    output = Path(output)
    output.mkdir(parents=True, exist_ok=False)
    opts = plan["photo"]
    data = photo_dataset(opts)
    entries = [("photo", data.rows[i]["id"], i) for i in range(opts["images"])]
    if [x[1] for x in entries] != opts["source_ids"][: opts["images"]]:
        raise ValueError("Frozen photo membership/order differs")
    entries += [("synthetic", f"synthetic-{i}", i) for i in range(opts["synthetic"])]
    rows, crops, observations = [], [], []
    selected = {x[1] for x in entries[:2]}
    for start in range(0, len(entries), opts["batch"]):
        batch = entries[start : start + opts["batch"]]
        rgb = torch.stack(
            [
                data[i]["rgb"]
                if kind == "photo"
                else synthetic(opts["size"], random.Random(1_000_000 + i))
                for kind, _, i in batch
            ]
        ).to(runner.device)
        for condition in opts["conditions"]:
            for pattern in opts["patterns"]:
                host = observation(
                    rgb,
                    [x[1] for x in batch],
                    condition,
                    pattern,
                    opts["wb"],
                    opts["matrix"],
                    opts["seed"],
                )
                pred, digest = runner(host, condition)
                trim = (
                    ...,
                    slice(opts["border"], -opts["border"]),
                    slice(opts["border"], -opts["border"]),
                )
                truth, wb, matrix = (host[k].cpu() for k in ("target", "wb", "matrix"))
                scores = {
                    p: quality_metrics(
                        pred[p][trim],
                        truth[trim],
                        wb,
                        matrix,
                    )
                    for p in POLICIES
                }
                differences = physical_rows(pred["fp32"], pred["fp16-hidden"])
                for j, (kind, identity, source_index) in enumerate(batch):
                    values = {p: numbers(scores[p], j) for p in POLICIES}
                    rows.append(
                        {
                            "kind": kind,
                            "id": identity,
                            "condition": condition["name"],
                            "pattern": pattern,
                            "metrics": values,
                            "physical": differences[j],
                            "input_sha256": digest,
                        }
                    )
                    if (
                        not runner.engineering
                        and identity in selected
                        and condition["name"] == "iso12800-prior"
                        and pattern == "RGGB"
                    ):
                        sliced = {k: v[j : j + 1] for k, v in host.items()}
                        arrays_path = output / (identity[:12] + "-observation.npz")
                        np.savez(arrays_path, **{k: v.cpu().numpy() for k, v in sliced.items()})
                        observations.append(ref(arrays_path))
                        metadata = {
                            "source_id": identity,
                            "source": data.rows[source_index],
                            "validation_index": source_index,
                            "validation_seed": data.seed,
                            "evaluation_tile_xywh": [48, 48, 160, 160],
                            "condition": condition,
                            "pattern": pattern,
                            "white_balance": opts["wb"],
                            "camera_to_srgb": opts["matrix"],
                            "reference": "Exact synthetic clean target",
                            "measurement_and_target_sha256": batch_fingerprint(sliced),
                        }
                        crops += native_pair(
                            runner,
                            output,
                            identity,
                            {p: v[j : j + 1] for p, v in pred.items()},
                            sliced,
                            metadata,
                            roi=[48, 48, 160, 160],
                            model_metadata={"observation": ref(arrays_path)},
                        )
        print(
            json.dumps(
                {
                    "stage": "photo",
                    "model": runner.label,
                    "sources_done": min(start + opts["batch"], len(entries)),
                }
            ),
            flush=True,
        )
    expected = len(entries) * len(opts["conditions"]) * len(opts["patterns"])
    if len(rows) != expected:
        raise ValueError("Photo coverage differs")
    with (output / "per-case.jsonl").open("x") as stream:
        for row in rows:
            stream.write(json.dumps(row, allow_nan=False) + "\n")
    save_new(
        output / "report.json",
        {
            "status": "completed-paired-photo-policy-inference-awaiting-native-and-scalar-review",
            "physical_observations": len(rows),
            "native_crops": crops,
            "saved_observations": observations,
            "model": runner.label,
            "checkpoint": runner.checkpoint,
            "settings": opts,
            "engineering_only": runner.engineering,
        },
    )


def camera_panel(runner, manifest, output):
    output = Path(output)
    output.mkdir(parents=True, exist_ok=False)
    data = read(manifest["path"])
    prepared = Path(manifest["path"])
    high = {}
    for case in data["cases"]:
        if case["scene"] not in high or (case["metadata"].get("iso") or 0) > (
            high[case["scene"]]["metadata"].get("iso") or 0
        ):
            high[case["scene"]] = case
    chosen = set(sorted(high)[:2])
    rows, crops = [], []
    for case in data["cases"]:
        meta, condition = case["metadata"], case["conditioning"]
        for start in range(0, len(case["crops"]), 4):
            current = case["crops"][start : start + 4]
            batches = [
                load_arrays(
                    {"path": str((prepared.parent / c["path"]).resolve()), "sha256": c["sha256"]}
                )
                for c in current
            ]
            tensors = {
                k: torch.stack([b[k] for b in batches])
                for k in ("raw", "reference_rgb", "sensor_reference", "sensor_mask")
            }
            packed = pack(tensors["raw"][:, None])
            host = {
                "packed": packed,
                "variance": packed.clamp_min(0) * condition["shot"] + condition["read"],
                "colors": color_indices(meta["pattern"])[None].expand(len(current), -1),
                "wb": torch.tensor(meta["white_balance"], dtype=torch.float32)[None].expand(
                    len(current), -1
                ),
                "matrix": torch.tensor(meta["camera_to_srgb"], dtype=torch.float32)[None].expand(
                    len(current), -1, -1
                ),
                "target": tensors["reference_rgb"],
                "sensor_reference": tensors["sensor_reference"],
                "sensor_mask": tensors["sensor_mask"],
            }
            pred, digest = runner(host, condition)
            scores = {}
            region = (..., slice(32, -32), slice(32, -32))
            for policy in POLICIES:
                score, n = measured_sensor_psnr(
                    pred[policy][region],
                    tensors["sensor_reference"][region],
                    tensors["sensor_mask"][region],
                )
                auxiliary = quality_metrics(
                    pred[policy][region],
                    tensors["reference_rgb"][region],
                    host["wb"],
                    host["matrix"],
                )
                scores[policy] = {
                    "sensor_psnr": score,
                    "reference_samples": n,
                    **{"ahd_" + k: v for k, v in auxiliary.items() if k.startswith("srgb_")},
                }
            differences = physical_rows(pred["fp32"], pred["fp16-hidden"])
            for j, crop in enumerate(current):
                rows.append(
                    {
                        "scene": case["scene"],
                        "pair": case["noisy"]["sha256"],
                        "tile_id": crop["id"],
                        "kind": "camera",
                        "pattern": meta["pattern"],
                        "metrics": {p: numbers(v, j) for p, v in scores.items()},
                        "physical": differences[j],
                        "input_sha256": digest,
                    }
                )
                if (
                    case["scene"] in chosen
                    and case is high[case["scene"]]
                    and start + j == len(case["crops"]) // 2
                ):
                    sliced = {k: v[j : j + 1] for k, v in host.items()}
                    metadata = {
                        "scene": case["scene"],
                        "conditioning": condition,
                        "white_balance": meta["white_balance"],
                        "camera_to_srgb": meta["camera_to_srgb"],
                        "noisy_sha256": case["noisy"]["sha256"],
                        "prepared_crop": crop,
                        "evaluation_tile_xywh": [176, 176, 160, 160],
                        "variance_multiplier": 1,
                        "reference": "Registered low-noise RAW, auxiliary LibRaw AHD RGB; primary scores use measured CFA",
                    }
                    crops += native_pair(
                        runner,
                        output,
                        crop["id"],
                        {p: v[j : j + 1] for p, v in pred.items()},
                        sliced,
                        metadata,
                        roi=[176, 176, 160, 160],
                        reference="AHD reference",
                    )
        print(
            json.dumps({"stage": "camera", "model": runner.label, "scene": case["scene"]}),
            flush=True,
        )
    if len(rows) != sum(len(c["crops"]) for c in data["cases"]):
        raise ValueError("Camera coverage differs")
    save_new(
        output / "report.json",
        {
            "status": "completed-paired-camera-policy-inference-awaiting-native-and-scalar-review",
            "rows": rows,
            "native_crops": crops,
            "manifest": manifest,
            "checkpoint": runner.checkpoint,
            "reference": "AHD is not exact GT; primary scores use measured CFA",
        },
    )

"""Attribute actual sampler calls to sensor transport or source construction."""

from contextlib import contextmanager
from unittest.mock import patch

import torch


@contextmanager
def count_source_draws():
    """Observe unchanged calls at the two sensor API boundaries.

    Procedural bandlimited textures also draw Gaussian values. Those draws
    remain separate from Poisson/read sensor noise. This is CPU data-builder
    instrumentation; use in a single data-construction thread.
    """
    import paired_response_data as paired

    from demosaic import suite

    counts = {
        "sensor_Poisson": 0,
        "sensor_Gaussian": 0,
        "procedural_Poisson": 0,
        "procedural_Gaussian": 0,
        "coupled_sensor_calls": 0,
        "ordinary_sensor_calls": 0,
    }
    depth = 0
    poisson, randn = torch.poisson, torch.randn
    coupled, ordinary = paired.coupled_sensor_noise, suite.add_noise

    def poisson_call(*args, **kwargs):
        counts[("sensor" if depth else "procedural") + "_Poisson"] += 1
        return poisson(*args, **kwargs)

    def gaussian_call(*args, **kwargs):
        counts[("sensor" if depth else "procedural") + "_Gaussian"] += 1
        return randn(*args, **kwargs)

    def sensor_call(fn, label, *args, **kwargs):
        nonlocal depth
        counts[label] += 1
        depth += 1
        try:
            return fn(*args, **kwargs)
        finally:
            depth -= 1

    def coupled_call(*args, **kwargs):
        return sensor_call(coupled, "coupled_sensor_calls", *args, **kwargs)

    def ordinary_call(*args, **kwargs):
        return sensor_call(ordinary, "ordinary_sensor_calls", *args, **kwargs)

    with (
        patch.object(torch, "poisson", poisson_call),
        patch.object(torch, "randn", gaussian_call),
        patch.object(paired, "coupled_sensor_noise", coupled_call),
        patch.object(suite, "add_noise", ordinary_call),
    ):
        yield counts

"""Exact FP32 native arrays with checked dependencies and lossless byte planes.

New outputs only: a checked baseline-plus-wave recipe avoids storing redundant
RGB bits when NumPy FP32 addition reproduces every original bit. Otherwise use
byte-plane zlib, optionally after XOR with an immutable baseline. No quantizing.
"""

import hashlib
import json
import os
import zlib
from pathlib import Path

import numpy as np


def ref(path):
    path = Path(path).absolute()
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"path": str(path), "sha256": digest}


def fingerprint(array):
    array = np.ascontiguousarray(array)
    return {
        "shape": list(array.shape),
        "dtype": array.dtype.str,
        "sha256": hashlib.sha256(array.tobytes()).hexdigest(),
    }


def checked(binding):
    if ref(binding["path"]) != binding:
        raise ValueError("Native dependency file digest mismatch")
    return Path(binding["path"])


def publish_exclusive(path, data):
    path = Path(path)
    temporary = path.with_name("." + path.name + ".writing")
    with temporary.open("xb") as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())
    os.link(temporary, path)  # Atomic publication; never replace existing output.
    temporary.unlink()


def load_native(binding):
    path = checked(binding) if isinstance(binding, dict) else Path(binding)
    if path.suffix == ".npy":
        return np.load(path, allow_pickle=False)
    metadata = json.loads(path.read_text())
    if metadata["format"] != "exact-native-f32-v1":
        raise ValueError("Unknown native format")
    expected = metadata["values"]
    shape = tuple(expected["shape"])
    if expected["dtype"] != "<f4" or any(type(n) is not int or n < 1 for n in shape):
        raise ValueError("Expected little-endian FP32 native array")
    if metadata["encoding"] == "checked-f32-add":
        baseline = load_native(metadata["baseline"])
        wave = load_native(metadata["wave"])
        if baseline.shape != shape or wave.shape != shape:
            raise ValueError("Addition operand shape mismatch")
        value = np.add(baseline, wave, dtype=np.float32)
    elif metadata["encoding"] in ["byteplanes-zlib", "xor-byteplanes-zlib"]:
        compressed = checked(metadata["payload"]).read_bytes()
        raw = zlib.decompress(compressed)
        count = int(np.prod(shape))
        if len(raw) != count * 4:
            raise ValueError("Native payload length mismatch")
        bits = np.frombuffer(raw, dtype=np.uint8).reshape(4, count).T.copy()
        bits = bits.reshape(-1).view("<u4").reshape(shape)
        if metadata["encoding"] == "xor-byteplanes-zlib":
            baseline = load_native(metadata["baseline"])
            if baseline.shape != shape or baseline.dtype != np.dtype("<f4"):
                raise ValueError("XOR baseline contract mismatch")
            bits = np.bitwise_xor(bits, baseline.view("<u4"))
        value = bits.view("<f4")
    else:
        raise ValueError("Unknown native encoding")
    if fingerprint(value) != expected:
        raise ValueError("Decoded native array bit digest mismatch")
    return value


def write_native(path, array, *, baseline=None, wave=None):
    """Publish one exact array; wave is a binding to an already closed array."""
    path = Path(path)
    if path.suffix != ".json" or path.exists():
        raise ValueError("Expected a new JSON native manifest")
    value = np.ascontiguousarray(array)
    if value.dtype != np.dtype("<f4") or not np.isfinite(value).all():
        raise ValueError("Expected finite little-endian FP32 native values")
    metadata = {"format": "exact-native-f32-v1", "values": fingerprint(value)}
    prior = load_native(baseline) if baseline is not None else None
    if prior is not None and (prior.shape != value.shape or prior.dtype != value.dtype):
        raise ValueError("Baseline contract mismatch")
    if wave is not None:
        if prior is None:
            raise ValueError("An addition recipe requires an immutable baseline")
        delta = load_native(wave)
        if delta.shape != value.shape or delta.dtype != value.dtype:
            raise ValueError("Wave contract mismatch")
        reproduced = np.add(prior, delta, dtype=np.float32)
        if fingerprint(reproduced) == metadata["values"]:
            metadata.update(encoding="checked-f32-add", baseline=baseline, wave=wave)
    if "encoding" not in metadata:
        bits = value.view("<u4")
        if prior is not None:
            bits = np.bitwise_xor(bits, prior.view("<u4"))
        planes = bits.view(np.uint8).reshape(-1, 4).T.copy().tobytes()
        payload = path.with_suffix(".zlib")
        publish_exclusive(payload, zlib.compress(planes, level=6))
        metadata.update(
            encoding="byteplanes-zlib" if prior is None else "xor-byteplanes-zlib",
            payload=ref(payload),
        )
        if prior is not None:
            metadata["baseline"] = baseline
    publish_exclusive(path, (json.dumps(metadata, indent=2, allow_nan=False) + "\n").encode())
    binding = ref(path)
    if fingerprint(load_native(binding)) != metadata["values"]:
        raise ValueError("Published native round trip failed")
    return binding

"""Check exact EMA arithmetic before measuring isolated update latency."""

import argparse
import ast
import hashlib
import json
import os
import random
import statistics
import time
from pathlib import Path

import psutil
import torch

from demosaic.safety import writable_path

SCHEDULE_POSITIONS = (1, 12, 13, 2000, 2001, 8000, 10000, 40000)
PROFILE_STATUS = Path("/mnt/external/demosaic/runs/mixed16-packed-profile-after-quarter-v1.json")
PROFILE_OWNER = {"pid": 2714232, "created": 1792306477.92}
PROFILE_TERMINAL = "completed-bounded-mixed16-quarter-FP32-CUDA-profiles-awaiting-trace-analysis"


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def state_hash(values):
    digest = hashlib.sha256()
    for name, value in values.items():
        digest.update(name.encode() + b"\0")
        digest.update(
            value.detach().contiguous().cpu().reshape(-1).view(torch.uint8).numpy().tobytes()
        )
    return digest.hexdigest()


def validate_states(values, ema):
    if not values or set(values) != set(ema):
        raise ValueError("EMA and model must contain the same nonempty named state")
    devices = {value.device for value in values.values()}
    if len(devices) != 1:
        raise ValueError("This measurement requires one device")
    for name, value in values.items():
        target = ema[name]
        if value.dtype != torch.float32 or target.dtype != torch.float32:
            raise ValueError("This measurement supports FP32 state only")
        if value.shape != target.shape or value.device != target.device:
            raise ValueError("Named EMA shapes and devices must match")
        if not torch.isfinite(value).all() or not torch.isfinite(target).all():
            raise ValueError("EMA measurement requires finite state")


def original_update(path, expected_sha256):
    if sha(path) != expected_sha256:
        raise ValueError("Frozen training source checksum differs")
    tree = ast.parse(Path(path).read_text())
    functions = [n for n in tree.body if isinstance(n, ast.FunctionDef) and n.name == "update_ema"]
    if len(functions) != 1:
        raise ValueError("Expected exactly one original EMA function")
    namespace = {"torch": torch}
    exec(  # noqa: S102 -- Execute only the caller's hash-checked own training function.
        compile(ast.Module(body=functions, type_ignores=[]), str(path), "exec"), namespace
    )
    return namespace["update_ema"]


class StateOnly:
    def __init__(self, values):
        self.values = values

    def restoration_state_dict(self):
        return self.values


@torch.no_grad()
def grouped_update(values, ema, decay):
    torch._foreach_lerp_([ema[name] for name in values], list(values.values()), 1 - decay)


def clone_state(values):
    return {name: value.clone() for name, value in values.items()}


def owner_alive(owner):
    try:
        process = psutil.Process(owner["pid"])
        return (
            process.create_time() == owner["created"] and process.status() != psutil.STATUS_ZOMBIE
        )
    except psutil.NoSuchProcess:
        return False


def check_gpu_release():
    status = json.loads(PROFILE_STATUS.read_text())
    if status["status"] != PROFILE_TERMINAL:
        raise RuntimeError("The existing inference profile must finish before CUDA EMA work")
    if status["controller"] != PROFILE_OWNER or any(
        owner_alive(status[k]) for k in ("controller", "child")
    ):
        raise RuntimeError("The exact inference profile owner and child must have exited")
    return {"path": str(PROFILE_STATUS), "sha256": sha(PROFILE_STATUS)}


def compare_case(values, initial, decay, scalar, *, updates=5):
    reference, candidate = clone_state(initial), clone_state(initial)
    model = StateOnly(values)
    matches = []
    for _ in range(updates):
        scalar(model, reference, decay)
        grouped_update(values, candidate, decay)
        matches.append(state_hash(reference) == state_hash(candidate))
    strides = all(reference[n].stride() == candidate[n].stride() for n in values)
    return {
        "decay": decay,
        "byte_identical_after_each_update": matches,
        "identical_strides": strides,
        "reference_state_sha256": state_hash(reference),
        "grouped_state_sha256": state_hash(candidate),
        "passed": all(matches) and strides,
    }


def measure(values, initial, scalar, decay, output, device, warmup, samples):
    model = StateOnly(values)
    states = {method: clone_state(initial) for method in ("scalar", "grouped")}

    def sync():
        if device.type == "cuda":
            torch.cuda.synchronize(device)

    def update(method):
        if method == "scalar":
            scalar(model, states[method], decay)
        else:
            grouped_update(values, states[method], decay)

    for _ in range(warmup):
        for method in states:
            update(method)
    sync()
    order = list(states) * samples
    random.Random(42).shuffle(order)
    timings = {method: [] for method in states}
    for method in order:
        sync()
        start_event = end_event = None
        if device.type == "cuda":
            start_event = torch.cuda.Event(enable_timing=True)
            end_event = torch.cuda.Event(enable_timing=True)
            start_event.record()
        started = time.perf_counter()
        update(method)
        if end_event is not None:
            end_event.record()
        sync()
        elapsed = (time.perf_counter() - started) * 1000
        event_ms = start_event.elapsed_time(end_event) if start_event is not None else None
        assert elapsed > 0 and (event_ms is None or event_ms > 0)
        timings[method].append({"synchronized_wall_ms": elapsed, "CUDA_event_ms": event_ms})
    assert state_hash(states["scalar"]) == state_hash(states["grouped"])
    profiles = {}
    activities = [torch.profiler.ProfilerActivity.CPU]
    if device.type == "cuda":
        activities.append(torch.profiler.ProfilerActivity.CUDA)
    for method in states:
        with (
            torch.profiler.profile(activities=activities) as profile,
            torch.profiler.record_function(f"demosaic::EMA-{method}"),
        ):
            update(method)
            sync()
        cuda_events = sum(
            str(event.device_type) == "DeviceType.CUDA" and event.time_range.elapsed_us() > 0
            for event in profile.events()
        )
        assert device.type != "cuda" or cuda_events > 0
        trace = output / f"EMA-{method}-trace.json"
        profile.export_chrome_trace(str(trace))
        profiles[method] = {
            "trace": {"path": str(trace), "sha256": sha(trace)},
            "genuine_CUDA_trace_events": cuda_events,
            "operator_calls": {event.key: event.count for event in profile.key_averages()},
        }
    assert state_hash(states["scalar"]) == state_hash(states["grouped"])
    return {
        "warmup": warmup,
        "samples_per_method": samples,
        "balanced_shuffled_order": order,
        "samples": timings,
        "synchronized_wall_median_ms": {
            method: statistics.median(row["synchronized_wall_ms"] for row in rows)
            for method, rows in timings.items()
        },
        "profiles": profiles,
        "post_timing_and_trace_states_byte_identical": True,
    }


def main(
    checkpoint,
    train_source,
    train_sha256,
    output,
    device="cuda",
    warmup=3,
    samples=10,
    expected_torch=None,
):
    os.nice(10)
    torch.set_num_threads(2)
    if expected_torch is not None and str(torch.__version__) != expected_torch:
        raise ValueError("Torch version differs from CPU preflight")
    if warmup < 1 or samples < 2:
        raise ValueError("Use at least one warmup and two samples")
    device = torch.device(device)
    if device.type not in ("cpu", "cuda"):
        raise ValueError("Use CPU or CUDA")
    release = check_gpu_release() if device.type == "cuda" else None
    source_digest = sha(__file__)
    output = writable_path(output)
    output.mkdir(parents=True, exist_ok=False)
    checkpoint_digest = sha(checkpoint)
    state = torch.load(checkpoint, map_location="cpu", weights_only=False)
    assert (
        state["config"]["steps"] == 40000
        and state["model_config"]["restoration_backbone"] == "packed-isotropic"
    )
    if device.type == "cuda":
        assert state["step"] == 10000 and state["example_draws"] == 160000
    scalar = original_update(train_source, train_sha256)
    identity = {
        "path": str(checkpoint.resolve()),
        "sha256": checkpoint_digest,
        "step": state["step"],
        "example_draws": state["example_draws"],
        "DINO": state["model_config"]["dino"],
    }
    values = {name: value.to(device) for name, value in state["model"].items()}
    initial = {name: value.to(device) for name, value in state["ema"].items()}
    validate_states(values, initial)
    source_hash, initial_hash = state_hash(values), state_hash(initial)
    cpu_rng, python_rng = torch.get_rng_state(), random.getstate()
    cuda_rng = torch.cuda.get_rng_state(device) if device.type == "cuda" else None
    cases = []
    for position in SCHEDULE_POSITIONS:
        decay = min(state["config"]["ema_decay"], (position + 1) / (position + 10))
        cases.append(
            {"decay_schedule_step": position, **compare_case(values, initial, decay, scalar)}
        )
    passed = all(case["passed"] for case in cases)
    measurements = (
        measure(
            values, initial, scalar, state["config"]["ema_decay"], output, device, warmup, samples
        )
        if passed
        else None
    )
    assert state_hash(values) == source_hash and state_hash(initial) == initial_hash
    assert torch.equal(torch.get_rng_state(), cpu_rng) and random.getstate() == python_rng
    if cuda_rng is not None:
        assert torch.equal(torch.cuda.get_rng_state(device), cuda_rng)
    assert torch.cuda.is_initialized() is (device.type == "cuda")
    assert sha(checkpoint) == checkpoint_digest and sha(train_source) == train_sha256
    assert sha(__file__) == source_digest
    if release is not None:
        assert sha(release["path"]) == release["sha256"]
    archive = output / "source"
    archive.mkdir()
    for path in (Path(__file__), train_source):
        (archive / path.name).write_bytes(path.read_bytes())
    result = {
        "status": (
            "completed-EMA-CPU-instrumentation-preflight-no-GPU-timing"
            if device.type == "cpu"
            else "completed-EMA-CUDA-state-and-latency-measurement"
        )
        if passed
        else "rejected-EMA-state-difference-no-timing-or-adoption",
        "checkpoint": identity,
        "source": {"path": str(Path(__file__)), "sha256": sha(__file__)},
        "frozen_train": {"path": str(train_source), "sha256": train_sha256},
        "torch": str(torch.__version__),
        "device": str(device),
        "state_tensors": len(values),
        "strict_state_equivalence_passed": passed,
        "cases": cases,
        "measurements": measurements,
        "source_and_initial_EMA_values_unchanged": True,
        "CPU_Python_CUDA_RNG_unchanged": True,
        "checkpoint_bytes_unchanged": True,
        "CUDA_initialized": torch.cuda.is_initialized(),
        "previous_profile_release": release,
        "scope": "Isolated EMA updates on cloned actual FP32 checkpoint state. Eight original "
        "schedule positions/five updates each; strict byte equality before any timings. "
        "Model values stay fixed. Timings exclude source loading and state transfer; "
        "not whole-step training, I/O, network inference or 100MP timing. CPU mode "
        "checks wiring only. No optimizer update, learned weights, production change "
        "or automatic adoption. Shared-machine observations are not an idle hardware optimum.",
    }
    (output / "result.json").write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    print(json.dumps({"status": result["status"], "result": str(output / "result.json")}))
    return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("checkpoint", "train-source", "output"):
        parser.add_argument("--" + name, type=Path, required=True)
    parser.add_argument("--train-sha256", required=True)
    parser.add_argument("--device", choices=("cpu", "cuda"), default="cuda")
    parser.add_argument("--warmup", type=int, default=3)
    parser.add_argument("--samples", type=int, default=10)
    parser.add_argument("--expected-torch")
    main(**vars(parser.parse_args()))

"""Explicit frozen-encoder identities for source-frozen experiment operators."""

import re
from collections.abc import Mapping

CONVNEXT_TINY_SHA256 = "370a84c2d9e1d216757422c0a25ceb82a0a106083ba8ca545d9b267e704540fd"


def sha256_identity(value):
    if not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None:
        raise ValueError("Frozen backbone requires a full lowercase SHA256")
    return value


def backbone_identity(model_config, sha256):
    """Bind the architecture/revision to a separately measured parameter hash."""
    identity = {
        "model": model_config.get("dino_model"),
        "revision": model_config.get("dino_revision"),
        "sha256": sha256,
    }
    return validate_backbone_identity(identity)


def validate_backbone_identity(identity):
    if not isinstance(identity, Mapping) or set(identity) != {"model", "revision", "sha256"}:
        raise ValueError("Frozen backbone identity requires model, revision and sha256")
    name, revision = identity["model"], identity["revision"]
    if not isinstance(name, str) or not name or name != name.strip():
        raise ValueError("Frozen backbone requires an explicit model name")
    if not isinstance(revision, str) or re.fullmatch(r"[0-9a-f]{40}", revision) is None:
        raise ValueError("Frozen backbone requires a pinned 40-character revision")
    return {"model": name, "revision": revision, "sha256": sha256_identity(identity["sha256"])}


def verify_backbone_identity(model_config, actual_sha256, record, *, legacy_sha256):
    """Preserve legacy shared-hash checks; explicit records also check name/revision."""
    identity = record.get("expected_backbone")
    if identity is None:
        expected_sha256 = sha256_identity(legacy_sha256)
    else:
        identity = validate_backbone_identity(identity)
        expected_sha256 = identity["sha256"]
        if (
            model_config.get("dino_model") != identity["model"]
            or model_config.get("dino_revision") != identity["revision"]
        ):
            raise ValueError("Loaded frozen backbone model/revision differs from its record")
    if sha256_identity(actual_sha256) != expected_sha256:
        raise ValueError("Loaded frozen backbone parameters differ from their SHA256")
    return expected_sha256

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_coherent_phase_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 798
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail"):
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 4788 and retained == 1374 and real == 42 and len(result["rows"]) == 6162
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 6162,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


