"""Selected-bin proximity to hidden CFA template power, never a recovery bound.

Counterfactual selection reads one RAW green phase at a time. Exact templates
are diagnostic-only inputs. Local interpolation/mixing can create frequencies
outside a Fourier footprint, and principal CFA aliases remain unresolved.
"""

import math

import numpy as np


def eligible_bins(shape, lower, upper, *, upper_inclusive=True):
    if (
        len(shape) != 2
        or any(type(n) is not int or n < 8 for n in shape)
        or not math.isfinite(lower)
        or not math.isfinite(upper)
        or not 0 < lower < upper <= math.sqrt(2) / 4
    ):
        raise ValueError("Expected axes>=8 and finite ordered principal radial band")
    fy, fx = [np.fft.fftfreq(n) / 2 for n in shape]
    radius = np.hypot(fy[:, None], fx[None, :])
    upper_mask = radius <= upper if upper_inclusive else radius < upper
    return (
        (radius >= lower)
        & upper_mask
        & ((fy[:, None] > 0) | ((fy[:, None] == 0) & (fx[None, :] > 0)))
    )


def select_bins(spectrum, variance, eligible, *, count=4):
    spectrum, variance, available = [np.asarray(v) for v in [spectrum, variance, eligible]]
    if (
        spectrum.ndim != 2
        or variance.shape != spectrum.shape
        or available.shape != spectrum.shape
        or available.dtype != np.bool_
        or not np.isfinite(spectrum).all()
        or not np.isfinite(variance).all()
        or (variance <= 0).any()
        or type(count) is not int
        or not 1 <= count <= 16
    ):
        raise ValueError("Expected finite spectrum/positive variance/boolean mask and count1..16")
    available = available.copy()
    power = np.abs(spectrum) ** 2 / variance
    bins = []
    for _ in range(count):
        score = np.where(available, power, -np.inf)
        flat = int(np.argmax(score))
        if not np.isfinite(score.flat[flat]):
            break
        y, x = divmod(flat, spectrum.shape[1])
        bins.append([y, x])
        for cy, cx in [(y, x), ((-y) % len(spectrum), (-x) % spectrum.shape[1])]:
            for dy in [-1, 0, 1]:
                for dx in [-1, 0, 1]:
                    available[(cy + dy) % len(spectrum), (cx + dx) % spectrum.shape[1]] = False
    return bins


def footprint(shape, bins, radius):
    if len(shape) != 2 or type(radius) is not int or radius < 0:
        raise ValueError("Expected two axes and nonnegative integer bin radius")
    result = np.zeros(shape, dtype=bool)
    bins = np.asarray(bins)
    if bins.size == 0:
        return result
    if (
        bins.ndim != 2
        or bins.shape[1] != 2
        or not np.issubdtype(bins.dtype, np.integer)
        or not ((bins >= 0) & (bins < shape)).all()
    ):
        raise ValueError("Expected in-range integer Nx2 frequency bins")
    for y, x in bins:
        for cy, cx in [(y, x), ((-y) % shape[0], (-x) % shape[1])]:
            for dy in range(-radius, radius + 1):
                for dx in range(-radius, radius + 1):
                    result[(cy + dy) % shape[0], (cx + dx) % shape[1]] = True
    return result


def power_fraction(power, mask):
    power, mask = np.asarray(power), np.asarray(mask)
    if (
        power.ndim != 2
        or mask.shape != power.shape
        or mask.dtype != np.bool_
        or not np.isfinite(power).all()
        or (power < 0).any()
    ):
        raise ValueError("Expected finite nonnegative power and matching mask")
    total = float(power.sum(dtype=np.float64))
    return None if total == 0 else float(power[mask].sum(dtype=np.float64) / total)


def sample_camera_rgb(value, colors):
    value, colors = np.asarray(value), np.asarray(colors)
    if (
        value.ndim != 4
        or value.shape[1] != 3
        or colors.shape != (len(value), 4)
        or not np.isfinite(value).all()
    ):
        raise ValueError("Expected finite Nx3 RGB and Nx4 CFA layout")
    allowed = {(0, 1, 1, 2), (2, 1, 1, 0), (1, 0, 2, 1), (1, 2, 0, 1)}
    if any(tuple(c) not in allowed for c in colors):
        raise ValueError("Expected standard CFA layout")
    return np.stack(
        [
            np.stack([rgb[int(c), p // 2 :: 2, p % 2 :: 2] for p, c in enumerate(layout)])
            for rgb, layout in zip(value, colors, strict=True)
        ]
    )

"""Separate V63's saved exact-target errors by color mean and spatial scale.

No inference or corrected images: these are additive error energies, not scores
for an oracle mean-subtracted restoration. All inputs come from a hash-bound
completed endpoint comparison. Real captures have no exact target and are omitted.
"""

import argparse
import hashlib
import json
import math
import shutil
from datetime import UTC, datetime
from pathlib import Path

import numpy as np


def reference(path):
    path = Path(path).resolve()
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"path": str(path), "sha256": digest}


def verify(ref):
    actual = reference(ref["path"])
    if actual["sha256"] != ref["sha256"]:
        raise ValueError(f"Changed input: {ref['path']}")
    return Path(actual["path"])


def read(ref):
    return json.loads(verify(ref).read_text())


def decompose(error, levels=4):
    error = np.asarray(error, dtype=np.float64)
    if error.ndim != 3 or error.shape[0] != 3 or not np.isfinite(error).all():
        raise ValueError("Expected finite RGB CHW error")
    if levels < 1 or any(side < 1 or side % 2**levels for side in error.shape[-2:]):
        raise ValueError("Spatial dimensions must divide into complete Haar blocks")
    bias = error.mean(axis=(-2, -1), keepdims=True)
    residual = error - bias
    coarse = residual
    bands = {}
    for level in range(1, levels + 1):
        a, b = coarse[:, ::2, ::2], coarse[:, ::2, 1::2]
        c, d = coarse[:, 1::2, ::2], coarse[:, 1::2, 1::2]
        details = [(a - b + c - d) / 2, (a + b - c - d) / 2, (a - b - c + d) / 2]
        bands[str(2**level)] = sum(float(np.sum(x * x)) for x in details) / error.size
        coarse = (a + b + c + d) / 2
    bands[f"coarser_than_{2**levels}"] = float(np.sum(coarse * coarse) / error.size)
    result = {
        "MSE": float(np.mean(error * error)),
        "signed_channel_mean_error": bias.ravel().tolist(),
        "mean_bias_MSE": float(np.mean(bias * bias)),
        "zero_mean_MSE": float(np.mean(residual * residual)),
        "zero_mean_Haar_MSE_by_block_side": bands,
    }
    return result


def audit(error, result, levels=4):
    """Independent scalar moments and nested block-average energy differences."""
    error = np.asarray(error, dtype=np.float64)
    channel_values = [channel.ravel().tolist() for channel in error]
    means = [math.fsum(values) / len(values) for values in channel_values]
    mse = math.fsum(x * x for values in channel_values for x in values) / error.size
    bias_mse = math.fsum(x * x for x in means) / 3
    residual_mse = (
        math.fsum((x - mean) ** 2 for values, mean in zip(channel_values, means) for x in values)
        / error.size
    )
    differences = [
        abs(result["MSE"] - mse),
        abs(result["mean_bias_MSE"] - bias_mse),
        abs(result["zero_mean_MSE"] - residual_mse),
        abs(result["MSE"] - result["mean_bias_MSE"] - result["zero_mean_MSE"]),
        abs(math.fsum(result["zero_mean_Haar_MSE_by_block_side"].values()) - residual_mse),
        *(abs(a - b) for a, b in zip(result["signed_channel_mean_error"], means)),
    ]
    previous = residual_mse
    channels, height, width = error.shape
    for level in range(1, levels + 1):
        side = 2**level
        block_means = error.reshape(channels, height // side, side, width // side, side).mean(
            axis=(2, 4)
        )
        remaining = float(np.mean((block_means - np.array(means)[:, None, None]) ** 2))
        differences.append(
            abs(result["zero_mean_Haar_MSE_by_block_side"][str(side)] - (previous - remaining))
        )
        previous = remaining
    differences.append(
        abs(result["zero_mean_Haar_MSE_by_block_side"][f"coarser_than_{2**levels}"] - previous)
    )
    maximum = max(differences)
    if maximum > 1e-14:
        raise ValueError(f"Error-energy decomposition failed independent identities: {maximum}")
    return maximum


def display(rgb, wb, matrix):
    linear = np.einsum("ij,jhw->ihw", matrix, rgb * wb[:, None, None]).clip(0, 1)
    return np.where(linear <= 0.0031308, linear * 12.92, 1.055 * linear ** (1 / 2.4) - 0.055)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--comparison", type=Path, required=True)
    parser.add_argument("--sha256", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise ValueError("Refuse to replace an existing analysis")
    parent_ref = {"path": str(args.comparison.resolve()), "sha256": args.sha256}
    parent = read(parent_ref)
    if parent["status"] != "completed-actual-control-original20k-CPU-array-and-native-comparison":
        raise ValueError("Expected the completed V63 endpoint comparison")
    stages = ("first4k", "final20k")
    plans = [read(parent["plans"][stage]["receipt"]) for stage in stages]
    if plans[0]["observations"] != plans[1]["observations"]:
        raise ValueError("Endpoint observations differ")
    observation_plan = read(plans[0]["observations"])
    cases = {case["id"]: case for case in observation_plan["cases"]}
    exact = {key: value for key, value in cases.items() if value["kind"] in ("photo", "analytic")}
    if set(exact) != {"exact-photo-0", "exact-photo-1", "fabric-mean", "fabric-cyclic-gbr"}:
        raise ValueError("Unexpected exact-target cohort")
    records, inputs, maximum = [], [], 0.0
    for stage, step, plan in zip(stages, (4000, 20000), plans, strict=True):
        execution = read(parent["executions"][stage])
        if execution["checkpoint"] != plan["checkpoint"] or execution["step"] != step:
            raise ValueError("Wrong endpoint")
        verify(execution["checkpoint"])
        predictions = {item["case"]: item for item in execution["float_predictions"]}
        for name, case in exact.items():
            prediction_ref = predictions[name]
            prediction = np.load(verify(prediction_ref), allow_pickle=False)
            observation_path = verify(case["arrays"])
            with np.load(observation_path, allow_pickle=False) as arrays:
                target = arrays["target"]
                wb, matrix = (
                    arrays["wb"][0].astype(np.float64),
                    arrays["matrix"][0].astype(np.float64),
                )
                if target.dtype != np.float32 or prediction.dtype != np.float32:
                    raise ValueError("Expected the original F32 arrays")
                if prediction.shape != target.shape or target.shape != (1, 3, 256, 256):
                    raise ValueError("Wrong native context dimensions")
                if not np.isfinite(target).all() or not np.isfinite(prediction).all():
                    raise ValueError("Nonfinite target/prediction")
                target, prediction = target[0].astype(np.float64), prediction[0].astype(np.float64)
            if case["display_exposure"] != 1:
                raise ValueError("Unexpected display exposure")
            inputs.append(
                {
                    "stage": stage,
                    "case": name,
                    "prediction": prediction_ref,
                    "observation": case["arrays"],
                    "checkpoint": execution["checkpoint"],
                }
            )
            for space, pred, truth in (
                ("camera_linear_unclipped", prediction, target),
                (
                    "sRGB_clipped_float64",
                    display(prediction, wb, matrix),
                    display(target, wb, matrix),
                ),
            ):
                for region, xywh in (
                    ("border8", [8, 8, 240, 240]),
                    ("native_crop", case["ROI_xywh"]),
                ):
                    x, y, width, height = xywh
                    error = (pred - truth)[:, y : y + height, x : x + width]
                    result = decompose(error)
                    maximum = max(maximum, audit(error, result))
                    records.append(
                        {
                            "case": name,
                            "stage": stage,
                            "space": space,
                            "region": region,
                            "ROI_xywh": xywh,
                            **result,
                        }
                    )
    pairs = []
    for before in (row for row in records if row["stage"] == "first4k"):
        after = next(
            row
            for row in records
            if row["stage"] == "final20k"
            and all(row[key] == before[key] for key in ("case", "space", "region"))
        )
        pairs.append(
            {
                **{key: before[key] for key in ("case", "space", "region")},
                "delta_MSE": after["MSE"] - before["MSE"],
                "delta_mean_bias_MSE": after["mean_bias_MSE"] - before["mean_bias_MSE"],
                "delta_zero_mean_MSE": after["zero_mean_MSE"] - before["zero_mean_MSE"],
                "delta_zero_mean_Haar_MSE_by_block_side": {
                    key: after["zero_mean_Haar_MSE_by_block_side"][key] - value
                    for key, value in before["zero_mean_Haar_MSE_by_block_side"].items()
                },
            }
        )
    result = {
        "status": "completed-saved-control-error-decomposition-no-inference",
        "created_UTC": datetime.now(UTC).isoformat(),
        "parent": parent_ref,
        "operator": reference(__file__),
        "inputs": inputs,
        "records": records,
        "pairs": pairs,
        "independent_scalar_and_block_average_audit_max_absolute_error": maximum,
        "audit_tolerance": 1e-14,
        "new_neural_forwards": 0,
        "limits": [
            "Four previously selected exact targets; no population estimate or causal claim.",
            "Haar scales are aligned block supports, not a Fourier transfer function.",
            "sRGB uses float64 rendering and is not an exact replay of float32 PSNR.",
            "Subtracting target-based means here does not produce a deployable correction.",
            "No real-photo reference is scored, and no model is promoted.",
        ],
    }
    args.output.mkdir(parents=True)
    shutil.copyfile(__file__, args.output / "operator-source.py")
    (args.output / "result.json").write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
    print(
        json.dumps(
            {
                "result": reference(args.output / "result.json"),
                "records": len(records),
                "independent_max_error": maximum,
            }
        )
    )


if __name__ == "__main__":
    main()

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from diagnose_support_crossover import METHODS, ORIGINALS
from score_support_crossover import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == (822 if label in ORIGINALS else 0)
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    source_aliases = {
        "native-native": "noisy-control-raw-step1000",
        "relative-relative": "relative-phase-raw-step1000",
    }
    for row in cached["rows"]:
        for current, old in source_aliases.items():
            if row["method"] == old:
                cached_rows[row["id"], current] = row
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in ORIGINALS)
            assert row["derived_diagnostic"] == (label in METHODS and label not in ORIGINALS)
            calls += label in ORIGINALS
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == int(
                    label in ORIGINALS
                )
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 1644 and retained == 3042 and real == 42 and len(result["rows"]) == 6330
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 6330,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
