"""Verify every declared endpoint's complete GFX RGB16 exports and native samples."""

from pathlib import Path

import numpy as np
import tifffile
from audit_quality_archive import binding, write
from compare_quality_archives import read_bound


def verify_exports(stage_binding, checkpoints, destination):
    stage = read_bound(stage_binding)
    summary = read_bound(stage["report"])
    count = len(checkpoints)
    expected_sha = {item["sha256"] for item in checkpoints.values()}
    if not count or len(expected_sha) != count:
        raise ValueError("Declare distinct nonempty endpoint checkpoints")
    if len(summary["models"]) != count or len(summary["full_frames"]) != count:
        raise ValueError("Full-frame model coverage differs from declared checkpoints")
    if {item["sha256"] for item in summary["models"]} != expected_sha:
        raise ValueError("Full-frame checkpoint identities differ")
    checked, outputs = 0, []
    for model, frame in zip(summary["models"], summary["full_frames"], strict=True):
        if model["label"] != frame["model_label"]:
            raise ValueError("Full-frame labels differ")
        files, linear = [], None
        if len(frame["files"]) != 2:
            raise ValueError("Require both linear and sRGB exports per endpoint")
        roles = []
        for item in frame["files"]:
            path = Path(stage["report"]["path"]).parent / item["path"]
            bound = binding(path)
            if bound["sha256"] != item["sha256"] or path.stat().st_size != item["bytes"]:
                raise ValueError("Changed RGB16 export")
            pixels = tifffile.memmap(path, mode="r")
            if pixels.shape != (8746, 11662, 3) or pixels.dtype != np.uint16:
                raise ValueError("Require complete GFX RGB16 pixels")
            if pixels.shape[0] * pixels.shape[1] / 1e6 != frame["timing"]["megapixels"]:
                raise ValueError("Export dimensions differ from the recorded frame")
            files.append({"file": bound, "shape": list(pixels.shape), "dtype": str(pixels.dtype)})
            if item["path"].endswith("-linear16.tiff"):
                roles.append("linear")
                linear = pixels
            elif item["path"].endswith("-srgb16.tiff"):
                roles.append("srgb")
            else:
                raise ValueError("Unrecognized RGB16 export role")
        if sorted(roles) != ["linear", "srgb"]:
            raise ValueError("Require one linear and one sRGB export")
        regions = [
            row
            for row in stage["full_native_floats"]
            if row["checkpoint"]["sha256"] == model["sha256"]
        ]
        if len(regions) != 6 or len({row["region"]["name"] for row in regions}) != 6:
            raise ValueError("Require six distinct native regions per endpoint")
        for row in regions:
            if binding(row["array"]["path"]) != row["array"]:
                raise ValueError("Changed native float array")
            native = np.load(row["array"]["path"], allow_pickle=False)
            if (
                native.shape != (1, 3, 160, 160)
                or native.dtype != np.float32
                or not np.isfinite(native).all()
            ):
                raise ValueError("Require finite native160 FP32 camera RGB")
            expected = np.rint(np.clip(native[0].transpose(1, 2, 0), 0, 1) * 65535).astype(
                np.uint16
            )
            x, y = row["region"]["noisy_xy"]
            actual = linear[y : y + 160, x : x + 160]
            if not np.array_equal(actual, expected):
                raise ValueError(
                    f"Linear RGB16 quantization differs: {model['label']} / {row['region']['name']}"
                )
            checked += actual.size
        outputs.append(
            {
                "checkpoint_sha256": model["sha256"],
                "files": files,
                "native_regions": [row["region"] for row in regions],
                "timing": frame["timing"],
            }
        )
    if checked != 460800 * count:
        raise ValueError("Native export verification coverage differs")
    write(
        destination,
        {
            "stage": stage_binding,
            "models": outputs,
            "RGB16_values_checked_against_retained_FP32": checked,
            "new_neural_forwards": 0,
            "new_noise_observations": 0,
            "RAW_decodes": 0,
            "scope": "Both full-frame TIFF hashes/types/shapes and exact linear-camera FP32 clip/round quantization at six native ROIs per declared endpoint. sRGB native quantization is not independently recomputed. Timings are observations, not a controlled speed comparison.",
        },
    )
    return binding(destination)

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_noisy_objective_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 4932 and retained == 1398 and real == 42 and len(result["rows"]) == 6330
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 6330,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())

"""Prepare resumable camera-linear public RAW targets for review, never training.

Uses the existing phase-aligned native binning. Source/decode/cache provenance,
clipping statistics and inspection previews are retained in quarantine. A
separate pinned admission remains mandatory before a training loader accepts it.
"""

import argparse
import fcntl
import hashlib
import json
import re
import subprocess
from dataclasses import asdict
from pathlib import Path

import numpy as np
import psutil
import rawpy
from PIL import Image

from demosaic.io import orient, read_raw
from demosaic.paired import verify_file
from demosaic.raw_clean import bin_bayer
from demosaic.safety import writable_path


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def normalized_camera(camera):
    return re.sub(r"[^A-Z0-9]", "", camera.upper())


def protected_identity(camera, metadata):
    camera = normalized_camera(camera)
    if camera.endswith(("EOSM100", "DMCGH1")):
        return "camera-held-out-for-unseen-development"
    text = json.dumps(metadata)
    if re.search(r"DSCF(?:3835|3842|3879|3880|3883)", text, re.IGNORECASE):
        return "standing-GFX-capture-identifier"
    if "GFX100S" in camera and "2023:12:31" in text:
        return "standing-GFX-capture-date-family"
    return None


def qualitative_capture_hashes(config):
    """Keep the extra RAW/JPEG comparison out even when capture metadata is absent."""
    hashes = set()
    roots = [
        Path(".cache/gfx-green-mesh-20231231").resolve(),
        Path(".cache/gfx-qualitative-20231231").resolve(),
    ]
    for item in json.loads(Path(config).read_text())["sources"].values():
        path = Path(item["path"]).resolve()
        if not any(path.is_relative_to(root) for root in roots):
            raise ValueError("Use locally cached green-mesh qualitative sources")
        digest = sha(path)
        if digest != item["sha256"]:
            raise ValueError("Green-mesh qualitative source hash differs")
        hashes.add(digest)
    return hashes


def protected_hashes():
    base = Path("/mnt/external/demosaic/references")
    names = ["rawnind-dataset/manifest-test.json", "rawnind-dataset/manifest-development.json", "rawnind-unseen-development/manifest-development.json", "rawnind-train32/manifest-train.json"]
    hashes, sources = set(), {}
    for name in names:
        path = base / name
        sources[str(path)] = sha(path)
        data = json.loads(path.read_text())
        for scene in data["selection"]:
            for role in ["clean", "noisy"]:
                hashes.update(r["sha256"] for r in scene[role])
    config = Path("configs/gfx-qualitative-20231231.json")
    sources[str(config)] = sha(config)
    data = json.loads(config.read_text())
    for role in ["noisy", "reference"]:
        path = Path(data[role])
        if not str(path).startswith(".cache/gfx-qualitative-20231231/"):
            raise ValueError("Use locally cached standing RAWs")
        hashes.add(sha(path))
    mesh_config = Path("configs/gfx-green-mesh-20231231.json")
    if mesh_config.exists():
        sources[str(mesh_config)] = sha(mesh_config)
        hashes.update(qualitative_capture_hashes(mesh_config))
    return hashes, sources


def prepare(acquisition, output):
    acquisition = Path(acquisition).resolve()
    data = json.loads(acquisition.read_text())
    files = data["files"]
    identities = [r["sha256"] for r in files]
    if not files or len(identities) != len(set(identities)) or any(
        r["license"] != "CC0-1.0"
        or r["license_url"] != "https://creativecommons.org/publicdomain/zero/1.0/"
        or r["publisher_checksum"] != {"type": "SHA-256", "value": r["sha256"]}
        for r in files
    ):
        raise ValueError("Expected unique, checksum-verified, explicitly CC0 sources")
    excluded, protection_sources = protected_hashes()
    output = writable_path(output)
    output.mkdir(parents=True, exist_ok=True)
    with (output / ".prepare.lock").open("a") as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            raise RuntimeError("Another quarantine producer owns this output") from None
        source_paths = [Path(__file__), *[Path("src/demosaic") / name for name in ["raw_clean.py", "io.py", "color.py", "cfa.py"]]]
        recipe = {"acquisition_sha256": sha(acquisition), "source_sha256": {p.name: sha(p) for p in source_paths}, "rawpy": rawpy.__version__, "libraw": list(rawpy.libraw_version), "numpy": np.__version__, "factors": [4, 8], "trim": 1, "protected_sources": protection_sources}
        path = output / "recipe.json"
        if path.exists() and json.loads(path.read_text()) != recipe:
            raise ValueError("Quarantine recipe changed; choose a new output")
        path.write_text(json.dumps(recipe, indent=2) + "\n")
        archive = output / "source"
        archive.mkdir(exist_ok=True)
        for source in source_paths:
            (archive / source.name).write_bytes(source.read_bytes())
        (archive / "acquisition-manifest.json").write_bytes(acquisition.read_bytes())
        captures = output / "captures"
        captures.mkdir(exist_ok=True)
        rows, rejected = [], []
        for index, source in enumerate(files):
            if psutil.virtual_memory().available / 1e9 < 16:
                raise RuntimeError("Insufficient RAM for the next RAW decode")
            checked = verify_file(source["path"], source)
            if checked["sha256"] != source["sha256"]:
                raise ValueError("Source checksum differs from acquisition")
            outcome = captures / f"{source['file_id']}.json"
            if outcome.exists():
                saved = json.loads(outcome.read_text())
                if saved["source_sha256"] != checked["sha256"]:
                    raise ValueError("Cached capture source changed")
                if "row" in saved:
                    row = saved["row"]
                    for cache in [*row["caches"], {"path": row["screen_cache"], "sha256": row["screen_sha256"]}, {"path": row["preview"], "sha256": row["preview_sha256"]}]:
                        if sha(cache["path"]) != cache["sha256"]:
                            raise ValueError("Previously prepared quarantine cache changed")
                    rows.append(row)
                else:
                    rejected.append(saved["rejection"])
                print(json.dumps({"event": "quarantine-reused", "file_id": source["file_id"], "done": index + 1, "total": len(files)}), flush=True)
                continue
            reason = "existing-or-protected-source-hash" if checked["sha256"] in excluded else None
            raw, meta = None, None
            if not reason:
                try:
                    raw, meta = read_raw(checked["path"])
                except (ValueError, rawpy.LibRawError) as exc:
                    reason = f"unsupported-or-invalid-RAW: {exc}"
            if not reason:
                exif = json.loads(subprocess.run(["exiftool", "-j", "-DateTimeOriginal", "-OriginalFileName", "-OriginalRawFileName", "-Artist", "-Copyright", str(checked["path"])], check=True, capture_output=True, text=True, timeout=30).stdout)[0]
                reason = protected_identity(meta.camera, exif)
                if meta.iso is None or not 0 < meta.iso <= 200 or meta.iso != source["scouted_iso"]:
                    reason = "actual-ISO-invalid-or-differs-from-survey"
                if min(raw.shape) // 8 - 2 < 256:
                    reason = "actual-visible-sensor-too-small"
                if not np.isfinite(raw).all():
                    reason = "nonfinite-RAW-values"
            if reason:
                rejection = {"file_id": source["file_id"], "source": checked, "reason": reason}
                saved = {"source_sha256": checked["sha256"], "rejection": rejection}
                rejected.append(rejection)
            else:
                caches, quality = [], {}
                for factor in [4, 8]:
                    rgb = bin_bayer(raw, meta.pattern, factor=factor)
                    pixels = np.rint(np.clip(rgb, 0, 1) * 65535).astype(np.uint16)
                    cache = output / f"bin{factor}" / f"{checked['sha256']}.npy"
                    cache.parent.mkdir(exist_ok=True)
                    with cache.with_suffix(".npy.tmp").open("wb") as stream:
                        np.save(stream, pixels, allow_pickle=False)
                    cache.with_suffix(".npy.tmp").replace(cache)
                    caches.append({"path": str(cache), "sha256": sha(cache), "shape": list(pixels.shape), "dtype": "uint16", "bin_factor": factor, "color_space": "linear-camera-RGB", "unique_codes": len(np.unique(pixels))})
                    if factor == 4:
                        quality = {"bin4_any_channel_near_white_fraction": float((pixels.max(-1) >= 65500).mean()), "sampled_camera_quantiles_1_50_99": np.quantile(pixels[::4, ::4].astype(np.float32) / 65535, [.01, .5, .99], axis=(0, 1)).tolist(), "bin4_source_clipping_gate_passed": bool((pixels.max(-1) >= 65500).mean() <= .001)}
                    else:
                        linear = np.clip((pixels.astype(np.float32) / 65535 * np.array(meta.white_balance, np.float32)) @ np.array(meta.camera_to_srgb, np.float32).T, 0, 1)
                        screen = output / f"screen-{source['file_id']}.npy"
                        np.save(screen, np.rint(linear * 65535).astype(np.uint16), allow_pickle=False)
                        srgb = np.where(linear <= .0031308, linear * 12.92, 1.055 * linear ** (1 / 2.4) - .055)
                        preview = output / f"preview-{source['file_id']}.png"
                        Image.fromarray(orient(np.rint(srgb * 255).astype(np.uint8), meta.flip)).save(preview)
                row = {"id": checked["sha256"], "file_id": source["file_id"], "split": "quarantine", "source": checked, "raw_shape": list(raw.shape), "raw_metadata": asdict(meta), "exif": exif, "caches": caches, "source_quality": quality, "screen_cache": str(screen), "screen_sha256": sha(screen), "preview": str(preview), "preview_sha256": sha(preview), "preview_display_exposure": 1.0}
                rows.append(row)
                saved = {"source_sha256": checked["sha256"], "row": row}
                del rgb, pixels, linear, srgb
            temporary = outcome.with_suffix(".json.tmp")
            temporary.write_text(json.dumps(saved, indent=2, allow_nan=False) + "\n")
            temporary.replace(outcome)
            del raw
            print(json.dumps({"event": "quarantine-prepared" if not reason else "quarantine-rejected", "file_id": source["file_id"], "done": index + 1, "total": len(files), "reason": reason}), flush=True)
        result = {"format_version": 1, "split": "quarantine", "usage": "QUARANTINE ONLY; not a training manifest. Camera-linear low-noise estimates, not exact GT. Clipping, content and scene-overlap review remain required before separate pinned admission.", "acquisition": str(acquisition), "acquisition_sha256": sha(acquisition), "recipe": recipe, "rows": rows, "rejected": rejected}
        temporary = output / "manifest.json.tmp"
        temporary.write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
        temporary.replace(output / "manifest.json")
        return result


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--acquisition", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    data = prepare(**vars(parser.parse_args()))
    print(json.dumps({"prepared": len(data["rows"]), "rejected": len(data["rejected"])}), flush=True)

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_objective_floor_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 3288 and retained == 1374 and real == 30 and len(result["rows"]) == 4686
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 4686,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())

"""Create local-time diary entries and migrate the audited UTC filename mistakes."""

import argparse
import datetime as dt
import hashlib
import json
import re
from pathlib import Path
from zoneinfo import ZoneInfo

LOCAL = ZoneInfo("America/Los_Angeles")
REPO = Path(__file__).resolve().parents[1]
STAMP = "%Y-%m-%d-%H-%M-%S"


def local_prefix(instant):
    if instant.tzinfo is None:
        raise ValueError("Diary timestamps must be timezone-aware")
    return instant.astimezone(LOCAL).strftime(STAMP)


def create(root, title, slug):
    if not re.fullmatch(r"[a-z0-9]+(?:-[a-z0-9]+)*", slug):
        raise ValueError("Use a lowercase hyphen-separated slug")
    now = dt.datetime.now(LOCAL)
    path = root / "diary" / f"{local_prefix(now)}-{slug}.md"
    with path.open("x") as stream:
        stream.write(
            f"# {title}\n\nRecorded: {now.isoformat(timespec='seconds')} (America/Los_Angeles).\n\n"
        )
    return path


def migrate(root, audit, apply=False):
    entries = json.loads(audit.read_text())
    changes = []
    for item in entries:
        if item["kind"] != "UTC-candidate":
            continue
        # This audited cohort is unambiguous: UTC matches filesystem creation
        # within five minutes; interpreting the same prefix as local is ~7h late.
        if abs(item["UTC_delta_minutes"]) > 5 or item["local_delta_minutes"] > -400:
            raise ValueError("Ambiguous diary time requires manual review")
        old, new = root / item["path"], root / item["new_path_if_UTC"]
        if old.parent != root / "diary" or new.parent != root / "diary":
            raise ValueError("Migration must stay in the diary directory")
        if not old.is_file() or new.exists():
            raise ValueError("Missing old diary or destination collision")
        old_time = dt.datetime.strptime(old.name[:19], STAMP).replace(tzinfo=dt.UTC)
        assert new.name[:19] == local_prefix(old_time)
        changes.append(
            {
                "old_path": item["path"],
                "new_path": item["new_path_if_UTC"],
                "content_sha256_unchanged": hashlib.sha256(old.read_bytes()).hexdigest(),
                "filesystem_creation_local": item["birth_local"],
                "UTC_prefix_to_creation_minutes": item["UTC_delta_minutes"],
            }
        )
    if apply:
        manifest = root / "diary/timestamp-corrections.json"
        if manifest.exists():
            raise ValueError("Timestamp migration has already been recorded")
        for item in changes:
            (root / item["old_path"]).rename(root / item["new_path"])
            assert (
                hashlib.sha256((root / item["new_path"]).read_bytes()).hexdigest()
                == item["content_sha256_unchanged"]
            )
        manifest.write_text(
            json.dumps(
                {
                    "timezone": str(LOCAL),
                    "recorded_local": dt.datetime.now(LOCAL).isoformat(),
                    "basis": "84 audited UTC filename prefixes match original filesystem creation within5min and would lie about7h in the future if interpreted as local. Convert the represented instant using ZoneInfo; preserve every Markdown byte. Historical machine receipts retain their literal paths/hashes and can resolve renamed diary files through this mapping.",
                    "corrections": changes,
                },
                indent=2,
            )
            + "\n"
        )
    return changes


def resolve(root, path):
    candidate = Path(path)
    if candidate.is_absolute():
        candidate = candidate.relative_to(root)
    if (root / candidate).exists():
        return root / candidate
    manifest = json.loads((root / "diary/timestamp-corrections.json").read_text())
    for item in manifest["corrections"]:
        if str(candidate) == item["old_path"]:
            return root / item["new_path"]
    raise FileNotFoundError(path)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="mode", required=True)
    new = sub.add_parser("new")
    new.add_argument("title")
    new.add_argument("--slug", required=True)
    migration = sub.add_parser("migrate")
    migration.add_argument("audit", type=Path)
    migration.add_argument("--apply", action="store_true")
    alias = sub.add_parser("resolve")
    alias.add_argument("path")
    args = parser.parse_args()
    if args.mode == "new":
        print(create(REPO, args.title, args.slug))
    elif args.mode == "migrate":
        print(
            json.dumps(
                {
                    "renamed" if args.apply else "proposed": len(
                        migrate(REPO, args.audit, args.apply)
                    )
                }
            )
        )
    else:
        print(resolve(REPO, args.path))

"""CPU-only fresh-model optimization diagnosis; never export learned weights."""

import argparse
import hashlib
import json
import os
import random
import time
from contextlib import contextmanager
from pathlib import Path

import numpy as np
import psutil
import torch

from demosaic import packed_isotropic
from demosaic.cfa import bilinear
from demosaic.losses import reconstruction_loss
from demosaic.model import JointDemosaic, ModelConfig
from demosaic.paired_training import paired_reconstruction_loss
from demosaic.precision import ieee_fp32
from demosaic.train import batch_fingerprint, make_optimizer


def coordinate_map(packed, shot, read, mode):
    """Change only input coordinates; original RAW skip/output units stay fixed.

    The compander is the rationalized integral of inverse noise standard
    deviation, normalized at sensor values0 and1, with linear continuation below
    zero. Its coefficients are supplied shot/read parameters, never image stats.
    Gaussian-only/ADC-only observations retain their original coordinates.
    """
    with torch.autocast(packed.device.type, enabled=False), ieee_fp32():
        packed = packed.float()
        if mode == "raw":
            return packed
        if mode == "gain32":
            return packed * 32
        if mode != "noise-compand":
            raise ValueError("Unknown feature coordinate mode")
        shot = torch.as_tensor(shot, dtype=torch.float32, device=packed.device)
        read = torch.as_tensor(read, dtype=torch.float32, device=packed.device)
        offset = (read + 0.375 * shot.square()).clamp_min(1e-12)
        origin = offset.sqrt()
        scale = (shot + offset).sqrt() + origin
        positive = (shot * packed.clamp_min(0) + offset).sqrt() + origin
        denominator = torch.where(packed >= 0, positive, 2 * origin)
        mapped = packed * (scale / denominator)
        return torch.where(shot == 0, packed, mapped)


@contextmanager
def feature_mode(mode, batch):
    """Isolated process-local prototype; leave production modules/config intact."""
    original = packed_isotropic.physical_features

    def features(packed, variance, colors, wb=None, matrix=None):
        legacy = original(packed, variance, colors, wb, matrix)
        mapped = coordinate_map(packed, batch["shot"], batch["read"], mode)
        return torch.cat((mapped, legacy[:, 4:]), 1)

    packed_isotropic.physical_features = features
    try:
        yield
    finally:
        packed_isotropic.physical_features = original


def read(path):
    return json.loads(Path(path).read_text())


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def ref(path):
    return {"path": str(path), "sha256": sha(path)}


def digest(items):
    value = hashlib.sha256()
    for name, tensor in items:
        value.update(name.encode())
        value.update(tensor.detach().contiguous().numpy().tobytes())
    return value.hexdigest()


def alive(owner):
    try:
        process = psutil.Process(owner["pid"])
        return (
            process.create_time() == owner["created"] and process.status() != psutil.STATUS_ZOMBIE
        )
    except psutil.NoSuchProcess:
        return False


def guard(plan):
    for path, expected in {**plan["inputs"], **plan["guards"]}.items():
        assert sha(path) == expected, path


def loss_for(model, batch, domain):
    prediction, auxiliary = model(
        *(batch[key] for key in ["packed", "variance", "colors", "wb", "matrix"]), auxiliary=True
    )
    if domain == "paired":
        loss, _ = paired_reconstruction_loss(prediction, batch, auxiliary)
    else:
        loss, _ = reconstruction_loss(prediction, batch, auxiliary, physical_fp32=True)
    return prediction, loss


def mse(prediction, batch, domain):
    if domain == "paired":
        mask = batch["sensor_mask"].bool()
        error = (prediction - batch["sensor_reference"]).square()
        return float(error.masked_fill(~mask, 0).sum() / mask.sum().clamp_min(1))
    return float((prediction - batch["target"]).square().mean())


def run(plan_path):
    assert not torch.cuda.is_available() and not torch.cuda.is_initialized(), "Hide CUDA"
    torch.set_num_threads(2)
    torch.set_num_interop_threads(1)
    plan = read(plan_path)
    guard(plan)
    root = Path(plan["root"])
    status = Path(plan["status"])
    assert not status.exists()
    with (root / "launch.claim").open("x") as stream:
        stream.write(str(os.getpid()) + "\n")
    info = {
        "controller": {"pid": os.getpid(), "created": psutil.Process().create_time()},
        "plan": ref(plan_path),
        "CUDA_initialized": False,
        "completed_updates_per_arm": 0,
    }

    def record(state, **fields):
        info.update(status=state, updated_unix=time.time(), **fields)
        temp = status.with_suffix(".tmp")
        temp.write_text(json.dumps(info, indent=2, allow_nan=False) + "\n")
        temp.replace(status)
        print(json.dumps({"status": state, **fields}), flush=True)

    def yield_for_reviews():
        # Use at most two CPU threads during training. Give owned inference /
        # timing stages the CPU too once the original training owner exits.
        if alive(plan["training_owner"]):
            return
        waiting = False
        while True:
            active = []
            for entry in plan["review_and_timing_owners"]:
                if alive(entry["owner"]):
                    active.append(entry["owner"])
                else:
                    current = read(entry["workflow"])
                    if (
                        current["controller"] == entry["owner"]
                        and current.get("child")
                        and alive(current["child"])
                    ):
                        active.append(current["child"])
            if not active:
                break
            if not waiting:
                record("waiting-for-owned-review-and-timing-owners-no-CPU-compute", active=active)
                waiting = True
            time.sleep(15)
        if waiting:
            record("resuming-discarded-CPU-diagnosis-after-owned-reviews")

    try:
        record("loading-fixed-training-only-arrays-no-CUDA")
        fixtures = read(plan["fixtures"]["path"])
        assert len(fixtures) == 16
        batches = []
        for entry in fixtures:
            assert ref(entry["fixture"]["path"]) == entry["fixture"]
            with np.load(entry["fixture"]["path"], allow_pickle=False) as arrays:
                batch = {key: torch.from_numpy(arrays[key].copy()) for key in arrays.files}
            assert batch_fingerprint(batch) == entry["batch_fingerprint"]
            assert batch["packed"].shape == (4, 4, 128, 128)
            assert all(s.get("split", "train") == "train" for s in entry["sources"])
            batches.append(batch)
        models, optimizers, initial = {}, {}, {}
        rng_digest = None
        for mode in plan["modes"]:
            torch.manual_seed(plan["seed"])
            random.seed(plan["seed"])
            model = JointDemosaic(ModelConfig(**plan["model_config"])).cpu()
            assert not model.config.dino and len(list(model.parameters())) == 852
            models[mode] = model
            optimizers[mode] = make_optimizer(model, {"lr": plan["lr"]})
            initial[mode] = digest(model.state_dict().items())
            value = hashlib.sha256(torch.get_rng_state().numpy().tobytes()).hexdigest()
            rng_digest = value if rng_digest is None else rng_digest
            assert value == rng_digest
        assert len(set(initial.values())) == 1

        @torch.inference_mode()
        def evaluate(update):
            result = {}
            for mode, model in models.items():
                model.eval()
                rows = []
                for entry, batch in zip(fixtures, batches, strict=True):
                    yield_for_reviews()
                    with feature_mode(mode, batch):
                        prediction, loss = loss_for(model, batch, entry["domain"])
                    assert torch.isfinite(prediction).all() and torch.isfinite(loss)
                    if update == 0:
                        assert torch.equal(prediction, bilinear(batch["packed"], batch["colors"]))
                    rows.append(
                        {
                            "production_step": entry["production_step"],
                            "domain": entry["domain"],
                            "loss": loss.item(),
                            "MSE": mse(prediction, batch, entry["domain"]),
                        }
                    )
                means = {
                    domain: {
                        key: float(np.mean([r[key] for r in rows if r["domain"] == domain]))
                        for key in ["loss", "MSE"]
                    }
                    for domain in ["commons", "native", "paired"]
                }
                result[mode] = {"cases": rows, "domain_means": means}
            return {"update": update, "arms": result}

        curves = [evaluate(0)]
        (root / "curves.json").write_text(json.dumps(curves, indent=2, allow_nan=False) + "\n")
        record(
            "running-fresh-CPU-coordinate-diagnosis",
            initial_model_SHA256=initial,
            initial_RNG_sha256=rng_digest,
            all16_initial_outputs_equal_bilinear=True,
        )
        with (root / "training.jsonl").open("x") as log:
            for update in range(1, plan["updates"] + 1):
                index = (update - 1) % 16
                entry, batch = fixtures[index], batches[index]
                for mode in plan["modes"]:
                    yield_for_reviews()
                    assert psutil.virtual_memory().available > 16 * 2**30
                    model, optimizer = models[mode], optimizers[mode]
                    model.train()
                    optimizer.zero_grad(set_to_none=True)
                    with feature_mode(mode, batch):
                        _, loss = loss_for(model, batch, entry["domain"])
                    assert torch.isfinite(loss)
                    with ieee_fp32():
                        loss.backward()
                        assert all(
                            p.grad is not None and torch.isfinite(p.grad).all()
                            for p in model.parameters()
                        )
                        norm = torch.nn.utils.clip_grad_norm_(
                            model.parameters(), 1, error_if_nonfinite=True
                        )
                    optimizer.step()
                    log.write(
                        json.dumps(
                            {
                                "update": update,
                                "mode": mode,
                                "production_step": entry["production_step"],
                                "domain": entry["domain"],
                                "loss": float(loss),
                                "gradient_norm": float(norm),
                            },
                            allow_nan=False,
                        )
                        + "\n"
                    )
                info["completed_updates_per_arm"] = update
                if update % 16 == 0:
                    log.flush()
                    record(
                        "running-fresh-CPU-coordinate-diagnosis", completed_updates_per_arm=update
                    )
                if update in plan["evaluation_updates"]:
                    curves.append(evaluate(update))
                    (root / "curves.json").write_text(
                        json.dumps(curves, indent=2, allow_nan=False) + "\n"
                    )
        states = {}
        for mode, model in models.items():
            optimizer = optimizers[mode]
            assert all(torch.isfinite(v).all() for v in model.state_dict().values())
            assert len(optimizer.state) == 852
            assert all(int(v["step"]) == plan["updates"] for v in optimizer.state.values())
            assert all(
                torch.isfinite(t).all() for v in optimizer.state.values() for t in v.values()
            )
            states[mode] = {
                "final_model_SHA256": digest(model.state_dict().items()),
                "finite_model_and852_Adam_states": True,
                "Adam_steps": plan["updates"],
                "learned_weights_discarded": True,
            }
        assert all(
            batch_fingerprint(b) == f["batch_fingerprint"]
            for b, f in zip(batches, fixtures, strict=True)
        )
        guard(plan)
        result = {
            "status": "completed-discarded-fresh-CPU-feature-coordinate-comparison",
            "plan": ref(plan_path),
            "initial_model_SHA256": initial,
            "initial_RNG_sha256": rng_digest,
            "all16_initial_outputs_equal_bilinear": True,
            "curves": ref(root / "curves.json"),
            "training_log": ref(root / "training.jsonl"),
            "states": states,
            "CUDA_initialized": torch.cuda.is_initialized(),
            "scope": plan["scope"],
        }
        assert not result["CUDA_initialized"]
        (root / "receipt.json").write_text(json.dumps(result, indent=2, allow_nan=False) + "\n")
        record(result["status"], result=ref(root / "receipt.json"))
    except BaseException as error:
        record("failed-no-automatic-restart-no-learned-weights-exported", error=repr(error))
        raise


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("plan", type=Path)
    run(parser.parse_args().plan)

"""Independently rebuild fresh-trial summary statistics from saved case scores.

No model inference, production aggregation imports, photo decoding or CUDA.
This audits coverage and arithmetic; it does not validate metric definitions,
inspect restoration pixels, estimate training uncertainty or select a model.
"""

import argparse
import hashlib
import json
import math
from collections import defaultdict
from pathlib import Path

import numpy as np

from demosaic.safety import writable_path

BASE = Path("/mnt/external/demosaic")
CLASSICAL = {"Bilinear", "Malvar2004:WB", "Wiener7+Malvar2004:WB"}
TOLERANCE = 2e-10


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def load_rows(path):
    with Path(path).open() as stream:
        return [json.loads(line) for line in stream]


def average(values):
    valid = [value for value in values if value is not None]
    return math.fsum(valid) / len(valid) if valid else None


def group_means(rows, fields):
    groups = defaultdict(list)
    for row in rows:
        groups[tuple(row[field] for field in fields)].append(row["metrics"])
    return {
        key: {name: average([row[name] for row in values]) for name in values[0]}
        for key, values in groups.items()
    }


def validate_rows(rows, expected, core_metrics, nullable_metrics):
    actual = set()
    missing_values = defaultdict(int)
    supports = {}
    for row in rows:
        key = (row["model"], row["kind"], row["id"], row["condition"], row["pattern"])
        require(key not in actual, f"Duplicate observation: {key}")
        actual.add(key)
        require(set(row["metrics"]) == core_metrics | nullable_metrics, "Metric names changed")
        support = {name for name, value in row["metrics"].items() if value is not None}
        observation = key[1:]
        require(
            supports.setdefault(observation, support) == support,
            f"Metric validity differs between methods: {observation}",
        )
        for name, value in row["metrics"].items():
            if value is None:
                require(name in nullable_metrics, f"Missing core metric: {key} {name}")
                missing_values[name] += 1
            else:
                require(
                    isinstance(value, (float, int)) and math.isfinite(value),
                    f"Nonfinite/non-numeric metric: {key} {name}",
                )
    require(
        actual == expected,
        f"Observation coverage mismatch: missing={len(expected - actual)}, extra={len(actual - expected)}",
    )
    return dict(missing_values)


def compare_summary(rows, summary):
    errors = []

    def close(actual, expected, label):
        if actual is None or expected is None:
            require(actual is expected, f"Missing-value mismatch: {label}")
            return
        error = abs(actual - expected)
        require(math.isfinite(actual) and error <= TOLERANCE, f"Summary mismatch: {label}: {error}")
        errors.append(error)

    def check_means(records, fields, source_rows):
        expected = group_means(source_rows, fields)
        partition = defaultdict(list)
        for row in source_rows:
            partition[tuple(row[field] for field in fields)].append(row)
        actual = {tuple(row[field] for field in fields): row for row in records}
        require(
            len(actual) == len(records) and actual.keys() == expected.keys(), "Summary keys differ"
        )
        for key, means in expected.items():
            require(actual[key]["metrics"].keys() == means.keys(), "Summary metric names differ")
            matching = partition[key]
            for name, value in means.items():
                metric = actual[key]["metrics"][name]
                require(
                    metric["count"] == sum(row["metrics"][name] is not None for row in matching),
                    f"Summary count mismatch: {key} {name}",
                )
                close(metric["mean"], value, (key, name))

    check_means(summary["groups"], ["model", "kind", "condition", "pattern"], rows)
    source = group_means(rows, ["model", "kind", "id"])
    source_rows = [
        {"model": key[0], "kind": key[1], "id": key[2], "metrics": metrics}
        for key, metrics in source.items()
    ]
    check_means(summary["overall"], ["model", "kind"], source_rows)
    comparisons = summary["paired_comparisons"]
    keys = {(row["first"], row["second"], row["kind"], row["metric"]) for row in comparisons}
    require(len(keys) == len(comparisons), "Duplicate paired comparison")
    names = {row["metric"] for row in comparisons}
    methods = sorted({row["model"] for row in source_rows})
    kinds = sorted({row["kind"] for row in source_rows})
    expected_keys = {
        (a, b, kind, name)
        for i, a in enumerate(methods)
        for b in methods[i + 1 :]
        for kind in kinds
        for name in names
    }
    require(keys == expected_keys, "Missing paired comparisons")
    for row in comparisons:
        first, second, kind, metric = (row[key] for key in ["first", "second", "kind", "metric"])
        identities = sorted(
            key[2]
            for key in source
            if key[:2] == (first, kind)
            and source[key][metric] is not None
            and source[second, kind, key[2]][metric] is not None
        )
        delta = np.array(
            [
                source[first, kind, key][metric] - source[second, kind, key][metric]
                for key in identities
            ]
        )
        require(row["sources"] == len(delta), "Paired comparison source count differs")
        close(
            row["mean_first_minus_second"], average(delta.tolist()), (first, second, kind, metric)
        )
        # Reproduce the declared 1000 resamples/seed42 percentile procedure.
        indices = np.random.default_rng(42).integers(len(delta), size=(1000, len(delta)))
        interval = np.quantile(delta[indices].mean(axis=1), [0.025, 0.975])
        require(len(row["source_bootstrap_95_interval"]) == 2, "Invalid bootstrap interval length")
        for actual, expected in zip(row["source_bootstrap_95_interval"], interval):
            close(actual, float(expected), (first, second, kind, metric, "interval"))
    return {
        "group_rows": len(summary["groups"]),
        "overall_rows": len(summary["overall"]),
        "paired_comparisons": len(comparisons),
        "max_absolute_arithmetic_difference": max(errors),
    }


def audit_photo(root, expected_methods=8):
    summary = json.loads((root / "summary.json").read_text())
    require(sha(summary["manifest"]) == summary["manifest_sha256"], "Photo manifest hash changed")
    manifest = load_rows(summary["manifest"])
    ids = {row["id"] for row in manifest if row["split"] == "val"}
    require(len(ids) == summary["sources"] == 427, "Expected 427 validation photos")
    require(summary["synthetic_sources"] == 16, "Expected 16 procedural sources")
    labels = [row["label"] for row in summary["models"]]
    methods = CLASSICAL | set(labels)
    require(
        len(labels) == len(set(labels)) == expected_methods - len(CLASSICAL)
        and len(methods) == expected_methods,
        f"Expected {expected_methods} photo methods",
    )
    conditions = {row["name"] for row in summary["protocol"]["conditions"]}
    patterns = set(summary["protocol"]["patterns"])
    require(
        len(conditions) == 7 and patterns == {"RGGB", "BGGR", "GRBG", "GBRG"}, "Photo grid changed"
    )
    expected = {
        (method, kind, identity, condition, pattern)
        for kind, sources in [("photo", ids), ("synthetic", {f"synthetic-{i}" for i in range(16)})]
        for identity in sources
        for method in methods
        for condition in conditions
        for pattern in patterns
    }
    rows = load_rows(root / "per-image.jsonl")
    nulls = validate_rows(
        rows,
        expected,
        {"linear_psnr", "srgb_psnr", "srgb_ssim", "chroma_mae", "gradient_mae"},
        {"highlight_boundary_chroma_mae", "highlight_boundary_rgb_mae", "shadow_linear_psnr"},
    )
    require(
        {row["metric"] for row in summary["paired_comparisons"]}
        == {"linear_psnr", "srgb_psnr", "srgb_ssim"},
        "Photo comparison metrics changed",
    )
    return {
        "cases": len(rows),
        "sources": 443,
        "methods": expected_methods,
        "nullable_metric_cases": nulls,
        **compare_summary(rows, summary),
    }


def audit_real(root, scenes, pairs, crops, expected_methods=8, *, require_rawnind=True):
    summary = json.loads((root / "summary.json").read_text())
    require(
        sha(summary["prepared_manifest"]) == summary["prepared_sha256"], "Prepared manifest changed"
    )
    prepared = json.loads(Path(summary["prepared_manifest"]).read_text())
    require(
        summary["scenes"] == scenes and summary["pairs"] == pairs, "Real scene/pair counts changed"
    )
    # Real reports retain one publisher-weight receipt for two gain adapters.
    labels = {row["label"] for row in summary["models"]}
    if require_rawnind:
        require("RawNIND" in labels, "Missing RawNIND publisher receipt")
    methods = (
        CLASSICAL
        | (labels - {"RawNIND"})
        | (
            {"RawNIND:cfa-ls:publisher", "RawNIND:cfa-channel:publisher"}
            if "RawNIND" in labels
            else set()
        )
    )
    require(len(methods) == expected_methods, f"Expected {expected_methods} real methods")
    expected = {
        (method, "real", crop["id"], case["noisy"]["sha256"], case["metadata"]["pattern"])
        for case in prepared["cases"]
        for crop in case["crops"]
        for method in methods
    }
    require(len(expected) == crops * expected_methods, "Real crop count changed")
    original = load_rows(root / "per-crop.jsonl")
    tile_scene = {crop["id"]: case["scene"] for case in prepared["cases"] for crop in case["crops"]}
    for row in original:
        require(row["scene"] == tile_scene.get(row["tile_id"]), "Crop scene changed")
    normalized = [
        {**row, "kind": "real", "id": row["tile_id"], "condition": row["pair"]} for row in original
    ]
    validate_rows(
        normalized,
        expected,
        {
            "sensor_psnr",
            "reference_samples",
            "ahd_srgb_psnr",
            "ahd_srgb_ssim",
            "ahd_chroma_mae",
            "ahd_gradient_mae",
        },
        set(),
    )
    capture = group_means(original, ["model", "scene", "pair", "pattern"])
    capture_rows = [
        {
            "model": key[0],
            "id": key[1],
            "condition": key[2],
            "pattern": key[3],
            "kind": "real",
            "metrics": scores,
        }
        for key, scores in capture.items()
    ]
    actual_pairs = {
        (row["model"], row["id"], row["condition"], row["pattern"]): row["metrics"]
        for row in summary["per_pair"]
    }
    require(
        len(actual_pairs) == len(summary["per_pair"]) == len(capture), "Capture records changed"
    )
    for key, scores in capture.items():
        require(
            key in actual_pairs and scores.keys() == actual_pairs[key].keys(),
            "Capture keys changed",
        )
        require(
            all(
                abs(value - actual_pairs[key][name]) <= TOLERANCE for name, value in scores.items()
            ),
            "Saved capture mean differs from crop means",
        )
    require(
        {row["metric"] for row in summary["paired_comparisons"]}
        == {"sensor_psnr", "ahd_srgb_psnr", "ahd_srgb_ssim"},
        "Real comparison metrics changed",
    )
    return {
        "cases": len(original),
        "scenes": scenes,
        "pairs": pairs,
        "crops_per_method": crops,
        "methods": expected_methods,
        **compare_summary(capture_rows, summary),
    }


def main(steps, output, trial="fresh"):
    if trial == "convnext-v58":
        require(steps in [1000, 10000], "ConvNeXt audits support the evaluated1000/10000 gates")
        suffix = "1k" if steps == 1000 else "10k"
        workflow = BASE / (
            "runs/dino-convnext-pyramid-v58-workflow.json"
            if steps == 1000
            else "runs/dino-convnext-pyramid-v58-10k-workflow.json"
        )
        expected_status = (
            "completed-first1000-and-evaluation-awaiting-manual-review"
            if steps == 1000
            else "completed-to10000-and-evaluation-awaiting-manual-review"
        )
        expected_methods = 9
        directories = [
            ("photo", f"synthetic-convnext-v58-fresh-{suffix}-full427"),
            ("known", f"paired-known-convnext-v58-fresh-{suffix}"),
            ("unseen", f"paired-unseen-convnext-v58-fresh-{suffix}"),
        ]
    else:
        require(steps in [3000, 10000], "Original fresh audits support3000/10000")
        suffix = {3000: "3k", 10000: "10k"}[steps]
        workflow = BASE / f"runs/fresh-dino-capacity-{suffix}-workflow.json"
        expected_status = f"completed-to{steps}-and-full-review"
        expected_methods = 8
        directories = [
            ("photo", f"synthetic-fresh-dino-capacity-{suffix}-full427"),
            ("known", f"paired-known-fresh-dino-capacity-{suffix}"),
            ("unseen", f"paired-unseen-fresh-dino-capacity-{suffix}"),
        ]
    state = json.loads(workflow.read_text())
    require(
        state["status"] == expected_status,
        "Workflow is not complete; inspect/wait, do not restart",
    )
    output = writable_path(output)
    require(not output.exists(), "Audit output already exists")
    results, inputs = {}, {}
    for name, directory in directories:
        root = BASE / "evaluation" / directory
        results[name] = (
            audit_photo(root, expected_methods)
            if name == "photo"
            else audit_real(
                root,
                *({"known": (4, 8, 72), "unseen": (5, 10, 90)}[name]),
                expected_methods=expected_methods,
            )
        )
        inputs[name] = {
            path.name: sha(path) for path in [root / "summary.json", *root.glob("*.jsonl")]
        }
    receipt = {
        "scope": "Independent saved-score coverage and arithmetic audit only; no inference, pixel/GT-definition validation, speed result, training-repeat uncertainty or model selection.",
        "steps": steps,
        "trial": trial,
        "workflow": str(workflow),
        "workflow_sha256": sha(workflow),
        "results": results,
        "inputs": inputs,
        "driver_sha256": sha(__file__),
        "production_aggregation_imported": False,
        "resampling": "1000 paired source/scene bootstrap resamples, seed42, percentile95 interval; matches current declared procedure.",
    }
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(json.dumps(receipt, indent=2, allow_nan=False) + "\n")
    print(json.dumps({"output": str(output), "results": results}))


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--steps", type=int, choices=[1000, 3000, 10000], required=True)
    parser.add_argument("--trial", choices=["fresh", "convnext-v58"], default="fresh")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    main(args.steps, args.output, args.trial)

"""Observe a frozen late RGB head and reuse its actual trunk/DINO inputs.

These are diagnostic counterfactuals of jointly trained checkpoints, never
models trained without the head. Physical inverse replay must match the
actual complete forward exactly before any component output is used.
"""

from unittest.mock import patch

import torch

import demosaic.pretrained_rgb as rgb_module
from demosaic.precision import ieee_fp32

INPUTS = ("packed", "variance", "colors", "wb", "matrix")


def compatible(model):
    rgb = model.pretrained_rgb
    if (
        model.training
        or rgb.processing_scale != 1
        or any(
            value is not None for value in [rgb.raw_kernel, rgb.raw_directional, rgb.raw_spectral]
        )
        or rgb.adc_projection
    ):
        raise ValueError("Component replay requires an eval full-resolution RGB-only checkpoint")
    return rgb


def inverse_tail(rgb, normalized, offset, span):
    """Replay only the actual final physical operations, with no target input."""
    with torch.autocast(normalized.device.type, enabled=False), ieee_fp32():
        value = normalized.float() * span + offset
        profiles = rgb._noise_profiles
        if profiles is not None:
            if len(profiles) not in (1, len(value)):
                raise ValueError("Noise profiles do not match the captured image batch")
            profiles = profiles * len(value) if len(profiles) == 1 else profiles
            value = torch.cat(
                [
                    transform.inverse(value[b : b + 1])
                    if transform is not None
                    else (value[b : b + 1].double() * scale).float()
                    for b, (transform, scale, _stochastic) in enumerate(profiles)
                ]
            )
        return value


def capture_forward(model, arguments):
    """Non-modifying hooks capture one full forward; remove them on every exit."""
    if set(arguments) != set(INPUTS):
        raise ValueError("Forward arguments must be exactly the five measurement/camera fields")
    rgb = compatible(model)
    if rgb.rgb_refinement is None:
        return model(*(arguments[k] for k in INPUTS)), None
    capture = {"physical_calls": 0, "head_calls": 0}
    original = rgb_module.physical_rgb_features

    def physical(*args, **kwargs):
        result = original(*args, **kwargs)
        capture["physical_calls"] += 1
        capture["offset"], capture["span"] = result[-2:]
        return result

    def before(_module, args):
        capture["head_arguments"] = args

    def after(_module, _args, output):
        capture["head_calls"] += 1
        capture["normalized_output"] = output

    handles = [
        rgb.rgb_refinement.register_forward_pre_hook(before),
        rgb.rgb_refinement.register_forward_hook(after),
    ]
    try:
        with patch.object(rgb_module, "physical_rgb_features", physical):
            output = model(*(arguments[k] for k in INPUTS))
    finally:
        for handle in handles:
            handle.remove()
    assert capture["physical_calls"] == capture["head_calls"] == 1
    reconstructed = inverse_tail(
        rgb, capture["normalized_output"], capture["offset"], capture["span"]
    )
    if not torch.equal(output, reconstructed):
        raise RuntimeError(
            "Captured physical tail does not replay the actual full RGB output exactly"
        )
    return output, capture


def component_outputs(model, full, capture):
    """Reuse captured inputs; no restoration-trunk or DINO invocation here."""
    rgb = compatible(model)
    if capture is None:
        assert rgb.rgb_refinement is None
        return {"full": full}
    head = rgb.rgb_refinement
    args = capture["head_arguments"]
    replay = head(*args)
    if not torch.equal(replay, capture["normalized_output"]):
        raise RuntimeError("Direct head replay differs from the actual captured head")
    with patch.object(head, "mode", "global"):
        pooled = head(*args)
    result = {
        "full": full,
        "bypass": inverse_tail(rgb, args[0], capture["offset"], capture["span"]),
    }
    if head.mode == "global":
        if not torch.equal(pooled, replay):
            raise RuntimeError("Pooling an already global head is not an exact identity")
    else:
        assert head.mode == "spatial"
        result["pooled"] = inverse_tail(rgb, pooled, capture["offset"], capture["span"])
    return result

"""CPU-only dependency proof for V178 GPU work; absence alone is not success."""

import hashlib
import json
from pathlib import Path

import psutil


def read(path):
    return json.loads(Path(path).read_text())


def ref(path):
    path = Path(path).absolute()
    with path.open("rb") as stream:
        digest = hashlib.file_digest(stream, "sha256").hexdigest()
    return {"path": str(path), "sha256": digest}


def owner_live(owner):
    """Transient/permission errors propagate, never turning an owner terminal."""
    try:
        process = psutil.Process(owner["pid"])
        return process.create_time() == owner["created"] and process.status() not in (
            psutil.STATUS_ZOMBIE,
            psutil.STATUS_DEAD,
        )
    except psutil.NoSuchProcess:
        return False


def dependency_readiness(root, *, is_live=owner_live):
    """Require terminal train/review/watch owners and the completed pipeline."""
    root = Path(root)
    for name in [
        "train-failure-v1.json",
        "review-failure-v1.json",
        "completion-watch-failure-v1.json",
    ]:
        if (root / name).exists():
            raise RuntimeError(f"Preserved dependency failure requires inspection: {root / name}")
    bindings, owners = [], {}
    phases = [
        ("train", "train-result-v1.json"),
        ("review", "scores-v1.json"),
        ("completion-watch", "completion-watch-result-v1.json"),
    ]
    for phase, result_name in phases:
        launch_path = root / f"{phase}-launch-v1.json"
        if not launch_path.exists():
            return {"ready": False, "reason": f"waiting-for-{phase}-launch"}
        launch = read(launch_path)
        owner = launch["owner"]
        owners[phase] = owner
        if is_live(owner):
            return {"ready": False, "reason": f"waiting-for-{phase}-owner", "owner": owner}
        result_path = root / result_name
        if not result_path.exists():
            return {
                "ready": False,
                "reason": f"waiting-for-{phase}-completed-result",
                "owner": owner,
            }
        result = read(result_path)
        if result.get("owner") != owner or not result.get("status", "").startswith("completed"):
            raise RuntimeError(f"Dependency result does not prove {phase} success: {result_path}")
        bindings.extend([ref(launch_path), ref(result_path)])
    status_path = root / "completion-watch-status-v1.json"
    status = read(status_path)
    if (
        status["owner"] != owners["completion-watch"]
        or status["status"] != "ready-for-actual-native-viewing"
    ):
        raise RuntimeError("Completion watcher did not reach its final native-viewing state")
    for name in [
        "training-audit-v1.json",
        "quality-audit-v1.json",
        "offset-audit-v1.json",
        "paired-comparisons-v1.json",
        "figures-v1.json",
    ]:
        path = root / name
        if not path.exists():
            raise RuntimeError(f"Completed dependency is missing required output: {path}")
        value = read(path)
        if not value.get("status", "").startswith(("pass", "completed", "rendered")):
            raise RuntimeError(f"Dependency output lacks completed status: {path}")
        bindings.append(ref(path))
    bindings.append(ref(status_path))
    return {
        "ready": True,
        "reason": "all-V175-owners-terminal-completed-audits-review-render",
        "owners": owners,
        "bindings": bindings,
        "scope": "Ready for separate GPU admission;V175 human viewing/report/publication may remain.",
    }

"""Run the frozen precision candidate only after exact quality-work exits.

The waiting controller imports no Torch/Triton/CUDA. The separate worker keeps
its own dependency/accuracy guards. One launch only; no retry or promotion.
"""

import argparse
import hashlib
import json
import os
import shutil
import subprocess
import time
from pathlib import Path

import psutil


def read(path):
    return json.loads(Path(path).read_text())


def ref(path):
    path = Path(path).resolve()
    with path.open('rb') as stream:
        digest = hashlib.file_digest(stream, 'sha256').hexdigest()
    return {'path': str(path), 'sha256': digest}


def alive(owner):
    try:
        process = psutil.Process(owner['pid'])
        return process.create_time() == owner['created'] and process.status() != psutil.STATUS_ZOMBIE
    except psutil.NoSuchProcess:
        return False


def dependencies_ready(gpu):
    """Detect failed work immediately; require successful exact terminal owners."""
    live = any(alive(owner) for owner in gpu['blocking_owners'])
    for dependency in gpu['completed_dependencies']:
        state = read(dependency['path'])
        if state['controller'] != dependency['controller'] or state['plan'] != dependency['plan']:
            raise ValueError('Dependency owner/plan identity changed')
        if ref(state['plan']['path']) != state['plan']:
            raise ValueError('Dependency plan bytes changed')
        if state['status'].startswith('failed-'):
            raise RuntimeError('Quality dependency failed; no GPU launch or automatic retry')
        if not live and state['status'] != dependency['status']:
            raise RuntimeError('Exited quality owner lacks successful terminal state')
        if not live and state.get('child') and alive(state['child']):
            raise RuntimeError('Dependency child remains live')
    if live:
        return False
    for dependency in gpu.get('required_completed_receipts', []):
        if read(dependency['path'])['status'] != dependency['status']:
            raise RuntimeError('Retained-reference preparation did not complete')
    return True


def guard(plan):
    for item in [plan['controller'], plan['GPU_plan'], *read(plan['GPU_plan']['path'])['inputs']]:
        if ref(item['path']) != item:
            raise ValueError('Frozen precision-candidate input changed: ' + item['path'])


def resource_ready(plan):
    return (
        psutil.virtual_memory().available >= plan['launch_available_gib'] * 2**30
        and shutil.disk_usage(plan['root']).free >= plan['root_reserve_gib'] * 2**30
        and shutil.disk_usage('/mnt/external').free >= plan['external_reserve_gib'] * 2**30
    )


def stop_owned(process, owner):
    """Signal only the exact child started here, then reap it."""
    if alive(owner):
        process.terminate()
    try:
        process.wait(timeout=10)
    except subprocess.TimeoutExpired:
        if alive(owner):
            process.kill()
        process.wait(timeout=10)


def main(plan_path):
    os.nice(10)
    plan_path = Path(plan_path).resolve()
    plan = read(plan_path)
    root = Path(plan['root'])
    if ref(__file__) != plan['controller']:
        raise ValueError('Frozen controller changed')
    guard(plan)
    gpu = read(plan['GPU_plan']['path'])
    if Path(gpu['output']).exists():
        raise ValueError('GPU output already exists; choose a separately reviewed recovery')
    with (root / 'controller.claim').open('x') as stream:
        stream.write(str(os.getpid()))
    status_path = root / 'status.json'
    owner = {'pid': os.getpid(), 'created': psutil.Process().create_time()}
    info = {'controller': owner, 'plan': ref(plan_path), 'GPU_plan': plan['GPU_plan']}

    def record(status, **fields):
        info.update(status=status, updated_unix=time.time(), **fields)
        temporary = status_path.with_suffix('.tmp')
        temporary.write_text(json.dumps(info, indent=2, allow_nan=False) + '\n')
        temporary.replace(status_path)

    record('waiting-for-exact-training-review-closure-and-reference-exits-no-Torch-or-CUDA')
    try:
        started = time.monotonic()
        while not dependencies_ready(gpu):
            if time.monotonic() - started > plan['dependency_timeout_seconds']:
                raise TimeoutError('Quality dependency wait expired; no automatic retry')
            time.sleep(plan['poll_seconds'])
        guard(plan)
        record('waiting-for-stable-memory-and-disk-no-Torch-or-CUDA')
        started, stable = time.monotonic(), None
        while True:
            now = time.monotonic()
            if now - started > plan['resource_timeout_seconds']:
                raise TimeoutError('Resource wait expired; no automatic retry')
            if resource_ready(plan):
                stable = now if stable is None else stable
                if now - stable >= plan['stable_seconds']:
                    break
            else:
                stable = None
            time.sleep(plan['poll_seconds'])
        assert dependencies_ready(gpu)
        guard(plan)
        env = dict(os.environ, **plan['worker_env'])
        with (root / 'GPU-worker.log').open('xb') as log:
            process = subprocess.Popen(
                [gpu['python'], '-P', gpu['worker']['path'], plan['GPU_plan']['path']],
                cwd=gpu['work'], env=env, stdin=subprocess.DEVNULL,
                stdout=log, stderr=subprocess.STDOUT, start_new_session=True,
            )
            child = {'pid': process.pid, 'created': psutil.Process(process.pid).create_time()}
            record('running-frozen-CUDA-array-gates-then-conditional-resident-timing', child=child)
            started = time.monotonic()
            try:
                while process.poll() is None:
                    if time.monotonic() - started > plan['worker_timeout_seconds']:
                        raise TimeoutError('CUDA preflight runtime bound exceeded')
                    if psutil.virtual_memory().available < plan['active_available_gib'] * 2**30:
                        raise MemoryError('Shared available-memory guard reached')
                    if shutil.disk_usage('/mnt/external').free < plan['external_reserve_gib'] * 2**30:
                        raise OSError('External disk reserve reached')
                    time.sleep(2)
            except BaseException:
                stop_owned(process, child)
                raise
            if process.returncode != 0 or alive(child):
                raise RuntimeError('Frozen GPU worker failed; no automatic retry')
        guard(plan)
        terminal = read(Path(gpu['output']) / 'status.json')
        if terminal['owner'] != child:
            raise ValueError('GPU terminal owner differs from exact launched child')
        if terminal['status'] == 'rejected-CUDA-RGB-accuracy-no-timing-or-fullframe':
            record('rejected-CUDA-array-gate-no-timing-or-fullframe-awaiting-native-inspection',
                   GPU_terminal=ref(Path(gpu['output']) / 'status.json'))
            return
        expected = 'completed-isolated-TF32x3-CUDA-array-gates-and-resident-timing-awaiting-native-review'
        if terminal['status'] != expected or ref(terminal['receipt']['path']) != terminal['receipt']:
            raise ValueError('GPU worker has no verified completed receipt')
        result = read(terminal['receipt']['path'])
        if result['plan'] != plan['GPU_plan'] or result['owner'] != child:
            raise ValueError('Completed precision-candidate lineage changed')
        record('completed-CUDA-numerics-and-resident-timing-awaiting-independent-array-and-native-review',
               GPU_receipt=terminal['receipt'])
    except BaseException as error:
        record('failed-precision-candidate-queue-no-automatic-retry', error=repr(error))
        raise


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('plan', type=Path)
    main(parser.parse_args().plan)

