class DisabledFrequencyFeature(ast.NodeTransformer):
    """Specialize only the added, disabled RAW-frequency feature to False/None."""

    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Load) and node.id == "raw_frequency_features":
            return ast.copy_location(ast.Constant(False), node)
        return node

    def visit_Attribute(self, node):
        if isinstance(node.ctx, ast.Load):
            if node.attr == "raw_frequency_features":
                return ast.copy_location(ast.Constant(False), node)
            if node.attr == "raw_frequency":
                return ast.copy_location(ast.Constant(None), node)
        return self.generic_visit(node)

    def visit_AnnAssign(self, node):
        if isinstance(node.target, ast.Name) and node.target.id == "raw_frequency_features":
            if not isinstance(node.value, ast.Constant) or node.value.value is not False:
                raise ValueError("RAW-frequency default must remain disabled")
            return None
        return self.generic_visit(node)

    def visit_Assign(self, node):
        if (
            len(node.targets) == 1
            and isinstance(node.targets[0], ast.Attribute)
            and node.targets[0].attr == "raw_frequency"
        ):
            if not isinstance(node.value, ast.Constant) or node.value.value is not None:
                raise ValueError("Disabled RAW-frequency state must initialize to None")
            return None
        return self.generic_visit(node)

    def visit_arguments(self, node):
        keep, defaults = [], []
        for arg, default in zip(node.kwonlyargs, node.kw_defaults, strict=True):
            if arg.arg == "raw_frequency_features":
                if not isinstance(default, ast.Constant) or default.value is not False:
                    raise ValueError("RAW-frequency constructor default must be False")
            else:
                keep.append(arg)
                defaults.append(default)
        node.kwonlyargs, node.kw_defaults = keep, defaults
        return self.generic_visit(node)

    def visit_Call(self, node):
        node.keywords = [kw for kw in node.keywords if kw.arg != "raw_frequency_features"]
        node = self.generic_visit(node)
        if (
            isinstance(node.func, ast.Name)
            and node.func.id == "type"
            and len(node.args) == 1
            and isinstance(node.args[0], ast.Constant)
            and type(node.args[0].value) is bool
        ):
            return ast.copy_location(ast.Name(id="bool", ctx=ast.Load()), node)
        return node

    def visit_Compare(self, node):
        node = self.generic_visit(node)
        if len(node.ops) != 1 or not isinstance(node.ops[0], (ast.Is, ast.IsNot)):
            return node
        left, right = node.left, node.comparators[0]
        equal = None
        if isinstance(left, ast.Constant) and isinstance(right, ast.Constant):
            equal = left.value is right.value
        elif (
            isinstance(left, ast.Name)
            and isinstance(right, ast.Name)
            and left.id == right.id == "bool"
        ):
            equal = True
        if equal is None:
            return node
        return ast.copy_location(
            ast.Constant(equal if isinstance(node.ops[0], ast.Is) else not equal), node
        )

    def visit_BoolOp(self, node):
        node = self.generic_visit(node)
        neutral = isinstance(node.op, ast.And)
        values = []
        for value in node.values:
            if isinstance(value, ast.Constant) and type(value.value) is bool:
                if value.value is not neutral:
                    return value
            else:
                values.append(value)
        return (
            values[0]
            if len(values) == 1
            else ast.BoolOp(op=node.op, values=values)
            if values
            else ast.Constant(neutral)
        )

    def visit_If(self, node):
        node.test = self.visit(node.test)
        if isinstance(node.test, ast.Constant) and type(node.test.value) is bool:
            return [self.visit(n) for n in (node.body if node.test.value else node.orelse)]
        return self.generic_visit(node)


def specialized_source(source):
    tree = DisabledFrequencyFeature().visit(ast.parse(source))
    return ast.dump(tree, include_attributes=False)


def inference_compatibility(original_work, quality_work):
    training_only = {"train.py", "source_loss.py", "data.py", "raw_clean.py", "conditional_bias.py"}
    result = []
    for original in (original_work / "src/demosaic").glob("*.py"):
        if original.name in training_only:
            continue
        current = quality_work / "src/demosaic" / original.name
        if not current.exists():
            raise ValueError("An original inference source is missing")
        if original.read_bytes() == current.read_bytes():
            continue
        if original.name not in {"model.py", "pretrained_rgb.py"}:
            raise ValueError(f"Conditional inference source changed: {original.name}")
        before, after = (
            specialized_source(original.read_text()),
            specialized_source(current.read_text()),
        )
        if before != after:
            raise ValueError(f"Active inference mathematics changed: {original.name}")
        result.append(
            {
                "original": ref(original),
                "current": ref(current),
                "disabled_frequency_specialized_AST_sha256": hashlib.sha256(
                    before.encode()
                ).hexdigest(),
            }
        )
    return result


def dependency_ready(state, dependency, *, is_live=live):
    if (
        state["owner"] != dependency["owner"]
        or state[dependency["plan_field"]] != dependency["plan"]
    ):
        raise ValueError("Conditional-response dependency identity changed")
    if state["status"].startswith("failed"):
        raise RuntimeError("Dependency failed; preserve its existing work")
    if is_live(dependency["owner"]):
        return False
    if state["status"] != dependency["terminal"]:
        raise RuntimeError("Dependency owner exited before successful completion")
    if state.get("child") and is_live(state["child"]):
        raise RuntimeError("Dependency still has a live child")
    return True


def dependency(path, plan_field, terminal):
    plan = read(path)
    status_path = Path(plan["root"]) / "status.json"
    state = read(status_path)
    result = {
        "status": str(status_path),
        "plan": ref(path),
        "plan_field": plan_field,
        "owner": state["owner"],
        "terminal": terminal,
    }
    dependency_ready(state, result)
    return result


def completed_methods(evaluation, photo, arms):
    if not arms or len(arms) != len(set(arms)):
        raise ValueError("Declare distinct new endpoint labels")
    checkpoints = {row["arm"]: row for row in evaluation["checkpoints"]}
    invariants = {row["checkpoint"]["arm"]: row for row in photo["invariants"]}
    if len(checkpoints) != len(evaluation["checkpoints"]) or len(invariants) != len(
        photo["invariants"]
    ):
        raise ValueError("Duplicate full-quality checkpoint or execution records")
    if not set(arms) <= checkpoints.keys() or set(invariants) != checkpoints.keys():
        raise ValueError("Completed quality endpoints do not cover the requested models")
    result = []
    for arm in arms:
        checkpoint, invariant = checkpoints[arm], invariants[arm]
        if (
            invariant["checkpoint"] != checkpoint
            or checkpoint["expected_lineage"]["step"] != 20000
            or invariant["calls"] != 3108
            or invariant["encoder_calls"] != 3108
            or invariant["observations"] != 12404
        ):
            raise ValueError("Require the completed full endpoint and original photo execution")
        result.append(
            {
                "label": arm,
                "checkpoint": {k: checkpoint[k] for k in ("path", "sha256")},
                "expected_lineage": checkpoint["expected_lineage"],
                "expected_backbone": checkpoint["expected_backbone"],
                "expected_full_model_sha256": invariant["before"],
            }
        )
    if len({m["checkpoint"]["sha256"] for m in result}) != len(result):
        raise ValueError("New endpoint checkpoint identities must be distinct")
    return result


def prepare(root, quality_path, mesh_path, source, arms=None):
    if os.environ.get("CUDA_VISIBLE_DEVICES") != "" or "torch" in sys.modules:
        raise RuntimeError("Queue preparation is CPU-only and cannot import Torch")
    root, source = root.resolve(), source.resolve()
    if not root.is_relative_to(REPO / ".cache"):
        raise ValueError("Conditional-response outputs belong in the repository cache")
    quality, mesh = read(quality_path), read(mesh_path)
    guard(quality)
    guard(mesh)
    if mesh["model_source_quality_plan"] != ref(quality_path):
        raise ValueError("Mesh and quality sources refer to different endpoints")
    arms = list(arms if arms is not None else mesh["new_arms"])
    if not arms or len(set(arms)) != len(arms) or not set(arms) <= set(mesh["new_arms"]):
        raise ValueError("New endpoint labels must come from the matched review")
    dependencies = [
        dependency(mesh_path, "plan", MESH_TERMINAL),
        dependency(quality_path, "queue_plan", QUALITY_TERMINAL),
    ]
    original = read(source / "plan-v1.json")
    guard(original)
    preparation = read(source / "input-preparation-v1.json")
    collection = read(source / "collection-v1.json")
    original_binding = ref(source / "plan-v1.json")
    if preparation["plan"] != original_binding or collection["plan"] != original_binding:
        raise ValueError("Retained observations and controls have different provenance")
    count = validate_observations(original["cases"], original["observations"])
    if count != 128 or collection["alignment"]["records"] != 256:
        raise ValueError("Expected the established four-target conditional-noise panel")
    compatibility = inference_compatibility(Path(original["work"]), Path(quality["work"]))
    if preparation["variance_values_independently_checked"] != 8388608:
        raise ValueError("Original independent input-variance proof is missing")
    exact_cases = [
        c["id"]
        for c in original["cases"]
        if c["reference_role"].startswith("Exact synthetic target")
    ]
    if len(exact_cases) != 2:
        raise ValueError("The conditional panel must retain its two exact synthetic targets")
    controls = original["methods"]
    if (
        collection["new_root_forwards"] != 256
        or [r["method"] for r in collection["methods"]] != controls
    ):
        raise ValueError("Retained controls do not match their original completed execution")
    if set(arms) & {m["label"] for m in controls}:
        raise ValueError("Already evaluated controls cannot be scheduled as new endpoints")
    inputs = [
        ref(quality_path),
        ref(mesh_path),
        original_binding,
        ref(source / "input-preparation-v1.json"),
        ref(source / "collection-v1.json"),
        ref(source / "analysis-v1.json"),
        collection["archive"],
    ]
    inputs += [o["arrays"] for o in original["observations"]]
    inputs += [c["target"] for c in original["cases"]]
    inputs += [binding for pair in compatibility for binding in (pair["original"], pair["current"])]
    for line in checked(collection["archive"]).read_text().splitlines():
        record = json.loads(line)
        inputs.extend((record["prediction"], record["supervision"]))
    root.mkdir(parents=True, exist_ok=False)
    work = root / "work"
    for path in (Path(quality["work"]) / "src/demosaic").glob("*.py"):
        target = work / "src/demosaic" / path.name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(path, target)
        inputs.append(ref(path))
    helper = work / "src/demosaic/conditional_bias.py"
    if not helper.exists():
        shutil.copyfile(REPO / "src/demosaic/conditional_bias.py", helper)
    for name in (
        "queue_conditional_noise_response.py",
        "report_conditional_noise_response.py",
        "train_directional_bank_trial.py",
        "train_v43_quality_trial.py",
        "profile_raw_kernel_inference.py",
        "frozen_backbone_identity.py",
    ):
        target = work / "scripts" / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(REPO / "scripts" / name, target)
    for name in (
        "third_party/dinov3/LICENSE.md",
        "third_party/gaussian/Noise2VST-LICENSE",
        "third_party/gaussian/KAIR-LICENSE",
    ):
        target = work / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(REPO / name, target)
    plan = {
        "root": str(root),
        "work": str(work),
        "python": sys.executable,
        "controller_source": ref(work / "scripts/queue_conditional_noise_response.py"),
        "report_source": ref(work / "scripts/report_conditional_noise_response.py"),
        "quality_plan": ref(quality_path),
        "dependencies": dependencies,
        "source_plan": original_binding,
        "retained_archive": collection["archive"],
        "retained_methods": controls,
        "retained_control_inference_compatibility": compatibility,
        "new_arms": arms,
        "triplet_arms": arms,
        "cases": original["cases"],
        "observations": original["observations"],
        "noise": original["noise"],
        "exact_synthetic_cases": exact_cases,
        "observations_per_model": count,
        "planned_new_root_forwards": count * len(arms),
        "planned_new_encoder_forwards": count * len(arms),
        "retained_control_predictions": count * len(controls),
        "planned_native_exact_GT_triplets": 2 * len(arms),
        "new_noise_observations": 0,
        "RAW_decodes": 0,
        "reference_neural_forwards": 0,
        "optimizer_updates": 0,
        "automatic_retries": 0,
        "maximum_dependency_wait_seconds": 1209600,
        "maximum_headroom_wait_seconds": 7200,
        "maximum_collection_seconds": 7200,
        "maximum_analysis_seconds": 3600,
        "phase_start_RAM_GiB": 48,
        "runtime_RAM_GiB": 32,
        "CUDA_quota_GiB": 12,
        "phase_start_internal_free_GiB": 128,
        "runtime_internal_reserve_GiB": 96,
        "runtime_external_reserve_GiB": 208,
        "inputs": list({v["path"]: v for v in inputs}.values()),
        "frozen_files": {str(p): ref(p)["sha256"] for p in work.rglob("*") if p.is_file()},
        "scope": (
            "Supplemental completed-endpoint bias/variance comparison after exact full quality/"
            "mesh owners exit successfully. Only new models run on128 already stored observations "
            "each;256 V120/V117 controls are reused without neural reruns. Four targets, four CFAs, "
            "eight draws; original noise/input/display/target protocol. Two native exact-synthetic-"
            "GT triplets per new endpoint and single/mean8 diagnostic boards. No reference NN, "
            "new noise, RAW, optimizer, automatic retry or promotion. Primary gains can be "
            "documented independently; this supplement is not a promotion gate."
        ),
    }
    path = root / "queue-plan-v1.json"
    save(path, plan)
    guard(plan)
    return path


def execution_plan(path):
    plan = read(path)
    guard(plan)
    for dep in plan["dependencies"]:
        if not dependency_ready(read(dep["status"]), dep):
            raise RuntimeError("Original dependency is still live")
    quality = read(plan["quality_plan"]["path"])
    state = read(Path(quality["root"]) / "status.json")
    if set(state["completed"]) != set(quality["stages"]):
        raise ValueError("Full endpoint quality stages are incomplete")
    evaluation_path = Path(quality["root"]) / "evaluation-plan-v1.json"
    evaluation = read(evaluation_path)
    guard(evaluation)
    photo_binding = state["completed"]["photo"]
    photo = read(checked(photo_binding))
    if live(photo["owner"]) or photo["plan"] != ref(evaluation_path):
        raise ValueError("Original photo result owner or plan differs")
    methods = completed_methods(evaluation, photo, plan["new_arms"])
    hashes = [m["expected_full_model_sha256"] for m in plan["retained_methods"] + methods]
    if len(set(hashes)) != len(hashes):
        raise ValueError(
            "A model state was already evaluated; review and adopt equivalent stored responses before scheduling neural work"
        )
    for method in methods:
        checkpoint = checked(method["checkpoint"])
        if checkpoint.is_symlink() or checkpoint.stat().st_mode & 0o222:
            raise ValueError("Conditional response requires immutable completed checkpoint copies")
    result = {
        **plan,
        "queue_plan": ref(path),
        "methods": methods,
        "inputs": [
            *plan["inputs"],
            ref(evaluation_path),
            photo_binding,
            *[m["checkpoint"] for m in methods],
            *[ref(d["status"]) for d in plan["dependencies"]],
        ],
    }
    target = Path(plan["root"]) / "execution-plan-v1.json"
    save(target, result)
    guard(result)
    return target


def collect(path):
    import torch
    from frozen_backbone_identity import verify_backbone_identity
    from profile_raw_kernel_inference import model_hash

    from demosaic.inference import load_checkpoint
    from demosaic.prediction_archive import PredictionArchive, fingerprint

    plan = read(path)
    guard(plan)
    root, work = Path(plan["root"]), Path(plan["work"])
    if Path(load_checkpoint.__code__.co_filename).resolve().is_relative_to(work / "src") is False:
        raise RuntimeError("Model execution must use the actual frozen quality source")
    if ref(__file__) != plan["controller_source"] or os.environ.get("CUDA_VISIBLE_DEVICES") != "0":
        raise RuntimeError("Unexpected conditional collector source or device")
    (root / "collect.claim").open("x").close()
    torch.set_num_threads(2)
    torch.set_float32_matmul_precision("highest")
    torch.backends.cuda.matmul.allow_tf32 = torch.backends.cudnn.allow_tf32 = False
    torch.backends.cudnn.benchmark = True
    torch.cuda.set_per_process_memory_fraction(
        plan["CUDA_quota_GiB"] * 2**30 / torch.cuda.get_device_properties(0).total_memory
    )
    cases = {case["id"]: case for case in plan["cases"]}
    archive = PredictionArchive(work / "artifacts/predictions")
    reports = []
    for method in plan["methods"]:
        model, state = load_checkpoint(checked(method["checkpoint"]), "cuda")
        if (
            state["step"] != 20000
            or state["config"]["initialized_from"] != method["expected_lineage"]["initialized_from"]
        ):
            raise ValueError("Loaded endpoint lineage differs")
        actual = model.restoration_state_dict()
        if (
            getattr(model.config, "raw_frequency_features", False)
            or getattr(model.pretrained_rgb, "raw_frequency", None) is not None
        ):
            raise ValueError("This comparison requires the unchanged V120-family operator")
        if len(actual) != 91 or any(
            not torch.equal(v.cpu(), state["ema"][k]) for k, v in actual.items()
        ):
            raise ValueError("Conditional collector did not load the exact completed EMA")
        verify_backbone_identity(
            model.config.to_dict(),
            model_hash(model.context.backbone),
            {"expected_backbone": method["expected_backbone"]},
            legacy_sha256=method["expected_backbone"]["sha256"],
        )
        del state, actual
        model.eval().to(memory_format=torch.channels_last)
        before = model_hash(model)
        if before != method["expected_full_model_sha256"]:
            raise ValueError(
                "Conditional endpoint differs from its original full quality evaluation"
            )
        counts = {"root": 0, "encoder": 0}
        witness = {}

        def pre_hook(module, args, _counts=counts, _witness=witness):
            if (
                module.training
                or torch.backends.cuda.matmul.allow_tf32
                or torch.backends.cudnn.allow_tf32
            ):
                raise RuntimeError("Conditional inference must remain single-view IEEE FP32")
            values = {
                k: fingerprint(v)
                for k, v in zip(("packed", "variance", "colors", "wb", "matrix"), args, strict=True)
            }
            if values != _witness["inputs"] or _counts["root"] >= plan["observations_per_model"]:
                raise ValueError("Actual conditional forward arguments/count differ")
            if psutil.virtual_memory().available < plan["runtime_RAM_GiB"] * 2**30:
                raise RuntimeError("Conditional collector memory reserve reached")

        def post_hook(module, args, value, _counts=counts):
            if (
                value.dtype != torch.float32
                or value.shape != (1, 3, 256, 256)
                or not torch.isfinite(value).all()
            ):
                raise ValueError("Invalid native conditional output")
            _counts["root"] += 1

        def encoder_hook(*args, _counts=counts):
            _counts["encoder"] += 1

        handles = [
            model.register_forward_pre_hook(pre_hook),
            model.register_forward_hook(post_hook),
            model.context.backbone.register_forward_hook(encoder_hook),
        ]
        model.set_noise(plan["noise"]["shot"], plan["noise"]["read"])
        with torch.inference_mode():
            for observed in plan["observations"]:
                with np.load(checked(observed["arrays"]), allow_pickle=False) as arrays:
                    cpu = {k: arrays[k] for k in arrays.files}
                expected = observed["input_fingerprints"]
                witness["inputs"] = expected
                if {k: fingerprint(v) for k, v in cpu.items()} != expected:
                    raise ValueError("Stored conditional input bytes differ")
                batch = {k: torch.from_numpy(v).to("cuda") for k, v in cpu.items()}
                prediction = model(
                    *(batch[k] for k in ("packed", "variance", "colors", "wb", "matrix"))
                )
                with np.load(
                    checked(cases[observed["case_id"]]["target"]), allow_pickle=False
                ) as arrays:
                    target = arrays["target"]
                archive.append(
                    {
                        "label": method["label"],
                        "sha256": method["checkpoint"]["sha256"],
                        "step": 20000,
                        "self_ensemble": "none",
                    },
                    {
                        **observed,
                        "stage": "conditional-noise-response",
                        "ids": [observed["id"]],
                        "noise": plan["noise"],
                    },
                    prediction,
                    {"target": target, "wb": cpu["wb"], "matrix": cpu["matrix"]},
                )
        if (
            counts
            != {"root": plan["observations_per_model"], "encoder": plan["observations_per_model"]}
            or model_hash(model) != before
        ):
            raise ValueError("Conditional model state or actual counts changed")
        for handle in handles:
            handle.remove()
        reports.append({"method": method, **counts, "model_unchanged": True})
        del model
        gc.collect()
        torch.cuda.empty_cache()
    alignment = archive.verify_alignment()
    if alignment["records"] != plan["planned_new_root_forwards"] or alignment["models"] != len(
        plan["methods"]
    ):
        raise ValueError("Conditional prediction archive coverage differs")
    save(
        root / "collection-v1.json",
        {
            "plan": ref(path),
            "archive": ref(archive.manifest),
            "methods": reports,
            "owner": {"pid": os.getpid(), "created": psutil.Process().create_time()},
            "new_root_forwards": sum(r["root"] for r in reports),
            "new_encoder_forwards": sum(r["encoder"] for r in reports),
            "new_reference_forwards": 0,
            "new_noise_observations": 0,
            "RAW_decodes": 0,
            "optimizer_updates": 0,
            "alignment": alignment,
        },
    )
    guard(plan)


def controller(path):
    if os.environ.get("CUDA_VISIBLE_DEVICES") != "" or "torch" in sys.modules:
        raise RuntimeError("Conditional queue controller is CPU-only")
    plan = read(path)
    guard(plan)
    if ref(__file__) != plan["controller_source"]:
        raise ValueError("Conditional controller source differs")
    root, work = Path(plan["root"]), Path(plan["work"])
    (root / "controller.claim").open("x").close()
    state = {
        "owner": {"pid": os.getpid(), "created": psutil.Process().create_time()},
        "plan": ref(path),
        "completed": {},
    }
    child = child_owner = None

    def record(status, **details):
        state.update(status=status, updated_unix=time.time(), **details)
        save(root / "status.json", state)

    def run(command, phase, timeout):
        nonlocal child, child_owner
        record("waiting-for-conditional-response-headroom", phase=phase, child=None)
        began = time.monotonic()
        while (
            psutil.virtual_memory().available < plan["phase_start_RAM_GiB"] * 2**30
            or shutil.disk_usage(root).free < plan["phase_start_internal_free_GiB"] * 2**30
            or shutil.disk_usage("/mnt/external").free
            < plan["runtime_external_reserve_GiB"] * 2**30
        ):
            if time.monotonic() - began > plan["maximum_headroom_wait_seconds"]:
                raise TimeoutError("Conditional resource observation window expired")
            time.sleep(5)
        guard(plan)
        env = dict(
            os.environ,
            PYTHONPATH=f"{work / 'src'}:{work / 'scripts'}",
            CUDA_VISIBLE_DEVICES="0" if phase == "collect" else "",
            OPENBLAS_NUM_THREADS="1",
            OMP_NUM_THREADS="2",
            HF_HUB_OFFLINE="1",
            TRANSFORMERS_OFFLINE="1",
        )
        with (root / f"{phase}-v1.log").open("x") as log:
            child = subprocess.Popen(
                command,
                cwd=work,
                env=env,
                stdin=subprocess.DEVNULL,
                stdout=log,
                stderr=subprocess.STDOUT,
                start_new_session=True,
            )
            child_owner = {"pid": child.pid, "created": psutil.Process(child.pid).create_time()}
            record("running-explicit-conditional-response-child", phase=phase, child=child_owner)
            began = time.monotonic()
            while child.poll() is None:
                if (
                    time.monotonic() - began > timeout
                    or psutil.virtual_memory().available < plan["runtime_RAM_GiB"] * 2**30
                    or shutil.disk_usage(root).free < plan["runtime_internal_reserve_GiB"] * 2**30
                    or shutil.disk_usage("/mnt/external").free
                    < plan["runtime_external_reserve_GiB"] * 2**30
                ):
                    raise RuntimeError("Conditional runtime reserve/window reached")
                time.sleep(2)
            if child.wait() != 0:
                raise RuntimeError(f"Conditional {phase} child failed; existing work preserved")

    try:
        began = time.monotonic()
        for dep in plan["dependencies"]:
            record("waiting-for-exact-endpoint-review-owner", dependency=dep["owner"], child=None)
            while True:
                try:
                    ready = dependency_ready(read(dep["status"]), dep)
                except (OSError, json.JSONDecodeError):
                    ready = False
                if ready:
                    break
                if time.monotonic() - began > plan["maximum_dependency_wait_seconds"]:
                    raise TimeoutError("Conditional dependency observation window expired")
                time.sleep(10)
        execution = execution_plan(path)
        run(
            [plan["python"], "-P", plan["controller_source"]["path"], "collect", str(execution)],
            "collect",
            plan["maximum_collection_seconds"],
        )
        actual = read(root / "collection-v1.json")
        if (
            actual["owner"] != child_owner
            or actual["new_root_forwards"] != plan["planned_new_root_forwards"]
        ):
            raise ValueError("Completed conditional collector owner/count differs")
        state["completed"]["collect"] = ref(root / "collection-v1.json")
        run(
            [
                plan["python"],
                "-P",
                plan["report_source"]["path"],
                str(execution),
                str(root / "collection-v1.json"),
            ],
            "analyze",
            plan["maximum_analysis_seconds"],
        )
        analysis = read(root / "analysis-v1.json")
        triplets = [i for i in analysis["images"] if i["kind"] == "single-triplet"]
        if len(triplets) != plan["planned_native_exact_GT_triplets"]:
            raise ValueError("Conditional report is missing its declared native GT triplets")
        state["completed"]["analyze"] = ref(root / "analysis-v1.json")
        record("completed-conditional-response-native-viewing-pending", child=None)
    except BaseException as error:
        if child is not None and child.poll() is None and child_owner and live(child_owner):
            os.killpg(child.pid, signal.SIGINT)
            try:
                child.wait(timeout=30)
            except subprocess.TimeoutExpired:
                if live(child_owner):
                    os.killpg(child.pid, signal.SIGTERM)
                child.wait(timeout=30)
        record("failed-conditional-response-preserved-no-automatic-retry", error=repr(error))
        raise


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("mode", choices=("prepare", "execution", "controller", "collect"))
    parser.add_argument("path", type=Path)
    parser.add_argument("--quality", type=Path)
    parser.add_argument("--mesh", type=Path)
    parser.add_argument("--source", type=Path)
    parser.add_argument("--arms", nargs="+")
    args = parser.parse_args()
    if args.mode == "prepare":
        print(prepare(args.path, args.quality, args.mesh, args.source, args.arms))
    elif args.mode == "execution":
        print(execution_plan(args.path))
    elif args.mode == "controller":
        controller(args.path)
    else:
        collect(args.path)

"""Factor future frozen V183 state out of spatial-context head checkpoints."""

import copy

import torch
from lossless_native import checked
from phase_wave_training_state import readout_parameters


def inherited_state(binding):
    exported = torch.load(checked(binding), map_location="cpu", weights_only=True)
    state = exported["state_dict"]
    if len(state) != 189 or any(n.startswith("wave_readout.") for n in state):
        raise ValueError("Expected the exact 189-tensor V183 EMA export")
    return state


def pack_checkpoint(payload, initializer):
    """Keep head/Adam/EMA/RNG; bind every omitted tensor to a checked export."""
    source = inherited_state(initializer)
    state = payload["models"]
    frozen = {n: v for n, v in state.items() if not n.startswith("wave_readout.")}
    if set(frozen) != set(source) or any(
        v.dtype != source[n].dtype
        or v.shape != source[n].shape
        or not torch.equal(v.detach().cpu(), source[n])
        for n, v in frozen.items()
    ):
        raise ValueError("Cannot factor a changed inherited tensor")
    head = {n: v for n, v in state.items() if n.startswith("wave_readout.")}
    if len(head) != 4 or set(head) != set(payload["ema"]):
        raise ValueError("Expected exactly four raw and EMA head tensors")
    return {
        **{k: v for k, v in payload.items() if k != "models"},
        "format": "frozen-V183-plus-spatial-head-v1",
        "initializer": initializer,
        "head": head,
    }


def expand_checkpoint(checkpoint):
    """Reconstruct strict full state on CPU without inference or optimizer work."""
    if checkpoint.get("format") != "frozen-V183-plus-spatial-head-v1":
        raise ValueError("Expected factored spatial-head checkpoint")
    source = inherited_state(checkpoint["initializer"])
    head = checkpoint["head"]
    if len(head) != 4 or any(not n.startswith("wave_readout.") for n in head):
        raise ValueError("Expected only four wave readout tensors")
    if set(head) != set(checkpoint["ema"]):
        raise ValueError("Raw and EMA head names differ")
    result = {k: v for k, v in checkpoint.items() if k not in ["head", "format", "initializer"]}
    result["models"] = {**source, **head}
    return result


def restore_factored(module, checkpoint, *, lr, weight_decay):
    from phase_wave_training_state import restore_state

    expanded = expand_checkpoint(checkpoint)
    if set(expanded["models"]) != set(module.state_dict()):
        raise ValueError("Factored checkpoint has incompatible strict state names")
    if set(checkpoint["head"]) != set(readout_parameters(module)):
        raise ValueError("Factored checkpoint has incompatible trainable names")
    return restore_state(module, copy.deepcopy(expanded), lr=lr, weight_decay=weight_decay)

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_robust_spectral_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 4932 and retained == 1398 and real == 42 and len(result["rows"]) == 6330
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 6330,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())

"""Future spatial-trial receipts may use lossless gzip to retain full evidence."""

import gzip
import json
from pathlib import Path

from phase_admission_protocol import owner_live, ref  # noqa: F401


def open_text(path, mode='rt'):
    path = Path(path)
    if path.suffix == '.gz':
        return gzip.open(path, mode, encoding='utf-8', compresslevel=6)
    return path.open(mode.replace('t', ''), encoding='utf-8')


def read(path):
    with open_text(path) as stream:
        return json.load(stream)


def save(path, value):
    with open_text(path, 'xt') as stream:
        json.dump(value, stream, separators=(',', ':'), allow_nan=False)
        stream.write('\n')

"""Optimizer/EMA state for the isolated readout above frozen V183 EMA."""

import copy
import hashlib

import torch


def readout_parameters(module):
    parameters = {n: p for n, p in module.named_parameters() if p.requires_grad}
    expected = {"wave_readout." + n for n, _ in module.wave_readout.named_parameters()}
    if set(parameters) != expected or len(parameters) != 4:
        raise ValueError("Only the four readout tensors may train")
    return parameters


def inherited_hash(module):
    digest = hashlib.sha256()
    for name, value in module.state_dict().items():
        if name.startswith("wave_readout."):
            continue
        value = value.detach().cpu().contiguous()
        digest.update(name.encode() + str(value.dtype).encode() + str(tuple(value.shape)).encode())
        digest.update(value.reshape(-1).view(torch.uint8).numpy().tobytes())
    return digest.hexdigest()


def fresh_state(module, *, lr, weight_decay):
    parameters = readout_parameters(module)
    optimizer = torch.optim.AdamW(parameters.values(), lr=lr, weight_decay=weight_decay)
    ema = {n: p.detach().clone() for n, p in parameters.items()}
    return optimizer, ema


def update_ema(module, ema, *, updates):
    parameters = readout_parameters(module)
    if set(ema) != set(parameters) or type(updates) is not int or updates < 1:
        raise ValueError("Expected all readout EMA tensors and a positive new-head clock")
    decay = min(0.999, (1 + updates) / (10 + updates))
    with torch.no_grad():
        for n, p in parameters.items():
            if p.shape != ema[n].shape or p.dtype != ema[n].dtype:
                raise ValueError("Readout EMA shape/dtype mismatch")
            ema[n].lerp_(p, 1 - decay)
    return decay


def load_ema(module, ema):
    parameters = readout_parameters(module)
    if set(parameters) != set(ema):
        raise ValueError("Expected exactly the four readout EMA tensors")
    with torch.no_grad():
        for n, p in parameters.items():
            if p.shape != ema[n].shape or p.dtype != ema[n].dtype:
                raise ValueError("Readout EMA shape/dtype mismatch")
            p.copy_(ema[n])


def clocks(module, optimizer):
    parameters = readout_parameters(module)
    if (
        len(optimizer.param_groups) != 1
        or len(optimizer.param_groups[0]["params"]) != 4
        or set(optimizer.param_groups[0]["params"]) != set(parameters.values())
        or set(optimizer.state) - set(parameters.values())
    ):
        raise ValueError("Optimizer must contain only readout state")
    steps = []
    for parameter in parameters.values():
        state = optimizer.state.get(parameter)
        if state:
            if not all(torch.isfinite(v).all() for v in state.values() if torch.is_tensor(v)):
                raise ValueError("Nonfinite readout Adam state")
            steps.append(float(state["step"]))
    return {"tensors": 4, "states": len(steps), "steps": sorted(set(steps))}


def restore_state(module, checkpoint, *, lr, weight_decay):
    from train_local_noise_matching_trial import tree_equal

    module.load_state_dict(checkpoint["models"], strict=True)
    optimizer, _ = fresh_state(module, lr=lr, weight_decay=weight_decay)
    optimizer.load_state_dict(copy.deepcopy(checkpoint["optimizer"]))
    assert tree_equal(optimizer.state_dict(), checkpoint["optimizer"])
    parameters = readout_parameters(module)
    assert set(checkpoint["ema"]) == set(parameters)
    ema = {n: v.detach().to(parameters[n].device).clone() for n, v in checkpoint["ema"].items()}
    assert all(p.shape == ema[n].shape and p.dtype == ema[n].dtype for n, p in parameters.items())
    assert clocks(module, optimizer) == {
        "tensors": 4,
        "states": 4,
        "steps": [float(checkpoint["updates"])],
    }
    assert inherited_hash(module) == checkpoint["inherited_hash"]
    torch.set_rng_state(checkpoint["CPU_RNG"])
    if checkpoint.get("CUDA_RNG") is not None:
        torch.cuda.set_rng_state(checkpoint["CUDA_RNG"])
    assert torch.equal(torch.get_rng_state(), checkpoint["CPU_RNG"])
    if checkpoint.get("CUDA_RNG") is not None:
        assert torch.equal(torch.cuda.get_rng_state(), checkpoint["CUDA_RNG"])
    return optimizer, ema

"""Recompute detail/flat reductions with independent NumPy64 and Decimal."""

import argparse
import os
from collections import defaultdict
from decimal import Decimal, localcontext
from pathlib import Path

import numpy as np
from score_delivered_objective_trial import load_module
from train_directional_bank_trial import read, ref, save


def main(root):
    os.nice(10)
    os.sched_setaffinity(0, sorted(os.sched_getaffinity(0))[2:4])
    design = read(root / "quality-design-v1.json")
    result = read(root / "scores-v1.json")
    assert result["design"] == ref(root / "quality-design-v1.json")
    independent_source = root.parent / "collaborative-detail-v1/audit-transfer-v1.py"
    metric = load_module(independent_source, "independent_late_spectral_metrics")
    review = read(root / "review-result-v1.json")
    maps = {}
    for label, binding in review["collections"].items():
        assert ref(binding["path"]) == binding
        collection = read(binding["path"])
        assert (
            collection["module_before"] == collection["module_after"]
            and collection["RNG_unchanged"]
        )
        assert collection["component_forwards"] == 822
        maps[label] = {o["id"]: o for o in collection["observations"]}
    by_id = defaultdict(list)
    for row in result["rows"]:
        by_id[row["id"]].append(row)
    cached = read(Path(read(root / "plan-v1.json")["previous"]) / "scores-v1.json")
    cached_rows = {
        (r["id"], r["method"]): r
        for r in cached["rows"]
        if r["method"] in ("parent", "periodic-detail")
    }
    checks = calls = retained = real = 0
    maximum = 0.0
    for index, case in enumerate(design["observations"]):
        assert ref(case["arrays"]["path"]) == case["arrays"]
        arrays = dict(np.load(case["arrays"]["path"]))
        expected = {
            "parent": case["parent"],
            **{k: m[case["id"]]["prediction"] for k, m in maps.items()},
        }
        if "periodic_detail" in case:
            expected["periodic-detail"] = case["periodic_detail"]
        assert set(expected) == {r["method"] for r in by_id[case["id"]]}
        parent = np.load(case["parent"]["path"]).astype(np.float64)
        for row in by_id[case["id"]]:
            label = row["method"]
            assert row["index"] == index and row["prediction"] == expected[label]
            assert ref(row["prediction"]["path"]) == row["prediction"]
            raw = np.load(row["prediction"]["path"])
            assert raw.dtype == np.float32 and raw.shape == parent.shape and np.isfinite(raw).all()
            value = raw.astype(np.float64)
            change = value - parent
            assert row["changed"] == (not np.array_equal(value, parent))
            assert row["new_forward"] == (label in maps)
            calls += label in maps
            if label in maps:
                binding = maps[label][case["id"]]
                assert binding["parent"] == case["parent"] and binding["module_forwards"] == 1
                for k, f in binding["inputs"].items():
                    import hashlib

                    v = np.ascontiguousarray(arrays[k])
                    assert f == {
                        "shape": list(v.shape),
                        "dtype": v.dtype.str,
                        "sha256": hashlib.sha256(v.tobytes()).hexdigest(),
                    }
            actual = {"correction_RMS_DN16": float(np.sqrt(np.mean(change**2)) * 65535)}
            if case["kind"] == "real":
                assert row["reference_scored"] is False and "full_error_RMS_DN16" not in row
                real += 1
                if value.shape[-1] == 512:
                    plane = metric.detrend(value[0])
                    blocks = np.stack(
                        [
                            plane[:, y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, 512, 32)
                            for x in range(0, 512, 32)
                        ],
                        -1,
                    )
                    actual["detrended_block32_variation_DN16"] = float(
                        np.sqrt(np.mean(blocks**2)) * 65535
                    )
            else:
                actual.update(
                    metric.photo_metrics(raw, arrays["target"], arrays, case["ROI_xywh"])
                    if case["kind"] == "photo"
                    else metric.errors(raw, arrays["target"], case["ROI_xywh"])
                )
                if case["kind"] == "mesh":
                    empty = arrays["target_empty"][0].astype(np.float64)
                    signal = metric.detrend(arrays["target_present"][0].astype(np.float64) - empty)
                    actual["template_gain"] = float(
                        np.sum(metric.detrend(value[0] - empty) * signal) / np.sum(signal**2)
                    )
                    blank = (
                        np.all(arrays["target_present"] == arrays["target_empty"], axis=1)[0]
                        if case["present"]
                        else np.ones((512, 512), bool)
                    )
                    assert row["blank_pixels"] == int(blank.sum())
                    if blank.any():
                        actual["blank_added_RMS_DN16"] = float(
                            np.sqrt(np.mean(change[0][:, blank] ** 2)) * 65535
                        )
                    else:
                        assert row["blank_added_RMS_DN16"] is None
                    if blank.any():
                        error = (value[0] - arrays["target"][0].astype(np.float64))[:, blank]
                        means = error.mean(1)
                        actual["blank_error_RMS_DN16"] = float(
                            np.linalg.norm(error) / np.sqrt(error.size) * 65535
                        )
                        actual["blank_DC_RMS_DN16"] = float(
                            np.linalg.norm(means) / np.sqrt(3) * 65535
                        )
                        actual["blank_spatial_RMS_DN16"] = float(
                            np.sqrt(max(0, np.mean(error**2) - np.mean(means**2))) * 65535
                        )
                elif case["kind"] == "mixed-quiet":
                    x, y, w, h = case["ROI_xywh"]
                    actual["quiet_error_RMS_DN16"] = float(
                        np.linalg.norm(
                            (value - arrays["target"].astype(np.float64))[
                                ..., y : y + h, x : x + w
                            ].ravel()
                        )
                        / np.sqrt(3 * w * h)
                        * 65535
                    )
                    actual["quiet_spatial_RMS_DN16"] = actual["crop_spatial_RMS_DN16"]
                    actual["quiet_added_RMS_DN16"] = float(
                        np.sqrt(np.mean(change[..., y : y + h, x : x + w] ** 2)) * 65535
                    )
                elif case["kind"] == "flat":
                    error = value - arrays["target"].astype(np.float64)
                    h, w = error.shape[-2:]
                    dc = error.mean((-2, -1))
                    blocks = np.stack(
                        [
                            error[..., y : y + 32, x : x + 32].mean((-2, -1))
                            for y in range(0, h, 32)
                            for x in range(0, w, 32)
                        ],
                        -1,
                    )
                    x, y, cw, ch = case["ROI_xywh"]
                    crop = error[..., y : y + ch, x : x + cw]
                    crop_dc = crop.mean((-2, -1))
                    cb = np.stack(
                        [
                            crop[..., j : j + 32, i : i + 32].mean((-2, -1))
                            for j in range(0, 160, 32)
                            for i in range(0, 160, 32)
                        ],
                        -1,
                    )
                    actual.update(
                        full_spatial_RMS_DN16=float(
                            np.sqrt(np.mean((error - dc[..., None, None]) ** 2)) * 65535
                        ),
                        block32_RMS_DN16=float(
                            np.sqrt(np.mean((blocks - dc[..., None]) ** 2)) * 65535
                        ),
                        crop_block32_RMS_DN16=float(
                            np.sqrt(np.mean((cb - crop_dc[..., None]) ** 2)) * 65535
                        ),
                        maximum_abs_DC_DN16=float(np.max(np.abs(dc)) * 65535),
                    )
            for field, value in actual.items():
                difference = abs(value - row[field])
                assert difference < 1e-9 * max(1, abs(value)), (case["id"], label, field)
                maximum = max(maximum, difference)
                checks += 1
            if label in ("parent", "periodic-detail") and (case["id"], label) in cached_rows:
                old = cached_rows[case["id"], label]
                assert row["prediction"] == old["prediction"]
                for field in actual:
                    if field in old:
                        assert abs(row[field] - old[field]) < 1e-10
                retained += 1
    assert calls == 4932 and retained == 1398 and real == 42 and len(result["rows"]) == 6330
    groups = defaultdict(list)
    for row in result["rows"]:
        groups[
            row["kind"],
            row.get("present", row.get("variant", row.get("noise"))),
            row.get("cohort"),
            row["method"],
        ].append(row)
    reductions = 0
    for item in result["summary"]:
        group = groups[item["kind"], item["condition"], item["cohort"], item["method"]]
        assert item["cases"] == len(group)
        for field in item.keys() - {
            "kind",
            "condition",
            "cohort",
            "method",
            "cases",
            "worst_abs_DC_DN16",
            "worst_blank_added_RMS_DN16",
            "worst_blank_error_RMS_DN16",
        }:
            values = [r[field] for r in group if r.get(field) is not None]
            with localcontext() as ctx:
                ctx.prec = 50
                number = float(sum(Decimal(str(v)) for v in values) / len(values))
            assert abs(number - item[field]) < 1e-10
            reductions += 1
        if item["kind"] == "mesh":
            assert item["worst_blank_added_RMS_DN16"] == max(
                r["blank_added_RMS_DN16"] or 0 for r in group
            )
        if item["kind"] == "mesh":
            assert item["worst_blank_error_RMS_DN16"] == max(
                r.get("blank_error_RMS_DN16", 0) for r in group
            )
        if item["kind"] == "flat":
            assert item["worst_abs_DC_DN16"] == max(r["maximum_abs_DC_DN16"] for r in group)
    save(
        root / "independent-metrics-audit-v1.json",
        {
            "status": "pass",
            "scores": ref(root / "scores-v1.json"),
            "auditor": ref(__file__),
            "independent_metric_source": ref(independent_source),
            "rows": 6330,
            "module_forwards_verified": calls,
            "retained_bindings_and_metrics": retained,
            "real_rows_unscored": real,
            "scalar_checks": checks,
            "maximum_scalar_difference": maximum,
            "Decimal_reductions": reductions,
            "new_forwards": 0,
            "new_noise_draws": 0,
        },
    )
    print("PASS independent scalar checks:", checks, "Decimal reductions:", reductions)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("root", type=Path)
    main(parser.parse_args().root.resolve())

"""Review saved mature precision scalars only after actual native-cell viewing."""

import argparse
import os
from pathlib import Path

import numpy as np
from mature_precision_review_tools import (
    carrier_metrics,
    comparison_gates,
    display_metrics,
    flat_metrics,
    input_fingerprint,
    linear_rgb,
    physical_difference,
)
from queue_tf32x3_cuda import alive
from render_mature_precision import (
    POLICIES,
    arrays,
    checked,
    gpu_methods,
    prediction,
    save_new,
)
from train_directional_bank_trial import guard, read, ref


def manual_review(index_path, manual_path, methods):
    index, manual = read(index_path), read(manual_path)
    if manual.get("status") != "actually-viewed-all-native-mature-precision-cells-before-scalars":
        raise ValueError("Actual native viewing receipt is required before scalar review")
    if (
        manual.get("render_index") != ref(index_path)
        or manual.get("new_scalars_interpreted") is not False
    ):
        raise ValueError("Manual viewing must precede scalar interpretation for these exact boards")
    if index["methods"] != methods or index["triplets"] != 36 or index["native_cells_exact"] != 48:
        raise ValueError("Native render does not cover all actual pilot policies and fixed cases")
    if len(manual.get("boards", [])) != 2 or not manual.get("observed_UTC"):
        raise ValueError("Both actual native boards and viewing time are required")
    for item, viewed in zip(index["boards"], manual["boards"], strict=True):
        board = read(checked(item))
        checked(board["board"])
        if (
            viewed["receipt"] != item
            or viewed["image"] != board["board"]
            or viewed["native_cells_viewed"] != board["native_cells_exact"]
            or not viewed.get("observations")
        ):
            raise ValueError("Manual receipt must describe every cell in each exact native board")
    findings = manual.get("per_policy_findings", [])
    expected = {(m["model"], m["policy"]) for m in methods if m["policy"] != "fp32"}
    keys = [(r["model"], r["policy"]) for r in findings]
    if (
        len(set(keys)) != len(keys)
        or set(keys) != expected
        or any(
            type(r.get("no_visible_new_artifact")) is not bool or not r.get("notes")
            for r in findings
        )
    ):
        raise ValueError("Record an actual visible-artifact finding for each half policy/model")
    return {(r["model"], r["policy"]): r for r in findings}


def main(protocol_path, receipt_path, index_path, manual_path, output):
    import torch

    import demosaic.metrics as canonical

    if os.environ.get("CUDA_VISIBLE_DEVICES") != "" or torch.cuda.is_initialized():
        raise ValueError("Scalar review must remain CPU-only")
    torch.set_num_threads(2)
    protocol = read(protocol_path)
    guard(protocol)
    if (
        ref(__file__) != protocol["reviewer"]
        or ref(canonical.__file__) != protocol["canonical_metrics"]
    ):
        raise ValueError("Run the source-frozen scalar reviewer and canonical metrics")
    plan_path = checked(protocol["GPU_plan"])
    plan = read(plan_path)
    guard(plan)
    status = read(Path(plan["root"]) / "controller-status.json")
    gpu = read(receipt_path)
    if (
        status["status"]
        != "completed-mature-precision-pilot-arrays-awaiting-native-and-independent-scalar-review"
        or status["plan"] != ref(plan_path)
        or status["receipt"] != ref(receipt_path)
        or status["child"] != gpu["owner"]
        or alive(status["controller"])
        or alive(status["child"])
    ):
        raise ValueError("GPU worker/controller must complete successfully and actually exit")
    methods = gpu_methods(plan_path, receipt_path)
    index = read(index_path)
    if index["driver"] != protocol["renderer"] or ref(receipt_path) not in index["evidence"]:
        raise ValueError("Native renderer/input receipt differs from the frozen postprocessing")
    findings = manual_review(index_path, manual_path, methods)
    # No quality/timing reduction occurs above the actual-viewing requirement.
    output = Path(output)
    output.mkdir(parents=True, exist_ok=False)
    cpu = read(checked(plan["CPU_preflight"]))
    inputs = {f["id"]: arrays(f["arrays"]) for f in plan["fixtures"]}
    fingerprints = {k: input_fingerprint(v) for k, v in inputs.items()}
    base_fixture, plus_fixture = plan["fixtures"][-2:]
    if (
        base_fixture["kind"] != "ramp"
        or plus_fixture["kind"] != "ramp"
        or base_fixture["patterns"] != ["RGGB", "BGGR", "GRBG", "GBRG"]
    ):
        raise ValueError("Expected the frozen all-CFA ramp pair")
    for name in inputs[base_fixture["id"]]:
        expected = inputs[base_fixture["id"]][name]
        if name == "packed":
            expected = expected + np.float32(1 / 65535)
        np.testing.assert_array_equal(inputs[plus_fixture["id"]][name], expected)
    rows, differences, ramps, timing_rows, policy_results = [], [], [], [], []
    for model in gpu["models"]:
        label = model["model"]
        proof = next(r for r in cpu["models"] if r["label"] == label)
        if (
            model["model_sha256"] != proof["model_sha256"]
            or model["DINO_sha256"] != proof["DINO_sha256"]
            or not model["FP32_hidden_identity_exact"]
            or not model["model_config_parameter_RNG_exact"]
            or model["instrumented_encoder_calls"] != 94
            or model["unhooked_timing_forwards"] != 12
        ):
            raise ValueError("GPU state/dtype/forward evidence differs from fixed pilot")
        captures = {(c["policy"], c["fixture"]): c for c in model["captures"]}
        scored = {}
        for fixture in plan["fixtures"]:
            host = inputs[fixture["id"]]
            shape = (
                len(host["packed"]),
                3,
                host["packed"].shape[-2] * 2,
                host["packed"].shape[-1] * 2,
            )
            predictions = {}
            for policy in POLICIES:
                capture = captures[policy, fixture["id"]]
                expected_dtypes = {
                    "physical_head": "torch.float32",
                    "middle": "torch.float32",
                    "physical_tail": "torch.float32",
                    "first_encoder": "torch.float16"
                    if policy == "fp16-hidden"
                    else "torch.float32",
                }
                if (
                    capture["input_sha256"] != fingerprints[fixture["id"]]
                    or capture["dtypes"] != expected_dtypes
                ):
                    raise ValueError("GPU physical input fingerprint or observed dtype differs")
                pred = prediction(capture["RGB"], shape)
                predictions[policy] = pred
                if fixture["kind"] == "photo":
                    tensors = [
                        torch.from_numpy(v)
                        for v in (pred, host["target"], host["wb"], host["matrix"])
                    ]
                    values = canonical.quality_metrics(*tensors)
                    fp32 = {k: float(values[k][0]) for k in ("srgb_psnr", "srgb_ssim")}
                    f64 = {
                        k: float(v[0])
                        for k, v in display_metrics(
                            pred, host["target"], host["wb"], host["matrix"]
                        ).items()
                    }
                    row = {
                        "model": label,
                        "policy": policy,
                        "fixture": fixture["id"],
                        "kind": "photo",
                        "RGB": capture["RGB"],
                        "canonical_FP32": fp32,
                        "independent_float64": f64,
                    }
                    scored[policy, fixture["id"], 0] = row
                    rows.append(row)
                elif fixture["kind"] == "analytic":
                    p, t = [
                        linear_rgb(v, host["wb"], host["matrix"]) for v in (pred, host["target"])
                    ]
                    if fixture["signal_kind"] == "carrier":
                        values = carrier_metrics(p, t, fixture["cases"][0]["period"])
                        kind = (
                            "adc-carrier"
                            if fixture["condition"]["name"] == "adc-only"
                            else "weak-noisy-carrier"
                        )
                    else:
                        values, kind = flat_metrics(p, t), "flat"
                    for j, case in enumerate(fixture["cases"]):
                        row = {
                            "model": label,
                            "policy": policy,
                            "fixture": fixture["id"],
                            "case": case,
                            "condition": fixture["condition"],
                            "kind": kind,
                            "RGB": capture["RGB"],
                            "metrics": {k: float(v[j]) for k, v in values.items()},
                        }
                        if kind == "adc-carrier":
                            row["duplicate_original_draw_labels"] = [0, 1, 2, 3]
                        scored[policy, fixture["id"], j] = row
                        rows.append(row)
            for policy in POLICIES[1:]:
                differences.append(
                    {
                        "model": label,
                        "policy": policy,
                        "fixture": fixture["id"],
                        **physical_difference(predictions[policy], predictions["fp32"]),
                    }
                )
        base, plus = plan["fixtures"][-2:]
        for policy in POLICIES:
            pred = prediction(captures[policy, base["id"]]["RGB"], (4, 3, 256, 256))
            other = prediction(captures[policy, plus["id"]]["RGB"], pred.shape)
            quantized = np.rint(np.clip(pred, 0, 1).astype(np.float64) * 65535).astype(np.uint16)
            for j, pattern in enumerate(base["patterns"]):
                codes = int(np.unique(quantized[j]).size)
                response = float(np.sqrt(np.mean((other[j].astype(np.float64) - pred[j]) ** 2)))
                ramps.append(
                    {
                        "model": label,
                        "policy": policy,
                        "pattern": pattern,
                        "codes": codes,
                        "one_DN_response_RMS": response,
                        "passed": codes > 256 and response > 0,
                    }
                )
        for policy in POLICIES[1:]:
            gates, deltas = [], []
            for (p, fixture_id, j), row in scored.items():
                if p != policy:
                    continue
                baseline = scored["fp32", fixture_id, j]
                if row["kind"] == "photo":
                    canonical_gate = comparison_gates(
                        "photo", baseline["canonical_FP32"], row["canonical_FP32"]
                    )
                    independent_gate = comparison_gates(
                        "photo", baseline["independent_float64"], row["independent_float64"]
                    )
                    result = {
                        "canonical_FP32": canonical_gate,
                        "independent_float64": independent_gate,
                        "gate_decisions_agree": canonical_gate == independent_gate,
                    }
                    passed = all(canonical_gate.values()) and all(independent_gate.values())
                else:
                    result = comparison_gates(row["kind"], baseline["metrics"], row["metrics"])
                    passed = all(result.values())
                    deltas.append(
                        {
                            "fixture": fixture_id,
                            "case": row["case"],
                            "kind": row["kind"],
                            "delta": {
                                k: row["metrics"][k] - baseline["metrics"][k]
                                for k in row["metrics"]
                            },
                        }
                    )
                gates.append(
                    {
                        "fixture": fixture_id,
                        "case_index": j,
                        "kind": row["kind"],
                        "gates": result,
                        "passed": bool(passed),
                    }
                )
            ramp_pass = all(
                r["passed"]
                for r in ramps
                if r["model"] == label and r["policy"] in ("fp32", policy)
            )
            visible_pass = findings[label, policy]["no_visible_new_artifact"]
            policy_results.append(
                {
                    "model": label,
                    "policy": policy,
                    "gates": gates,
                    "analytic_deltas": deltas,
                    "native_artifact_screen_passed": visible_pass,
                    "ramp_passed": ramp_pass,
                    "finite_screen_passed": bool(
                        visible_pass and ramp_pass and all(g["passed"] for g in gates)
                    ),
                }
            )
        timing = model["timings"]
        first_calls = [r for r in timing if r["kind"] == "first-policy-call-in-this-process"]
        if (
            len(timing) != 15
            or len(first_calls) != 3
            or {r["policy"] for r in first_calls} != set(POLICIES)
            or any(
                not r["includes_dtype_hooks_and_checks"]
                or not np.isfinite(r["seconds"])
                or r["seconds"] <= 0
                for r in first_calls
            )
        ):
            raise ValueError("Expected one finite instrumented first call per policy/model")
        samples = [r for r in timing if r["kind"] == "synchronized-resident-unhooked-sample"]
        if len(samples) != 12 or sorted(r["sample"] for r in samples) != list(range(12)):
            raise ValueError("Expected all twelve fixed resident timing samples")
        for policy in POLICIES:
            group = [r for r in samples if r["policy"] == policy]
            if len(group) != 4:
                raise ValueError("Expected exactly four samples per policy/model")
            first = prediction(captures[policy, plan["fixtures"][0]["id"]]["RGB"], (4, 3, 512, 512))
            repeats = []
            for sample in group:
                saved = prediction(sample["RGB"], first.shape)
                equal = np.array_equal(first, saved)
                if (
                    bool(equal) != sample["byte_equal_first_capture"]
                    or not np.isfinite(sample["seconds"])
                    or sample["seconds"] <= 0
                ):
                    raise ValueError("Resident timing repeat/finite-duration evidence differs")
                repeats.append(
                    {
                        "sample": sample["sample"],
                        "RGB": sample["RGB"],
                        "byte_equal_first_capture": bool(equal),
                        **physical_difference(saved, first),
                    }
                )
            seconds = [r["seconds"] for r in group]
            timing_rows.append(
                {
                    "model": label,
                    "policy": policy,
                    "seconds": seconds,
                    "median_seconds": float(np.median(seconds)),
                    "minimum_seconds": min(seconds),
                    "maximum_seconds": max(seconds),
                    "repeat_checks": repeats,
                    "first_calls": [
                        r
                        for r in timing
                        if r["kind"] == "first-policy-call-in-this-process"
                        and r["policy"] == policy
                    ],
                }
            )
    if len(rows) != 588 or len(ramps) != 24 or len(differences) != 116:
        raise ValueError("Fixed scalar observation coverage is incomplete")
    for row in timing_rows:
        baseline = next(
            r for r in timing_rows if r["model"] == row["model"] and r["policy"] == "fp32"
        )
        row["median_speedup_fraction"] = baseline["median_seconds"] / row["median_seconds"] - 1
    groups = {}
    for row in rows:
        if row["kind"] == "photo":
            continue
        case = row["case"]
        key = (
            row["model"],
            row["policy"],
            row["kind"],
            case["level"],
            case["contrast"],
            case["period"],
        )
        groups.setdefault(key, []).append(row)
    means = [
        {
            "model": k[0],
            "policy": k[1],
            "kind": k[2],
            "level": k[3],
            "contrast": k[4],
            "period": k[5],
            "unique_observations": len(v),
            "metrics": {
                name: float(np.mean([r["metrics"][name] for r in v])) for name in v[0]["metrics"]
            },
        }
        for k, v in groups.items()
    ]
    if len(means) != 90 or torch.cuda.is_initialized():
        raise ValueError("Expected all fixed analytic groups and CPU-only review")
    save_new(
        output / "result.json",
        {
            "status": "completed-fixed-mature-precision-scalar-screen",
            "protocol": ref(protocol_path),
            "GPU_receipt": ref(receipt_path),
            "native_render": ref(index_path),
            "actual_manual_viewing_before_scalars": ref(manual_path),
            "driver": ref(__file__),
            "per_observation": rows,
            "group_means": means,
            "policy_screens": policy_results,
            "physical_differences_unclipped_DN16": differences,
            "native_ramps": ramps,
            "resident_timings": timing_rows,
            "CUDA_initialized": torch.cuda.is_initialized(),
            "new_network_forwards": 0,
            "scope": "Finite existing-weight screen only. All 96 unique analytic observations retained per method; 48 ADC observations carry 192 historical duplicate labels. Photo metrics use full native256 outputs; analytic ROI is native160 at48,48. GFX ISO100 is not scored. FP32 production and independent float64 photo gate decisions must both pass. Timing is resident B4/native512 only, excludes export/full-frame inference. No model/default change, automatic continuation, quality-population, SOTA or100MP/10s claim.",
        },
    )
    guard(protocol)
    guard(plan)
    print(
        {
            "status": "completed-fixed-mature-precision-scalar-screen",
            "rows": len(rows),
            "native_ramps": len(ramps),
        }
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    for name in ("protocol", "GPU_receipt", "render_index", "manual_viewing", "output"):
        parser.add_argument(name, type=Path)
